/* ============================== ENCYCLOPEDIA ============================== */
const ENC_CATS=[['bas',(LANG_EN?"Getting started":'Başlangıç')],['urun',(LANG_EN?"Products":'Ürünler')],['pazar',(LANG_EN?"Market":'Pazar')],['ekip',(LANG_EN?"Team":'Ekip')],['uretim',(LANG_EN?"Manufacturing and infrastructure":'Üretim ve altyapı')],['arge',(LANG_EN?"Research and legal":'Araştırma ve hukuk')],['finans',(LANG_EN?"Finance":'Finans')],['diger',(LANG_EN?"Gaming":'Oyun')]];
const ENC=[
 {id:'goal',c:'bas',t:(LANG_EN?"Goal of the game":'Oyunun amacı'),go:'dash',b:(LANG_EN?`<p>You start in a garage in 2015 with $150K and a single founder. You grow your company by launching products, from apps to operating systems and from processors to game consoles.</p><ul><li><b>Free play</b> has no goals; grow as much as you like.</li><li><b>Scenarios</b> come with a set duration and goals; you earn 1–3 stars based on your speed.</li><li>If your cash is negative for three months in a row, the company goes bankrupt.</li></ul>`:`<p>2015'te bir garajda, $150K ve tek kurucuyla başlarsın. Uygulamadan işletim sistemine, işlemciden oyun konsoluna kadar ürünler çıkarıp şirketini büyütürsün.</p><ul><li><b>Serbest oyun</b>da hedef yoktur; istediğin kadar büyürsün.</li><li><b>Senaryolar</b> belirli süre ve hedeflerle gelir; hızına göre 1–3 yıldız alırsın.</li><li>Nakit üç ay üst üste eksiye düşerse şirket iflas eder.</li></ul>`)},
 {id:'first',c:'bas',t:(LANG_EN?"First steps":'İlk adımlar'),go:'team',b:(LANG_EN?`<ol><li>Hire a designer and a developer in Team → Team & candidates.</li><li>Start your first <b>mobile app</b> in Product → Development; with ad revenue, it's the fastest start.</li><li>Once the app is out, build a <b>web service</b> and add server racks from Infrastructure.</li><li>Hire a researcher and unlock new categories in Research.</li><li>As cash grows, move to a bigger office; a bigger office attracts more talented candidates.</li></ol>`:`<ol><li>Ekip → Ekip ve adaylar bölümünden bir tasarımcı ve bir yazılımcı işe al.</li><li>Ürün → Geliştirme bölümünde ilk <b>mobil uygulamanı</b> başlat; reklam geliriyle en hızlı başlangıç budur.</li><li>Uygulama çıkınca bir <b>web servisi</b> yap ve Altyapı'dan sunucu rafı ekle.</li><li>Bir araştırmacı alıp Araştırma'dan yeni kategorilerin kilidini aç.</li><li>Nakit büyüdükçe daha büyük ofise taşın; büyük ofis daha yetenekli adayları çeker.</li></ol>`)},
 {id:'keys',c:'bas',t:(LANG_EN?"Speed and shortcuts":'Hız ve kısayollar'),b:(LANG_EN?`<ul><li><b>Space</b>: pauses or resumes the game.</li><li><b>1–6</b>: switch between main sections (Company, Product, Team, R&D, Market, Finance).</li><li>Speed buttons in the top bar: at normal speed one day takes 1 second, at the fastest about 0.1 seconds.</li><li>Use the arrow keys to move between months in charts.</li><li>In office edit mode, <b>R</b> rotates furniture and <b>Esc</b> exits.</li><li>The <b>?</b> key opens this encyclopedia.</li></ul>`:`<ul><li><b>Boşluk</b>: oyunu duraklatır ya da başlatır.</li><li><b>1–6</b>: ana bölümler arasında geçiş (Şirket, Ürün, Ekip, Ar-Ge, Pazar, Finans).</li><li>Üst çubuktaki hız düğmeleri: normal hızda bir gün 1 saniye, en hızlıda yaklaşık 0,1 saniye.</li><li>Grafiklerde ok tuşlarıyla aylar arasında gezebilirsin.</li><li>Ofis düzenleme modunda <b>R</b> mobilyayı döndürür, <b>Esc</b> çıkar.</li><li><b>?</b> tuşu bu ansiklopediyi açar.</li></ul>`)},
 {id:'save',c:'bas',t:(LANG_EN?"Save & settings":'Kayıt ve ayarlar'),go:'fin:kayit',b:(LANG_EN?`<p>The game autosaves every month. Finance → Save & settings has three save slots, save export/import, and sound, music, day-night and season settings.</p>`:`<p>Oyun her ay otomatik kaydedilir. Finans → Kayıt ve ayarlar bölümünde üç kayıt yuvası, kaydı dışa/içe aktarma, ses, müzik, gece-gündüz ve mevsim ayarları bulunur.</p>`)},

 {id:'cats',c:'urun',t:(LANG_EN?"Product categories":'Ürün kategorileri'),go:'dev',b:(LANG_EN?`<ul><li><b>Mobile app</b>: ad revenue, the cheapest start.</li><li><b>Web service</b>: monthly subscription, needs servers.</li><li><b>Operating system</b>: licensed to other companies; free on your own devices.</li><li><b>Processor</b>: made at a foundry or in your own chip fab.</li><li><b>Phone, computer, wearable, game console</b>: parts are sourced and assembled.</li><li><b>AI service</b>: a fast-growing subscription market; needs lots of servers.</li><li><b>VR/AR headset</b>: a device market that starts small and grows in the 2020s; you choose optics and battery, and it needs an operating system.</li><li><b>Vehicle software</b>: monthly per-vehicle license to automakers. Buggy software leads to costly recalls; driver-assist research lowers the risk.</li><li><b>Smart home</b>: cheap, high-volume devices (plugs, cameras, speakers, thermostats). Every device sold joins the installed base; if you have a web service or AI service, each device brings a monthly cloud subscription. Without cybersecurity research your devices can become a botnet.</li><li><b>Quantum computer</b>: the longest moonshot. Three stages of expensive research (very costly before 2022, 2026 and 2029), a huge development team, millions of dollars per system; the field test sets the score between 70% and 135%. The market opens in the 2030s. Having a quantum system on the market speeds up your research by 10%. The first powerful system declares <b>quantum supremacy</b>; once powerful quantum computers spread, "Q-Day" arrives and cyberattacks rise against companies without Post-Quantum Cryptography research.</li><li><b>Robotics</b>: a moonshot. A long, expensive research chain and a big development team; when done, the field test sets the score between 80% and 125%. The market grows fast after 2025.</li></ul><p>Most categories are unlocked by research. Specialist rivals emerge in new markets over time.</p>`:`<ul><li><b>Mobil uygulama</b>: reklam geliri, en ucuz başlangıç.</li><li><b>Web servisi</b>: aylık abonelik, sunucu ister.</li><li><b>İşletim sistemi</b>: diğer firmalara lisans; kendi cihazında bedava.</li><li><b>İşlemci</b>: dökümhane ya da kendi çip fabrikanda üretilir.</li><li><b>Telefon, bilgisayar, giyilebilir, oyun konsolu</b>: parça tedarik edilip montajla üretilir.</li><li><b>Yapay zekâ hizmeti</b>: hızla büyüyen abonelik pazarı; çok sunucu ister.</li><li><b>VR/AR gözlük</b>: küçük başlayıp 2020'lerde büyüyen cihaz pazarı; optik ve batarya seçilir, işletim sistemi gerekir.</li><li><b>Araç yazılımı</b>: otomobil üreticilerine araç başına aylık lisans. Hatalı yazılım pahalı geri çağırmalara yol açar; sürüş destek araştırması riski azaltır.</li><li><b>Akıllı ev</b>: ucuz, çok satan cihazlar (priz, kamera, hoparlör, termostat). Satılan her cihaz kurulu tabana eklenir; web servisin ya da yapay zekâ hizmetin varsa her cihaz ayda bulut aboneliği getirir. Siber güvenlik araştırması olmadan cihazların botnete dönüşebilir.</li><li><b>Kuantum bilgisayar</b>: en uzun ay projesi. Üç aşamalı pahalı araştırma (2022, 2026 ve 2029'dan önce çok pahalı), dev geliştirme ekibi, sistem başına milyonlarca dolar; saha testi puanı %70–135 arasında belirler. Pazar 2030'larda açılır. Piyasada kuantum sistemin varsa araştırman %10 hızlanır. İlk güçlü sistem <b>kuantum üstünlüğü</b> ilan eder; güçlü kuantum bilgisayarlar yaygınlaşınca "Q Günü" gelir ve Kuantum Sonrası Şifreleme araştırması olmayan şirketlere siber saldırılar artar.</li><li><b>Robotik</b>: ay projesi. Uzun ve pahalı araştırma zinciri, büyük geliştirme ekibi; bitince saha testi puanı %80 ile %125 arasında belirler. Pazar 2025 sonrası hızla büyür.</li></ul><p>Çoğu kategori bir araştırmayla açılır. Yeni pazarlarda zamanla uzman rakipler kurulur.</p>`)},
 {id:'score',c:'urun',t:(LANG_EN?"Score and freshness":'Puan ve güncellik'),go:'prod',b:(LANG_EN?`<p>Every product has a <b>score</b>, set by your team's skill, your research and the parts you choose. The <b>market standard</b> rises every year as technology advances.</p><p><b>Freshness</b> = product score ÷ today's standard. Your product ages over time; once it drops below 85% it loses customers fast. Either update it or release a new generation.</p>`:`<p>Her ürünün bir <b>puanı</b> vardır; ekibinin yeteneği, araştırmaların ve seçtiğin parçalar belirler. <b>Pazar standardı</b> teknoloji ilerledikçe her yıl yükselir.</p><p><b>Güncellik</b> = ürün puanı ÷ bugünkü standart. Ürünün zamanla eskir; %85'in altına düşen ürün hızla müşteri kaybeder. Ya güncelleme yap ya da yeni nesil çıkar.</p>`)},
 {id:'price',c:'urun',t:(LANG_EN?"Price and press score":'Fiyat ve basın puanı'),b:(LANG_EN?`<p>Each product gets a <b>suggested (fair) price</b>; pricing high lowers appeal, pricing low lowers profit. You can change the price anytime in the Products table.</p><p>At launch the press gives a score from 1 to 10, based on freshness and price/performance. 8 or higher boosts sales for 60 days and grows your brand; below 5 hurts.</p>`:`<p>Her ürün için bir <b>önerilen (adil) fiyat</b> hesaplanır; pahalı fiyat çekiciliği düşürür, ucuz fiyat kârı. Fiyatı Ürünler tablosundan istediğin zaman değiştirebilirsin.</p><p>Çıkışta basın 1–10 arası puan verir: güncellik ve fiyat/performans belirler. 8 ve üstü 60 gün satışları artırır, markayı büyütür; 5'in altı zarar verir.</p>`)},
 {id:'launch',c:'urun',t:(LANG_EN?"Launch events":'Lansman etkinlikleri'),go:'dev',b:(LANG_EN?`<p>You can plan a press conference, stage event or big keynote for an ongoing project. The event boosts appeal for 60 days; big events are expensive and risk leaks and demo crashes. A launch that lands in peak season is more effective. If the product isn't ready in time, the event is postponed at extra cost.</p><p><b>Launch stage.</b> On the day of a stage event or keynote, you take the stage yourself: you make choices in four steps — opening, featured highlight, live demo and closing. The crowd's excitement (0–100) changes the launch's appeal effect between ×0.85 and ×1.25 and affects your brand; excitement above 75 adds +0.3 to the press score, below 30 lowers it. To pick the right feature, check the product card: freshness, value for price, press expectations and ecosystem. The live demo's crash risk depends on the product's bug count and tech debt. "One more thing…" only works if you have another product in development. Your marketers help with rehearsal; leaks lower the starting excitement. If you skip the stage or turn it off in settings, the launch is presented automatically as before.</p>`:`<p>Devam eden projeye basın toplantısı, sahne etkinliği ya da dev keynote planlayabilirsin. Etkinlik 60 gün çekiciliği artırır; büyük etkinlik pahalıdır, sızıntı ve demo çökmesi riski taşır. Yoğun sezona denk gelen lansman daha etkilidir. Ürün yetişmezse etkinlik ertelenir ve ek masraf çıkar.</p><p><b>Lansman sahnesi.</b> Sahne etkinliği ve keynote günü sahneye sen çıkarsın: açılış, öne çıkan özellik, canlı demo ve kapanış olmak üzere dört adımda seçim yaparsın. Salonun coşkusu (0–100) lansmanın çekicilik etkisini ×0,85 ile ×1,25 arasında değiştirir, markayı etkiler; 75 üstü coşku basın puanını +0,3 artırır, 30 altı düşürür. Doğru özelliği seçmek için ürün kartına bak: güncellik, fiyatın değeri, basın beklentisi ve ekosistem. Canlı demonun çökme riski ürünün hata sayısına ve teknik borcuna bağlıdır. "Bir şey daha…" ancak geliştirmede başka bir ürünün varsa işe yarar. Pazarlamacıların provaya katkı sağlar, sızıntı başlangıç coşkusunu düşürür. Sahneyi atlarsan ya da ayarlardan kapatırsan lansman eskisi gibi otomatik sunulur.</p>`)},
 {id:'update',c:'urun',t:(LANG_EN?"Product updates":'Ürün güncellemeleri'),go:'prod',b:(LANG_EN?`<p>The <b>Update</b> button in the Products table refreshes a product without releasing a new one; customers and market share stay put.</p><ul><li><b>Minor update (x.1)</b>: ~25% of the work; reduces bugs and raises the score a little. Its effect shrinks with each consecutive update.</li><li><b>Major update (x+1.0)</b>: ~55% of the work; brings the product up to today's technology. Hardware switches to the best processor and parts, 30% of the tooling cost is paid, and the press rates it again.</li></ul>`:`<p>Ürünler tablosundaki <b>Güncelle</b> düğmesiyle yeni ürün çıkarmadan ürünü tazelersin; müşteriler ve pazar payı yerinde kalır.</p><ul><li><b>Küçük güncelleme (x.1)</b>: işin ~%25'i; hataları azaltır, puanı biraz artırır. Art arda yapıldıkça etkisi azalır.</li><li><b>Büyük güncelleme (x+1.0)</b>: işin ~%55'i; ürünü bugünün teknolojisine taşır. Donanımda en iyi işlemciye ve parçalara geçilir, kalıp masrafının %30'u ödenir; basın yeniden puan verir.</li></ul>`)},
 {id:'pricing',c:'urun',t:(LANG_EN?"Pricing models":'Fiyatlandırma modelleri'),go:'prod',b:(LANG_EN?`<p>For apps, web services and AI products you can choose a model (at most one change per month):</p><ul><li><b>Free with ads</b> (app): small ad revenue per user.</li><li><b>Freemium</b>: free entry draws far more users; some of them pay. Discerning customers pay much more often. In services, free users also use servers, and a network effect builds over time.</li><li><b>Paid subscription</b> (app): fewer users, but they pay.</li><li><b>Tiered</b> (service): Basic 60%, Pro 100%, Enterprise 200% price; each segment sees its own plan. An enterprise sales team costs money every month.</li></ul><p>In subscriptions, <b>churn</b> depends on satisfaction and freshness; high churn lowers appeal.</p>`:`<p>Uygulama, web servisi ve yapay zekâ ürünlerinde model seçebilirsin (ayda en fazla bir değişiklik):</p><ul><li><b>Reklamlı ücretsiz</b> (uygulama): kullanıcı başı küçük reklam geliri.</li><li><b>Freemium</b>: ücretsiz giriş çok daha fazla kullanıcı çeker; bir kısmı öder. Seçici kitle çok daha sık öder. Serviste ücretsizler de sunucu kullanır, zamanla ağ etkisi oluşur.</li><li><b>Ücretli abonelik</b> (uygulama): az ama ödeyen kullanıcı.</li><li><b>Katmanlı</b> (servis): Temel %60, Pro %100, Kurumsal %200 fiyat; her kitle kendi paketini görür. Kurumsal satış ekibi aylık gider ister.</li></ul><p>Aboneliklerde <b>müşteri kaybı</b> memnuniyet ve güncelliğe bağlıdır; yüksek kayıp çekiciliği düşürür.</p>`)},
 {id:'support',c:'urun',t:(LANG_EN?"Bugs and customer support":'Hatalar ve müşteri desteği'),go:'prod',b:(LANG_EN?`<p>Products accumulate bugs over time; bugs generate support tickets. Support specialists resolve tickets. Pending tickets lower <b>satisfaction</b>; low satisfaction erodes appeal and brand. You can assign developers or hardware engineers to a product for maintenance.</p>`:`<p>Ürünler zamanla hata biriktirir; hatalar destek talebi doğurur. Destek uzmanları talepleri çözer. Bekleyen talepler <b>memnuniyeti</b> düşürür; düşük memnuniyet çekiciliği ve markayı aşındırır. Bakım için ürüne yazılımcı ya da donanım mühendisi atayabilirsin.</p>`)},
 {id:'eco',c:'urun',t:(LANG_EN?"Ecosystem":'Ekosistem'),go:'prod',b:(LANG_EN?`<p>Your products support each other; every active link gives all your products +5% appeal. Links include using your own processor in your own device, building an app store on your own OS, phone + wearable, and AI + device. Every console sold brings game license revenue, and every device sold with your own OS brings store revenue.</p>`:`<p>Ürünlerin birbirini destekler; her aktif bağlantı bütün ürünlerine +%5 çekicilik verir. Kendi işlemcini kendi cihazında kullanmak, kendi OS'unla uygulama mağazası kurmak, telefon + giyilebilir, yapay zekâ + cihaz gibi bağlantılar vardır. Satılan her konsol oyun lisans geliri, kendi OS'unla satılan her cihaz mağaza geliri getirir.</p>`)},

 {id:'share',c:'pazar',t:(LANG_EN?"Market share and appeal":'Pazar payı ve çekicilik'),go:'market',b:(LANG_EN?`<p>Each month, demand in each category is split according to products' <b>appeal</b>. Appeal is set by freshness (score³), price fairness, brand, press impact, campaigns, ecosystem and satisfaction. Customers who like nothing buy nothing.</p>`:`<p>Her ay her kategorideki talep, ürünlerin <b>çekiciliğine</b> göre paylaşılır. Çekiciliği güncellik (puan³), fiyat uygunluğu, marka, basın etkisi, kampanyalar, ekosistem ve memnuniyet belirler. Kimseyi beğenmeyen müşteri hiç almaz.</p>`)},
 {id:'segment',c:'pazar',t:(LANG_EN?"Customer segments":'Müşteri segmentleri'),go:'market:pazarlama',b:(LANG_EN?`<p>In every market, demand splits into three segments:</p><ul><li><b>Budget</b>: very price-sensitive, cares little about brand.</li><li><b>Mainstream</b>: balances price and quality.</li><li><b>Discerning</b> (enthusiast or enterprise): looks at quality and brand, accepts a 35% higher price. Enterprise customers care about support satisfaction, enthusiasts about press score.</li></ul><p>A cheap product wins budget buyers; a pricey, superior product wins discerning ones.</p>`:`<p>Her pazarda talep üç kitleye bölünür:</p><ul><li><b>Fiyat odaklı</b>: fiyata çok duyarlı, markayı az önemser.</li><li><b>Ana akım</b>: fiyat ve kaliteyi dengeler.</li><li><b>Seçici</b> (meraklı ya da kurumsal): kaliteye ve markaya bakar, %35 daha yüksek fiyatı kabul eder. Kurumsal müşteri destek memnuniyetine, meraklı basın puanına bakar.</li></ul><p>Ucuz ürünle fiyat odaklıları, pahalı ve üstün ürünle seçicileri toplarsın.</p>`)},
 {id:'mkt',c:'pazar',t:(LANG_EN?"Marketing channels":'Pazarlama kanalları'),go:'market:pazarlama',b:(LANG_EN?`<p>You set a monthly budget for six channels: social media, search ads, influencers, TV, trade shows and retail displays. Each channel is strong in different categories and segments. More budget means more reach but diminishing returns; the "suggested" budget gives ~63% reach and grows with revenue. TV permanently grows your brand, trade shows your regional awareness. There is also a one-time "Ad" campaign per product.</p>`:`<p>Altı kanala aylık bütçe ayırırsın: sosyal medya, arama reklamı, fenomenler, TV, fuarlar, perakende vitrin. Her kanal farklı kategori ve kitlelerde güçlüdür. Bütçe arttıkça erişim artar ama getiri azalır; "önerilen" bütçe ~%63 erişim sağlar ve ciroyla büyür. TV markayı, fuarlar bölge bilinirliğini kalıcı büyütür. Ürün bazında tek seferlik "Reklam" kampanyası da vardır.</p>`)},
 {id:'region',c:'pazar',t:(LANG_EN?"Regions and branches":'Bölgeler ve şubeler'),go:'market:bolge',b:(LANG_EN?`<p>Turkey is your home market. You enter Europe, North America, Asia and Latin America for an entry fee plus monthly operating costs. In regions you haven't entered, software is 25% and hardware 70% less appealing. Europe requires data protection compliance, North America a brand of 20+; in Asia hardware faces a 15% tariff unless you have a factory there. Branches provide sales, support and R&D in their region.</p>`:`<p>Türkiye ev pazarındır. Avrupa, Kuzey Amerika, Asya ve Latin Amerika'ya giriş ücreti ve aylık işletme gideriyle girersin. Girmediğin bölgede yazılım %25, donanım %70 daha az çekicidir. Avrupa'da veri koruma uyumu, Kuzey Amerika'da marka 20+ gerekir; Asya'da bölgede fabrikan yoksa donanıma %15 gümrük vardır. Şubeler bölgede satış, destek ve Ar-Ge sağlar.</p>`)},
 {id:'season',c:'pazar',t:(LANG_EN?"Seasons":'Mevsimler'),go:'market:sezon',b:(LANG_EN?`<p>Demand fluctuates through the year: hardware peaks in November–December (consoles especially), summer is slow, and computer demand rises at back-to-school. Timing a launch for peak season amplifies its effect.</p>`:`<p>Talep yıl içinde dalgalanır: donanım Kasım–Aralık'ta zirve yapar (konsol özellikle), yaz durgundur; okula dönüşte bilgisayar talebi artar. Lansmanı yoğun sezona denk getirmek etkisini büyütür.</p>`)},
 {id:'rival',c:'pazar',t:(LANG_EN?"Rivals and their strategies":'Rakipler ve stratejileri'),go:'market',b:(LANG_EN?`<p>Every rival has a strategy:</p><ul><li><b>Price cutter</b>: cheap products, never shies from a price war.</li><li><b>Balanced</b>: market price.</li><li><b>Premium</b>: expensive but superior, doesn't cut prices.</li><li><b>Fast follower</b>: copies your hit product within 2–4 months.</li></ul><p>Rivals adjust prices monthly, update their products, launch counter-campaigns against your launches, enter attractive markets and pull out of ones where they can't hold on. You can buy a struggling rival.</p>`:`<p>Her rakibin bir stratejisi vardır:</p><ul><li><b>Fiyat kırıcı</b>: ucuz ürünler, fiyat savaşından kaçmaz.</li><li><b>Dengeli</b>: piyasa fiyatı.</li><li><b>Premium</b>: pahalı ama üstün, fiyat kırmaz.</li><li><b>Hızlı takipçi</b>: başarılı ürününü 2–4 ay içinde kopyalar.</li></ul><p>Rakipler fiyatlarını aylık ayarlar, ürünlerini günceller, lansmanına karşı kampanya başlatır, cazip pazarlara girer, tutunamadıklarından çekilir. Zor durumdaki rakibi satın alabilirsin.</p>`)},
 {id:'deal',c:'pazar',t:(LANG_EN?"Partnerships":'Ortaklıklar'),go:'market:ortak',b:(LANG_EN?`<p>You can make deals with rivals, such as operating system licenses or buying and selling processors. Whether an offer is accepted depends on its price and your relationship; if you can't meet a production commitment, you pay a penalty.</p>`:`<p>Rakiplerle işletim sistemi lisansı, işlemci alım-satımı gibi anlaşmalar yapabilirsin. Teklifin kabul ihtimali fiyatına ve ilişkine bağlıdır; üretim taahhüdünü karşılayamazsan ceza ödersin.</p>`)},

 {id:'hire',c:'ekip',t:(LANG_EN?"Roles and hiring":'Roller ve işe alım'),go:'team',b:(LANG_EN?`<ul><li><b>Developer, designer, hardware engineer</b>: produce work on projects.</li><li><b>Researcher</b>: research points.</li><li><b>Marketer</b>: brand and regional awareness.</li><li><b>Operations</b>: supply lead times, factory defect rate.</li><li><b>Support</b>: customer tickets.</li><li><b>Security</b>: cybersecurity.</li></ul><p>The candidate list refreshes monthly; a big office and a strong brand attract more talented candidates.</p>`:`<ul><li><b>Yazılımcı, tasarımcı, donanım mühendisi</b>: projelerde iş üretir.</li><li><b>Araştırmacı</b>: araştırma puanı.</li><li><b>Pazarlamacı</b>: marka ve bölge bilinirliği.</li><li><b>Operasyon</b>: tedarik süreleri, fabrika hata oranı.</li><li><b>Destek</b>: müşteri talepleri.</li><li><b>Güvenlik</b>: siber güvenlik.</li></ul><p>Aday listesi her ay yenilenir; büyük ofis ve güçlü marka daha yetenekli aday getirir.</p>`)},
 {id:'morale',c:'ekip',t:(LANG_EN?"Morale and energy":'Moral ve enerji'),go:'team',b:(LANG_EN?`<p>Morale is affected by salary, pace, perks, manager, teammates, layoffs and successes. Employees below 30 may resign. Energy drains with work; an employee who runs out goes on burnout leave. Choosing the pace (relaxed / normal / intense) is a trade-off between output and fatigue.</p>`:`<p>Moral maaş, tempo, yan haklar, yönetici, ekip arkadaşları, işten çıkarmalar ve başarılardan etkilenir. 30'un altında kalan çalışan istifa edebilir. Enerji çalıştıkça azalır; biten çalışan tükenmişlik iznine çıkar. Tempo seçimi (rahat / normal / yoğun) üretimle yorgunluk arasında takastır.</p>`)},
 {id:'career',c:'ekip',t:(LANG_EN?"Levels and promotion":'Kademeler ve terfi'),go:'team:yonetim',b:(LANG_EN?`<p>Employees gain experience and rise through Junior → Specialist → Senior → Manager levels; each level raises output but also salary expectations. An employee who becomes a manager strengthens their own team. Employees whose promotion is delayed lose morale.</p>`:`<p>Çalışanlar deneyim kazanıp Junior → Uzman → Kıdemli → Yönetici kademelerinde yükselir; her kademe üretimi artırır ama maaş beklentisini de yükseltir. Yönetici olan çalışan kendi ekibini güçlendirir. Terfi bekletilen çalışanın morali düşer.</p>`)},
 {id:'want',c:'ekip',t:(LANG_EN?"Employee requests":'Çalışan istekleri'),go:'office',b:(LANG_EN?`<p>Every now and then employees ask for a specific item on their floor: a potted plant, an espresso machine, a bookshelf, a couch, a foosball table, an aquarium and so on. What they ask for depends on their personality: social people want games and lounge items, hard workers want coffee and a sleep pod, calm people want plants and aquariums, fast learners want a bookshelf. As the office grows they may ask for pricier things.</p><ul><li>An employee with a request has a heart bubble over their head in the office. It also shows on their card and in the <b>Employee requests</b> section of the office.</li><li><b>Buy and place</b> puts the item in the nearest free spot on the employee's floor; it uses one from storage if you have it. You can also place it yourself in Edit mode.</li><li>If the request is met within 60 days, morale rises by 8 right away and by 3 for the next 4 months. If not, morale stays down by 4 for 4 months.</li></ul>`:`<p>Çalışanlar zaman zaman kendi katlarına somut bir eşya ister: saksı bitkisi, espresso makinesi, kitaplık, kanepe, langırt, akvaryum gibi. Ne istedikleri kişiliklerine bağlıdır: sosyal olanlar oyun ve dinlenme eşyaları, çalışkanlar kahve ve uyku kapsülü, sakinler bitki ve akvaryum, hızlı öğrenenler kitaplık ister. Ofis büyüdükçe daha pahalı şeyler isteyebilirler.</p><ul><li>İsteği olan çalışanın başında ofiste kalp balonu belirir. Çalışan kartında ve ofisteki <b>Çalışan istekleri</b> bölümünde görünür.</li><li><b>Satın al ve yerleştir</b> eşyayı çalışanın katında ona en yakın boş yere koyar; depodaki eşya varsa onu kullanır. Eşyayı Düzenle modunda kendin de yerleştirebilirsin.</li><li>İstek 60 gün içinde karşılanırsa moral hemen +8, sonraki 4 ay +3 olur. Karşılanmazsa 4 ay boyunca −4 moral kalır.</li></ul>`)},
 {id:'teamd',c:'ekip',t:(LANG_EN?"Specialization, mentoring and careers":'Uzmanlık, mentorluk ve kariyer'),go:'office',b:(LANG_EN?`<p>Click an employee in the office to open the <b>Career</b> section of their card.</p><ul><li><b>Specialization:</b> Developers, designers and hardware engineers who reach level 1 can specialize in a product attribute (performance, design, security and so on). If the project's design focus puts 3–4 points on that attribute, their output rises 5–10% and the press sub-score for that attribute goes up; at 0–1 points it drops 3%. It can be changed once every 180 days.</li><li><b>Mentoring:</b> Assign a level 2 employee or a manager in the same role as a junior's mentor. The junior gains 50% more experience and improves skill faster; the mentor produces 3% less per mentee. A mentor can have at most 2 mentees.</li><li><b>Raise negotiations:</b> Employees paid well below market whose morale is slipping will ask for a raise. You can accept, counter or refuse; money-driven or key employees who are turned down may leave for a rival.</li><li><b>Career goal:</b> Two months after joining, every employee reveals a goal (becoming a manager, mentoring, training, working in a particular category, an acclaimed product). Reaching it keeps their morale high for a year; neglecting it for more than a year lowers it.</li><li><b>Key employee:</b> Employees who carry more than a third of their role's skill, or are among the two most skilled in their role with skill above 8.5, are rivals' favorite targets. A two-year retention bonus (4 months' salary) greatly reduces the risk that they leave.</li><li><b>Team chemistry:</b> The personalities on a project team raise or lower its speed by up to 10%. Helpful, leader and social employees and a senior–junior mix help; troublemakers, hard-worker–slacker and perfectionist–sloppy pairings, and overcrowded teams hurt. It shows on the project card.</li></ul>`:`<p>Ofiste bir çalışana tıklayınca kartında <b>Kariyer</b> bölümü açılır.</p><ul><li><b>Uzmanlık:</b> 1. kademeye çıkan yazılımcı, tasarımcı ve donanım mühendisi bir ürün niteliğinde uzmanlaşabilir (performans, tasarım, güvenlik gibi). Projenin tasarım odağında bu nitelik 3–4 puansa üretimi %5–10 artar ve basının o nitelikteki alt puanını yükseltir; 0–1 puansa %3 düşer. 180 günde bir değiştirilebilir.</li><li><b>Mentorluk:</b> Aynı roldeki 2. kademe ya da yönetici bir çalışanı gence mentor olarak ata. Gencin deneyimi %50, yetenek gelişimi daha hızlı artar; mentor kişi başı %3 daha az üretir. Bir mentorun en fazla 2 öğrencisi olur.</li><li><b>Maaş pazarlığı:</b> Maaşı piyasanın belirgin altında kalan ve morali düşen çalışanlar zam ister. Kabul edebilir, karşı teklif verebilir ya da reddedebilirsin; reddedilen para odaklı ya da kilit çalışanlar rakibe geçebilir.</li><li><b>Kariyer hedefi:</b> Her çalışanın işe girdikten iki ay sonra bir hedefi belli olur (yönetici olmak, mentorluk, eğitim, belirli bir kategoride çalışmak, övgü alan bir ürün). Hedefe ulaşınca morali bir yıl boyunca yüksek kalır; bir yıldan uzun ihmal edilirse düşer.</li><li><b>Kilit çalışan:</b> Rolünün yeteneğinin üçte birinden fazlasını taşıyan ya da rolündeki en yetenekli iki kişiden biri olup yeteneği 8,5'i aşan çalışanlar rakiplerin hedefidir. İki yıllık tutma primi (4 aylık maaş) ayrılma riskini büyük ölçüde azaltır.</li><li><b>Takım uyumu:</b> Projedeki ekibin kişilikleri hızı %10'a kadar artırır ya da düşürür. Yardımsever, lider ve sosyal çalışanlar ile kıdemli-genç karışımı iyi gelir; kavgacılar, çalışkan-tembel ve mükemmeliyetçi-dağınık eşleşmeleri ve çok kalabalık ekipler zarar verir. Proje kartında görünür.</li></ul>`)},
 {id:'training',c:'ekip',t:(LANG_EN?"Training & internships":'Eğitim ve staj'),go:'team:egitim',b:(LANG_EN?`<p>Online courses, certificate programs, conferences and leadership training raise your employees' skills. Partner with universities and intern candidates arrive every term; you can hire the good interns.</p>`:`<p>Online kurs, sertifika programı, konferans ve liderlik eğitimiyle çalışanların yeteneğini artırırsın. Üniversitelerle anlaşma yapınca her dönem stajyer adayları gelir; iyi stajyerleri işe alabilirsin.</p>`)},
 {id:'survey',c:'ekip',t:(LANG_EN?"Employee survey":'Çalışan anketi'),go:'team:sendika',b:(LANG_EN?`<p>Can be run at most once every 60 days. It scores pay, workload, management, environment, growth and belonging from 0–100 and shows the top complaints. You can promise a +10 improvement in one area within 4 months: keep it and morale rises, break it and morale drops. The survey also shows the tendency to unionize.</p>`:`<p>En az 60 günde bir yapılabilir. Maaş, iş yükü, yönetim, ortam, gelişim ve aidiyeti 0–100 puanlar; en çok şikâyet edilen konuları gösterir. Bir konuda 4 ay içinde +10 iyileşme sözü verebilirsin: tutarsan moral yükselir, tutamazsan düşer. Anket sendikalaşma eğilimini de gösterir.</p>`)},
 {id:'union',c:'ekip',t:(LANG_EN?"Union and strikes":'Sendika ve grev'),go:'team:sendika',b:(LANG_EN?`<p>In a company with more than 25 employees, low morale, below-market pay, an intense pace and layoffs create pressure to organize. If a union forms, collective bargaining happens every year; if you can't agree, members go on strike. During a strike members don't work, factories drop to 40% capacity, and your brand erodes. You can accept the demands, hire a mediator or wait for the strike fund to run out.</p>`:`<p>25'ten fazla çalışanı olan şirkette düşük moral, piyasanın altında maaş, yoğun tempo ve işten çıkarmalar örgütlenme baskısı yaratır. Sendika kurulursa her yıl toplu sözleşme pazarlığı yapılır; anlaşamazsan üyeler greve çıkar. Grevde üyeler çalışmaz, fabrikalar %40 kapasiteye düşer, marka aşınır. Talebi kabul edebilir, arabulucu tutabilir ya da grev fonunun tükenmesini bekleyebilirsin.</p>`)},
 {id:'fl',c:'urun',t:(LANG_EN?"Freelance work":'Serbest işler'),go:'dev',b:(LANG_EN?`<p>Other companies ask you for specific components within a set time: a promo website, an admin panel, a device prototype, firmware and so on. Offers appear on Product → New product, above the component depot, and stay open for a few days. You only get jobs that ask for components your team can produce.</p><ul><li>Components in the depot are delivered automatically to jobs you've accepted, before projects get them. The depot also prioritizes the components those jobs need.</li><li>When a job is finished on time you get paid and your reputation rises; it rises more if you finish within the first half of the deadline. Missing the deadline or backing out lowers your reputation.</li><li>The higher your reputation, the bigger and better-paid the jobs; at 50 reputation you can take three jobs at once.</li><li><b>Do it yourself:</b> The founder spends energy to make one of the job's components instantly (at most 3 times a day). Components outside the founder's own role are more tiring.</li></ul><p>Freelance work brings in cash especially in the first months, before your product makes money.</p>`:`<p>Başka şirketler senden belli bileşenleri belli bir süre içinde ister: tanıtım sitesi, yönetim paneli, cihaz prototipi, gömülü yazılım gibi. Teklifler Ürün → Yeni ürün sayfasında, bileşen deposunun üstünde görünür ve birkaç gün geçerlidir. Yalnızca ekibinin üretebileceği bileşenleri isteyen işler gelir.</p><ul><li>Kabul ettiğin işe depodaki bileşenler projelerden önce, otomatik teslim edilir. Depo da bu işlerin istediği bileşenleri öncelikli üretir.</li><li>İş zamanında bitince ödeme yapılır ve itibarın artar; sürenin ilk yarısında biterse daha da artar. Yetişmezse ya da vazgeçersen itibar düşer.</li><li>İtibar arttıkça işler büyür ve daha iyi ödenir; 50 itibarda aynı anda üç iş alabilirsin.</li><li><b>Kendin çalış:</b> Kurucu enerjisini harcayarak işin bir bileşenini anında yapar (günde en fazla 3 kez). Kendi rolü dışındaki bileşenler daha çok yorar.</li></ul><p>Serbest işler özellikle ilk aylarda, ürünün henüz para kazandırmadığı dönemde nakit sağlar.</p>`)},
 {id:'feat',c:'urun',t:(LANG_EN?"Product features":'Ürün özellikleri'),go:'dev',b:(LANG_EN?`<p>Every category has concrete features: accounts and login, video playback and dark mode for apps; fingerprint reader, face recognition, wireless charging and 5G for phones; backward compatibility and ray tracing for consoles, and so on. Some unlock through research or after a certain year. You pick them in step two of the development wizard.</p><ul><li>Each feature adds its own components to the recipe, so it lengthens the work; in return it raises the score and appeals more to certain audiences. Hardware features also raise the unit cost a little.</li><li><b>Innovation:</b> Features that aren't widespread yet have their full effect and win points with the press.</li><li><b>Standard:</b> After a certain year the market expects the feature. Standard features take half the work but contribute less, and leaving them out costs score. At the start of each year the news announces which features became standard.</li><li>You can add features to a product on the market with an update: 1 in a minor update, 2 in a major one.</li></ul>`:`<p>Her kategorinin somut özellikleri vardır: uygulamada hesap ve giriş, video oynatma, karanlık tema; telefonda parmak izi, yüz tanıma, kablosuz şarj, 5G; konsolda geriye dönük uyumluluk ve ışın izleme gibi. Bir kısmı araştırmayla ya da belli bir yıldan sonra açılır. Geliştirme sihirbazının ikinci adımında seçilir.</p><ul><li>Her özellik tarife kendi bileşenlerini ekler, yani işi uzatır; karşılığında puanı artırır ve bazı kitleleri daha çok çeker. Donanım özellikleri birim maliyeti de biraz artırır.</li><li><b>Yenilik:</b> Henüz yaygın olmayan özellikler tam etki verir ve basına artı yazar.</li><li><b>Standart:</b> Belli bir yıldan sonra pazar özelliği bekler. Standart özellikler yarı işle yapılır ama daha az katkı verir; olmaması puan kaybettirir. Her yılın başında hangi özelliklerin standart olduğu haber olarak duyurulur.</li><li>Piyasadaki bir ürüne güncellemeyle özellik eklenebilir: küçük güncellemede 1, büyük güncellemede 2.</li></ul>`)},
 {id:'comp',c:'urun',t:(LANG_EN?"Components and the depot":'Bileşenler ve depo'),go:'dev',b:(LANG_EN?`<p>Every project is built from a <b>component recipe</b>: interface code, backend services, databases and graphics sets for an app; circuit boards, mechanical housings, sensor modules, industrial design and firmware for a phone, and so on. The recipe depends on the category and the design focus; the attributes you emphasize need more of their components. You can see the recipe in step two of the development wizard.</p><p>The team produces components one by one; in the office a small badge pops up over an employee's head with each delivery. The project card shows how many of each component are done.</p><p><b>Component depot:</b> Developers, designers and hardware engineers without a project produce components for the depot instead of sitting idle (80% efficiency). A new project takes the components it needs from the depot right away. You can choose what each role produces in the depot section at the bottom of Product → New product. Depot capacity grows with your office; components from cancelled projects go back to the depot.</p>`:`<p>Her proje bir <b>bileşen tarifiyle</b> yapılır: uygulama için arayüz kodu, arka uç servisi, veritabanı ve grafik seti; telefon için devre kartı, mekanik gövde, sensör modülü, endüstriyel tasarım ve gömülü yazılım gibi. Tarif kategoriye ve tasarım odağına göre değişir; öne çıkardığın niteliğin bileşenlerinden daha çok gerekir. Geliştirme sihirbazının ikinci adımında tarifi görürsün.</p><p>Ekip bileşenleri tek tek üretir; ofiste her teslimde çalışanın başında küçük bir rozet belirir. Proje kartında hangi bileşenden kaç tane bittiği görünür.</p><p><b>Bileşen deposu:</b> Projesi olmayan yazılımcı, tasarımcı ve donanım mühendisleri boş durmak yerine depoya bileşen üretir (verim %80). Yeni bir proje ihtiyaç duyduğu bileşenleri depodan hemen alır. Hangi bileşenin üretileceğini Ürün → Yeni ürün sayfasının altındaki depo bölümünden seçebilirsin. Depo kapasitesi ofisle büyür; iptal edilen projelerin bileşenleri depoya döner.</p>`)},
 {id:'focus',c:'urun',t:(LANG_EN?"Design focus":'Tasarım odağı'),go:'dev',b:(LANG_EN?`<p>Every product category has four attributes: for a phone, performance, design, battery life and durability; for an app, speed, ease of use, features and privacy. In the second development step you spread 8 focus points across them. Each attribute appeals to different segments and has a cost: performance draws discerning buyers but raises cost, low cost draws budget buyers but drives discerning ones away, durability lowers defect risk. The press gives each attribute its own sub-score. Updates can shift the focus (1 point in a minor update, 2 in a major one), and every update goes into the release notes. Click a product name to open its details, sub-scores, rival comparison and version history.</p>`:`<p>Her ürün kategorisinin dört niteliği vardır; örneğin telefonda performans, tasarım, pil ömrü ve dayanıklılık, uygulamada hız, kullanım kolaylığı, özellikler ve gizlilik. Geliştirmenin ikinci adımında bunlara 8 odak puanı dağıtırsın. Her nitelik farklı kesimlere hitap eder ve bir bedeli vardır: performans seçici kitleyi çeker ama maliyeti artırır, düşük maliyet fiyat odaklı kitleyi çeker ama seçicileri uzaklaştırır, dayanıklılık arıza riskini düşürür. Basın her nitelik için ayrı alt puan verir. Güncellemelerde odağı kaydırabilirsin (küçük güncellemede 1, büyük güncellemede 2 puan); her güncelleme sürüm notlarına yazılır. Ürün adına tıklayınca detay, alt puanlar, rakip karşılaştırması ve sürüm geçmişi açılır.</p>`)},
 {id:'claude',c:'diger',t:(LANG_EN?"Advisor and press with Claude":'Claude ile danışman ve basın'),go:'dash',b:(LANG_EN?`<p>When you open the game on claude.ai, the "Ask Ayla" button on the CEO desk lets you ask the advisor anything: Ayla sees your company's current data and tailors her advice to it, and you can jump to the screens she suggests with one click. The "Press" button in the Products table writes a fictional magazine review of a product, and "This month's paper" in the News archive writes a newspaper front page from the month's events. These use your Claude usage; permission is requested on first use. If you decline, these buttons are hidden and the rest of the game works as usual.</p>`:`<p>Oyunu claude.ai'de açtığında CEO masasındaki "Ayla'ya sor" düğmesiyle danışmana serbest soru sorabilirsin: Ayla şirketinin o anki verisini görür ve önerilerini ona göre yapar, önerdiği ekranlara tek tıkla gidebilirsin. Ürünler tablosundaki "Basın" düğmesi ürün için kurgusal bir dergi incelemesi, Haber arşivindeki "Bu ayın gazetesi" ayın olaylarından bir gazete ön sayfası yazdırır. Bunlar senin Claude kullanımından harcar; ilk kullanımda izin istenir. İzin vermezsen bu düğmeler gizlenir, oyunun geri kalanı aynen çalışır.</p>`)},
 {id:'story',c:'bas',t:(LANG_EN?"Story campaign":'Hikâye kampanyası'),go:'dash',b:(LANG_EN?`<p>The story campaign on the new game screen starts with a single company in 2015 and goes from garage to IPO across 8 chapters. Each chapter has a short goal; the chapter card sits at the top of the CEO desk. There is no time limit, but finishing faster earns more stars. If Simple mode is on, advanced sections unlock as you progress.</p>`:`<p>Yeni oyun ekranındaki hikâye kampanyası tek bir şirketle 2015'ten başlar ve 8 bölümde garajdan halka arza gider. Her bölümün kısa bir hedefi vardır; bölümün kartı CEO masasının en üstündedir. Süre sınırı yoktur ama hızlı bitirirsen daha çok yıldız alırsın. Basit mod açıksa ileri seviye bölümler sen ilerledikçe açılır.</p>`)},
 {id:'simple',c:'bas',t:(LANG_EN?"Simple and Full mode":'Basit ve Tam mod'),go:'fin:kayit',b:(LANG_EN?`<p>In Simple mode, advanced sections such as union, currency, patents, culture and data policy are hidden from the menu; their decisions are made automatically with the default option, part orders and the research queue run on their own, and basic cybersecurity measures are taken as the team grows. You can switch to Full mode anytime in Finance → Save & settings.</p>`:`<p>Basit modda sendika, döviz, patent, kültür, veri politikası gibi ileri seviye bölümler menüden gizlenir; bunların kararları varsayılan seçenekle otomatik verilir, parça siparişi ve araştırma sırası kendiliğinden yürür, ekip büyüyünce temel siber güvenlik önlemleri alınır. Finans → Kayıt ve ayarlar bölümünden her an Tam moda geçebilirsin.</p>`)},
 {id:'diag',c:'bas',t:(LANG_EN?"Why am I losing?":'Neden kaybediyorum?'),go:'dash',b:(LANG_EN?`<p>When the company posts losses several months in a row or your runway gets short, a diagnosis card appears on the CEO desk: it looks at recent revenue, expenses, morale, quality and supply data, names the real problem with numbers and suggests what to do. If you go bankrupt, the recent diagnoses are collected in the "Why did it fail?" summary.</p>`:`<p>Şirket üst üste zarar ettiğinde ya da nakit ömrü kısaldığında CEO masasında bir teşhis kartı çıkar: son aylardaki gelir, gider, moral, kalite ve tedarik verisine bakıp asıl sorunu rakamlarla söyler ve ne yapman gerektiğini önerir. İflas edersen son aylardaki teşhisler "Neden battı?" özetinde toplanır.</p>`)},
 {id:'duel',c:'diger',t:(LANG_EN?"Challenge a friend":'Arkadaşına meydan oku'),go:'stats:lider',b:(LANG_EN?`<p>Create a six-character code and send it to a friend. The code sets starting cash, starting research, two world conditions and every random event in the game: everyone who plays the same code competes in the same world. After 3 game years your valuation becomes your score and appears next to others on the code's leaderboard. The table compares not just valuation but the whole company profile: revenue over the last 12 months, year-end valuations, product and employee counts, high-awareness cities, stores, factories and production lines, mines, real estate, stock portfolio and media audience; the best value in each row is highlighted. During the game, at the end of each year you see where the leaderboard's leader stood at the same point. You can replay the same code as many times as you like; your best result counts.</p>`:`<p>Altı karakterlik bir kod oluştur ve arkadaşına gönder. Kod; başlangıç nakdini, hazır araştırmayı, iki dünya koşulunu ve oyun boyunca tüm rastgele olayları belirler: aynı kodu oynayan herkes aynı dünyada yarışır. 3 oyun yılı sonunda değerlemen skorun olur ve kodun tablosunda diğerleriyle yan yana görünür. Tablo yalnızca değerlemeyi değil şirket profilini de karşılaştırır: son 12 ayın geliri, yıl sonu değerlemeleri, ürün ve çalışan sayısı, bilinirliği yüksek şehirler, mağazalar, fabrikalar ve üretim hatları, madenler, gayrimenkul, hisse portföyü ve medya izleyicisi; her satırda en iyisi vurgulanır. Oyun sırasında her yıl sonunda tablonun liderinin o noktadaki değerlemesini görürsün. Aynı kodu istediğin kadar tekrar oynayabilirsin; en iyi sonucun sayılır.</p>`)},
 {id:'cloud',c:'diger',t:(LANG_EN?"Cloud save":'Bulut kaydı'),go:'',b:(LANG_EN?`<p>Cloud slots under Settings → Save are stored in your account: sign in to claude.ai on another device, open the game and pick up where you left off. Only you can see your cloud saves. Optionally, the game saves automatically to the "Auto" slot at the start of each game year.</p>`:`<p>Ayarlar → Kayıt bölümündeki bulut yuvaları hesabına saklanır: başka bir cihazda claude.ai'de oturum açıp oyunu açtığında kaldığın yerden devam edebilirsin. Bulut kayıtlarını yalnızca sen görürsün. İstersen her oyun yılı başında "Otomatik" yuvasına kendiliğinden kaydedilir.</p>`)},
 {id:'report',c:'diger',t:(LANG_EN?"Report card":'Şirket karnesi'),go:'stats:karne',b:(LANG_EN?`<p>History → Report card, and the report card shown at the end of the game, gather your valuation curve, milestones, strengths and weaknesses, and tips for your next company on a single page. The grade is based on your valuation's annual growth rate and how the company ended.</p>`:`<p>Tarihçe → Şirket karnesi ve oyun sonunda açılan karne; değerleme eğrisini, dönüm noktalarını, güçlü ve zayıf yönlerini ve bir sonraki şirket için önerileri tek sayfada toplar. Not, değerlemenin yıllık büyüme hızına ve şirketin nasıl sonlandığına göre verilir.</p>`)},
 {id:'pf',c:'finans',t:(LANG_EN?"Share portfolio":'Hisse portföyü'),go:'fin:portfoy',b:(LANG_EN?`<p>You can buy rivals' shares as an investment. Shares are bought in 1% slices; each slice costs a little more as your stake grows, and selling has a 1% spread.</p><ul><li><b>Dividends:</b> 25% of a profitable rival's monthly profit is paid to you in proportion to your stake.</li><li><b>Disclosure:</b> A stake above 5% is made public; your relationship with the rival worsens a little.</li><li><b>Control:</b> Above 50% you can buy the remaining shares at 105% of value and merge with the company; it's cheaper but slower than a hostile takeover. The competition authority limit applies here too.</li><li>If the rival is bought by someone else, your stake is paid out with a 10% premium; if it goes bankrupt, almost all of it is lost.</li><li>You can't run a portfolio and a hostile takeover on the same company.</li></ul><p>Your portfolio's market value appears on the balance sheet. Dividend and buyback decisions for your own company are on Finance → Shareholders.</p>`:`<p>Rakiplerin hissesini bir yatırım olarak alabilirsin. Hisseler %1'lik dilimlerle alınır; payın büyüdükçe her dilim biraz daha pahalıya gelir, satışta %1 makas vardır.</p><ul><li><b>Temettü:</b> Kârlı bir rakibin aylık kârının %25'i payın oranında sana ödenir.</li><li><b>Bildirim:</b> %5'i geçen pay kamuya duyurulur; rakiple ilişkin biraz bozulur.</li><li><b>Kontrol:</b> %50'yi geçince kalan hisseleri değerin %105'iyle alıp şirketle birleşebilirsin; bu, düşmanca devralmadan daha ucuz ama daha yavaş bir yoldur. Rekabet Kurumu sınırı burada da geçerlidir.</li><li>Rakip başkası tarafından satın alınırsa payın %10 primle ödenir; batarsa neredeyse tamamı kaybolur.</li><li>Aynı şirkette hem portföy hem düşmanca devralma yürütülemez.</li></ul><p>Portföyün piyasa değeri bilançoda görünür. Kendi şirketinin temettü ve geri alım kararları Finans → Hissedarlar sayfasındadır.</p>`)},
 {id:'stmt',c:'finans',t:(LANG_EN?"Financial statements":'Mali tablolar'),go:'fin:tablo',b:(LANG_EN?`<p>Finance → Financial statements shows your company's three core statements and key ratios.</p><ul><li><b>Income statement:</b> Compares the last 12 months with the 12 before: revenue, cost of goods sold (parts and production), gross profit, salaries, rent, infrastructure, factories, other expenses, interest and net profit.</li><li><b>Balance sheet:</b> Today's assets (cash, inventory, and the book value of factories, mines, stores, the venture fund and rival stakes) and how they're funded (loans and equity). Products, brand and team aren't on the balance sheet; that's where the gap between market value and book value comes from.</li><li><b>Cash flow:</b> Operating, investing and financing (funding rounds, loans, dividends and other) lines.</li><li><b>Ratios:</b> gross and net margin, cash runway, debt/equity, return on equity, price-to-book.</li><li><b>Rival financials:</b> The most valuable rivals' revenue and profit last month, cash, estimated value and P/E ratio. From here you can start building a stake or buy a company outright.</li></ul>`:`<p>Finans → Mali tablolar sayfası şirketinin üç temel tablosunu ve oranlarını gösterir.</p><ul><li><b>Gelir tablosu:</b> Son 12 ayı önceki 12 ayla karşılaştırır: gelir, satılan malın maliyeti (parça ve üretim), brüt kâr, maaş, kira, altyapı, fabrika, diğer giderler, faiz ve net kâr.</li><li><b>Bilanço:</b> Bugünkü varlıklar (nakit, stok, fabrika, maden, mağaza, girişim fonu ve rakip hisselerinin defter değeri) ile kaynaklar (kredi ve özkaynak). Ürünlerin, markanın ve ekibin değeri bilançoda yer almaz; piyasa değeriyle defter değeri arasındaki fark buradan gelir.</li><li><b>Nakit akışı:</b> İşletme, yatırım ve finansman (yatırım turları, kredi, temettü ve diğer) kalemleri.</li><li><b>Oranlar:</b> brüt ve net marj, nakit ömrü, borç/özkaynak, özkaynak kârlılığı, piyasa/defter değeri.</li><li><b>Rakip finansalları:</b> En değerli rakiplerin geçen ayki gelir ve kârı, nakdi, tahmini değeri ve F/K oranı. Buradan hisse toplamaya başlayabilir ya da şirketi doğrudan satın alabilirsin.</li></ul>`)},
 {id:'mega',c:'finans',t:(LANG_EN?"Megaprojects":'Büyük projeler'),go:'mega',b:(LANG_EN?`<p>Once your company is worth more than $50 million, you can take on megaprojects such as an education foundation, a campus, an AI supercomputer, a global distribution network, a smart city and a crewed space mission. The cost is paid in monthly installments; in months when your cash falls short, the project waits. Each completed project gives a permanent bonus: candidate quality, morale, research speed, appeal or steady income. If you cancel, 30% of the money spent comes back.</p>`:`<p>Şirket değerin 50 milyon doları geçince eğitim vakfı, kampüs, yapay zekâ süper bilgisayarı, küresel dağıtım ağı, akıllı şehir ve insanlı uzay görevi gibi büyük projelere girişebilirsin. Bedel aylık taksitlerle ödenir; nakdin yetmediği ay proje bekler. Tamamlanan her proje kalıcı bir bonus verir: aday kalitesi, moral, araştırma hızı, çekicilik ya da düzenli gelir. İptal edersen harcananın %30'u geri gelir.</p>`)},
 {id:'nem',c:'pazar',t:(LANG_EN?"Nemesis":'Ezeli rakip'),go:'market:pay',b:(LANG_EN?`<p>After the third year, once your company is on its feet (worth more than $8 million and profitable for the last six months), the aggressive rival you clash with most in shared markets makes you its target. It prices and advertises more aggressively and now and then puts you in a tough spot. You win the rivalry if you hold 2.5 times its share in shared markets for six months, buy it, or it goes bankrupt. If you trail by the same margin for a full year, you lose. Once a rivalry ends, a new nemesis may appear two years later.</p>`:`<p>Üçüncü yıldan sonra, şirketin ayağa kalkınca (değer 8 milyon doları geçip son altı ay kârlı kapanınca) ortak pazarlarda en çok çakıştığın saldırgan rakip seni hedef alır. Daha agresif fiyat ve reklam yapar, ara sıra seni zor bir karar önüne koyar. Ortak pazarlardaki payın onunkinin 2,5 katını altı ay korursa, onu satın alırsan ya da iflas ederse rekabeti kazanırsın. Bir yıl boyunca aynı farkla geride kalırsan kaybedersin. Rekabet bitince iki yıl sonra yeni bir rakip çıkabilir.</p>`)},
 {id:'exec',c:'ekip',t:(LANG_EN?"Executives":'Üst yönetim'),go:'team:ust',b:(LANG_EN?`<p>Once you reach 8 employees, you can appoint Product, Operations, Finance, HR and Marketing heads. They handle recurring tasks weekly by the rules you set: updating aging products, adding racks, switching suppliers, giving raises, filling empty desks, sending tired staff on leave, starting launch campaigns for new products, booking trade show booths and so on. A skilled executive makes sharper calls. Hiring costs a 2-salary bonus; firing costs 3 salaries in severance.</p>`:`<p>8 çalışana ulaşınca Ürün, Operasyon, Finans, İK ve Pazarlama müdürü atayabilirsin. Senin belirlediğin kurallarla tekrarlayan işleri haftalık olarak yaparlar: eskiyen ürünü güncellemek, raf eklemek, tedarikçi değiştirmek, zam yapmak, boş masaları doldurmak, yorgunları izne yollamak, yeni ürüne lansman kampanyası açmak, fuara stant ayırmak gibi. Yetenekli yönetici daha isabetli karar verir. İşe alırken 2 maaş prim, çıkarırken 3 maaş tazminat ödenir.</p>`)},
 {id:'acq',c:'ekip',t:(LANG_EN?"Acquired teams":'Devralınan ekipler'),go:'team:devralma',b:(LANG_EN?`<p>When you buy a rival, its employees come with it. You can keep key people with retention bonuses, run the team as a separate division, or let them go with severance. Different company cultures can cause friction.</p>`:`<p>Bir rakibi satın alınca çalışanları da gelir. Kilit kişileri tutma primiyle elde tutabilir, ekibi ayrı bir bölüm olarak yaşatabilir ya da tazminatla çıkarabilirsin. Farklı şirket kültürleri uyum sorunu yaratabilir.</p>`)},

 {id:'raw',c:'uretim',t:(LANG_EN?"Raw materials":'Ham maddeler'),go:'supply:ham',b:(LANG_EN?`<p>Part prices depend on raw material prices: chips and memory on silicon, batteries on lithium, cameras and motors on rare earth elements, housings on aluminum, memory and graphics cards on copper. 40% of a part's price comes from its raw material mix; 1.00 is the normal level.</p><ul><li>Raw material prices change once a month, and shocks happen from time to time: export restrictions, demand booms, strikes, new deposits. A shock lasts a few months.</li><li><b>Mine:</b> You can build one mine per raw material (up to level 3). A mine sells what it produces at the market price, and its cost is fixed. When prices rise your parts get more expensive, but the mine earns more too; it's a natural hedge. The hedge ratio is the mine's output relative to your usage.</li><li><b>Feed your own production:</b> Instead of selling the mine's output on the market you can route it to your own production (the default for new mines). For the usage the mine covers, raw material comes at an internal cost of 0.60 and your part prices drop; any surplus is still sold on the market. If the market price falls below 0.60, selling is more profitable. Raw materials appear on the far left of the supply chain diagram.</li><li><b>Futures contract:</b> Locks today's price for 12 months for your monthly usage (the fee is 2% of the yearly amount). If the price rises above the lock you receive the difference each month; if it falls below, you pay it.</li></ul>`:`<p>Parçaların fiyatı ham madde fiyatlarına bağlıdır: yonga ve bellek silisyuma, batarya lityuma, kamera ve motor nadir toprak elementlerine, kasa alüminyuma, bellek ve grafik kartı bakıra. Bir parçanın fiyatının %40'ı ham madde karışımından gelir; 1,00 normal seviyedir.</p><ul><li>Ham madde fiyatları ayda bir değişir ve zaman zaman şoklar yaşanır: ihracat kısıtlaması, talep patlaması, grev, yeni yataklar. Şok birkaç ay sürer.</li><li><b>Maden:</b> Her ham madde için bir maden kurabilirsin (3 seviyeye kadar). Maden ürettiğini piyasa fiyatından satar, gideri sabittir. Fiyatlar yükselince parçaların pahalanır ama maden de daha çok kazandırır; bu doğal bir korunmadır. Korunma oranı, madenin üretiminin senin kullanımına oranıdır.</li><li><b>Kendi üretimine ver:</b> Madenin çıktısını piyasaya satmak yerine kendi üretimine yönlendirebilirsin (yeni madenlerde varsayılan budur). Madenin karşıladığı kullanım için ham madde 0,60 iç maliyetle gelir ve parça fiyatların düşer; fazlası yine piyasaya satılır. Piyasa fiyatı 0,60'ın altına inerse satmak daha kârlıdır. Tedarik zinciri şemasında ham maddeler en solda görünür.</li><li><b>Vadeli anlaşma:</b> Bugünkü fiyatı aylık kullanımın kadar 12 ay kilitler (ücreti yıllık tutarın %2'si). Fiyat kilidin üstüne çıkarsa farkı her ay sen alırsın, altına düşerse sen ödersin.</li></ul>`)},
 {id:'fgrid',c:'uretim',t:(LANG_EN?"Facility grid":'Tesis ızgarası'),go:'mfg',b:(LANG_EN?`<p>Every factory is a grid of cells: 5×4 for an assembly plant, 4×3 for a chip fab. Materials really flow: <b>purchasing</b> (input) → <b>production lines</b> → <b>shipping</b> (output). Click an empty cell to choose what to build; click a filled cell to remove it (40% of the cost comes back).</p><ul><li><b>Line group:</b> Lines side by side (right, left, above, below) pass materials to each other and form a group.</li><li><b>Purchasing and shipping:</b> A line group works only if it touches a purchasing unit and a shipping unit. Each serves at most 4 lines; a 9-line group needs at least 3 purchasing and 3 shipping units. Running lines directly next to a purchasing unit produce 15% more because they are close to the materials; layout matters.</li><li><b>Idle line:</b> A line that is not connected to a group, or whose group lacks capacity, does not work; it appears hatched on the grid with the reason.</li><li>The <b>Add line</b> button places the line next to the group and adds a purchasing or shipping unit if needed; the price is shown on the button.</li><li><b>Quality control:</b> Next to a line, it lowers the defect rate by 0.6 points (up to 3 units).</li><li><b>Training center:</b> Lowers labor cost by 6% (up to 2 units).</li><li><b>Maintenance workshop:</b> Lowers operating cost by 8% (up to 2 units).</li></ul><p>Quality control, training and maintenance units raise operating cost by 3%, purchasing and shipping by 1%. Older factories were laid out once to fit the flow; all of their lines work.</p>`:`<p>Her fabrika hücrelerden oluşan bir ızgaradır: montaj fabrikası 5×4, çip fabrikası 4×3. Malzeme gerçekten akar: <b>satın alma</b> (girdi) → <b>üretim hatları</b> → <b>sevkiyat</b> (çıktı). Boş bir hücreye tıklayıp ne kuracağını seçersin; dolu bir hücreye tıklayıp kaldırabilirsin (maliyetin %40'ı geri döner).</p><ul><li><b>Hat grubu:</b> Yan yana (sağ, sol, üst, alt) duran hatlar malzemeyi birbirine aktarır ve bir grup oluşturur.</li><li><b>Satın alma ve sevkiyat:</b> Bir hat grubu ancak bir satın alma birimine ve bir sevkiyat birimine bitişikse çalışır. Her biri en çok 4 hatta hizmet eder; 9 hatlık bir grup için en az 3 satın alma ve 3 sevkiyat gerekir. Satın almaya doğrudan bitişik çalışan hatlar malzemeye yakın olduğu için %15 daha çok üretir; yerleşim önemlidir.</li><li><b>Boştaki hat:</b> Gruba bağlı olmayan ya da kapasitesi yetmeyen hat çalışmaz; ızgarada taralı görünür ve nedeni yazar.</li><li><b>Hat ekle</b> düğmesi hattı grubun yanına koyar ve gerekiyorsa satın alma ya da sevkiyat birimini de ekler; fiyatı düğmede yazar.</li><li><b>Kalite kontrol:</b> Bir hatta bitişikse hata oranını 0,6 puan düşürür (en çok 3 birim).</li><li><b>Eğitim merkezi:</b> İşçilik maliyetini %6 düşürür (en çok 2 birim).</li><li><b>Bakım atölyesi:</b> İşletme giderini %8 düşürür (en çok 2 birim).</li></ul><p>Kalite kontrol, eğitim ve bakım birimleri işletme giderini %3, satın alma ve sevkiyat %1 artırır. Eski fabrikalar akışa uygun biçimde bir kez yeniden yerleştirildi; hatların hepsi çalışır durumda.</p>`)},
 {id:'factory',c:'uretim',t:(LANG_EN?"Hardware manufacturing and factories":'Donanım üretimi ve fabrikalar'),go:'mfg',b:(LANG_EN?`<p>Hardware products are made by a contract manufacturer (China) or in your own factory. An assembly factory makes phones, computers, wearables and consoles; a chip fab makes processors. Your own factory is cheaper and gives you more control; its region sets labor costs and tariffs. Adding lines raises capacity, automation raises yield. Finished products go into inventory; if inventory runs out, you lose sales.</p>`:`<p>Donanım ürünleri fason tesiste (Çin) ya da kendi fabrikanda üretilir. Montaj fabrikası telefon, bilgisayar, giyilebilir ve konsol; çip fabrikası işlemci üretir. Kendi fabrikan daha ucuz ve kontrollüdür; bölgesi işçilik maliyetini ve gümrükleri belirler. Hat ekleyerek kapasite, otomasyonla verim artar. Üretilen ürün stoğa girer; stok biterse satış kaçar.</p>`)},
 {id:'supply',c:'uretim',t:(LANG_EN?"Supply chain":'Tedarik zinciri'),go:'supply',b:(LANG_EN?`<p>Parts are ordered from suppliers; lead time, reliability and price vary by supplier. Auto-ordering keeps inventory in line with the production plan. It protects your cash: 1.5 months of fixed costs are set aside before orders, at most 60% of free cash goes to parts at once, and if cash falls below 3 months of fixed costs it switches to cautious mode and buys only lead time + 10 days of inventory. Production also runs with half a month of costs set aside. Before a hardware launch, the advisor warns you if parts costs will exceed your cash: sales revenue comes in only after the product ships, so line up a loan or investment in advance. Events like earthquakes, strikes, tariffs and chip shortages disrupt supply; excess inventory ties up cash, too little halts production.</p>`:`<p>Parçalar tedarikçilerden sipariş edilir; teslim süresi, güvenilirlik ve fiyat tedarikçiye göre değişir. Otomatik sipariş üretim planına göre stok tutar. Nakdi korur: siparişlerden önce 1,5 aylık sabit gider ayrılır, tek seferde serbest nakdin en fazla %60'ı parçaya gider; nakit 3 aylık sabit giderin altına inerse temkinli moda geçer ve yalnızca teslim süresi + 10 gün stok alır. Üretim de yarım aylık gideri ayırarak çalışır. Donanım lansmanından önce parça maliyeti nakdi aşacaksa danışman uyarır: satış geliri ürün çıktıktan sonra gelir, önceden kredi ya da yatırım ayarla. Deprem, grev, gümrük, çip krizi gibi olaylar tedariki aksatır; fazla stok nakit bağlar, az stok üretimi durdurur.</p>`)},
 {id:'vert',c:'uretim',t:(LANG_EN?"Vertical integration":'Dikey entegrasyon'),go:'supply:dikey',b:(LANG_EN?`<p>You can build your own plant for casings, batteries, sensors, panels, memory, graphics chips or silicon wafers (120 days). Parts within capacity cost ~55% of the market price, arrive in 4 days and avoid tariffs; anything beyond comes from the spot market at 15% more. Selling spare capacity can cover up to 80% of fixed costs. Plants pay off at large scale.</p>`:`<p>Kasa, batarya, sensör, panel, bellek, grafik çipi ya da silikon levha için kendi tesisini kurabilirsin (120 gün). Kapasite içindeki parçalar piyasa fiyatının ~%55'ine gelir, 4 günde teslim edilir, gümrüğe takılmaz; aşan kısım %15 pahalı anlık piyasadan alınır. Boş kapasiteyi satarak sabit giderin en fazla %80'ini karşılayabilirsin. Tesisler büyük ölçekte kârlıdır.</p>`)},
 {id:'dc',c:'uretim',t:(LANG_EN?"Servers and data centers":'Sunucular ve veri merkezleri'),go:'infra:veri',b:(LANG_EN?`<p>Web service subscribers use 1 unit of server capacity, AI subscribers 4; once capacity is full you can't take new subscribers. You can add racks to your office or build data centers in regions: data center racks are 30% cheaper, cost 45% less to run and give 25% more capacity. You can lease part of your capacity to other companies. Data centers occasionally suffer outages.</p>`:`<p>Web servisi aboneleri 1, yapay zekâ aboneleri 4 birim sunucu kapasitesi kullanır; kapasite dolarsa yeni abone alamazsın. Ofise raf ekleyebilir ya da bölgelerde veri merkezi kurabilirsin: veri merkezi rafları %30 ucuz, %45 daha az gider ister, %25 fazla kapasite verir. Kapasitenin bir kısmını diğer şirketlere kiralayabilirsin. Merkezler ara sıra kesinti yaşar.</p>`)},

 {id:'research',c:'arge',t:(LANG_EN?"Research":'Araştırma'),go:'res',b:(LANG_EN?`<p>Researchers produce research points; only one research project runs at a time. Research unlocks new categories, parts, manufacturing processes and efficiency gains. Chip processes ahead of their time are much more expensive; they get cheaper as their time comes.</p>`:`<p>Araştırmacılar araştırma puanı üretir; aynı anda tek araştırma yapılır. Araştırmalar yeni kategorileri, parçaları, üretim süreçlerini ve verim artışlarını açar. Çağının ötesindeki çip süreçleri çok daha pahalıdır; zamanı geldikçe ucuzlar.</p>`)},
 {id:'oss',c:'arge',t:(LANG_EN?"Open source and developer community":'Açık kaynak ve geliştirici topluluğu'),go:'res:acik',b:(LANG_EN?`<p>You can open-source your completed software, infrastructure, security and operations research (monthly maintenance cost per project).</p><ul><li>Projects collect stars, and stars grow your <b>developer community</b>.</li><li>The community contributes to your research daily, reduces bugs in your software products, brings more talented candidates and grows your brand.</li><li>The cost: rivals working in that field get a slight tech boost, and you lose the patent on that technology.</li><li>An <b>API platform</b> earns revenue per developer and makes your software more appealing (requires a web service, AI service or OS).</li><li>Once a year you can host a <b>developer conference</b> and speed up growth with a <b>developer relations</b> budget.</li></ul>`:`<p>Tamamladığın yazılım, altyapı, güvenlik ve operasyon araştırmalarını açık kaynak yapabilirsin (proje başına aylık bakım gideri).</p><ul><li>Projeler yıldız toplar, yıldızlar <b>geliştirici topluluğunu</b> büyütür.</li><li>Topluluk araştırmana günlük katkı verir, yazılım ürünlerindeki hataları azaltır, daha yetenekli aday getirir, markanı büyütür.</li><li>Bedeli: o alanda çalışan rakiplerin teknolojisi biraz güçlenir ve o teknolojinin patentini kaybedersin.</li><li><b>API platformu</b> geliştirici başına gelir getirir ve yazılımlarını daha çekici yapar (web servisi, yapay zekâ hizmeti ya da OS gerekir).</li><li>Yılda bir <b>geliştirici konferansı</b> düzenleyebilir, <b>geliştirici ilişkileri</b> bütçesiyle büyümeyi hızlandırabilirsin.</li></ul>`)},
 {id:'patent',c:'arge',t:(LANG_EN?"Patents & lawsuits":'Patentler ve davalar'),go:'res:patent',b:(LANG_EN?`<p>You can patent completed research; patent strength makes it easier to sue and to defend yourself. Rivals can sue you too. The chance of winning depends on both sides' patent strength and the law firm you retain; settlement offers may also come in.</p><ul><li><b>Patent strength:</b> a patent from completed research is worth 2 points, 3 for major research (4,000+ research points); an automatic design patent is worth 1. Patents last 12 years.</li><li><b>Lawsuit risk:</b> the Patents panel lists the categories you sell in where a rival is close to the suit line, how much patent strength you need, and the cheapest research that would protect that category.</li><li><b>Filing fee:</b> $30K per application (today's prices); half that, $15K, while you have at most 25 employees. A decision comes in 4–8 months.</li><li><b>When rivals sue:</b> not in your first 18 months, and only if their patent strength in that category is at least 3 ahead of yours; each patent strength point you hold in that category also cuts the chance they sue by 15% (up to 80%), because they fear a countersuit.</li><li><b>Claim:</b> 2–4 times your monthly revenue in that category, but at most 20% of your cash (at least $150K).</li><li><b>Options:</b> settling costs half the claim; defending is a bet that depends on patent strength (the decision shows each option's estimated net effect).</li></ul>`:`<p>Tamamladığın araştırmaları patentleyebilirsin; patent gücün dava açmanı ve savunmanı kolaylaştırır. Rakipler de seni dava edebilir. Kazanma ihtimali iki tarafın patent gücüne ve tuttuğun hukuk bürosuna bağlıdır; uzlaşma teklifleri de gelebilir.</p><ul><li><b>Patent gücü:</b> tamamlanan araştırmadan gelen patent 2 puan, büyük araştırmada (4.000+ araştırma puanı) 3 puan; otomatik tasarım patenti 1 puandır. Patentler 12 yıl geçerlidir.</li><li><b>Dava riski:</b> Patentler panelinde, sattığın kategorilerden hangisinde bir rakibin dava sınırına yaklaştığını, ne kadar patent gücü gerektiğini ve o kategoriyi koruyacak en ucuz araştırmayı görürsün.</li><li><b>Başvuru ücreti:</b> başvuru başına 30K (bugünkü fiyatlarla); en çok 25 çalışanın varken yarısı, 15K. Karar 4–8 ayda çıkar.</li><li><b>Rakipler ne zaman dava açar:</b> ilk 18 ayında açmaz; o kategoride patent güçleri seninkinden en az 3 fazlaysa açabilir. Ayrıca o kategorideki her patent gücün, karşı dava korkusuyla dava ihtimalini %15 düşürür (en çok %80).</li><li><b>Talep:</b> o kategorideki aylık cironun 2–4 katı, ama nakdinin en çok %20'si (en az $150K).</li><li><b>Seçenekler:</b> uzlaşmak talebin yarısına mal olur; savunmak patent gücüne bağlı bir bahistir (kararda her seçeneğin tahmini net etkisi görünür).</li></ul>`)},
 {id:'gov',c:'arge',t:(LANG_EN?"Government & regulation":'Devlet ve regülasyon'),go:'fin:devlet',b:(LANG_EN?`<p>Corporate tax is 15%; losses carry forward to later periods, and small companies pay half the rate. You can apply for R&D, investment, employment and export incentives. Regulations such as a digital services tax, data localization and tariffs come into force from time to time. If you hold more than 45% of a market, the Competition Authority may open an investigation.</p>`:`<p>Kurumlar vergisi %15'tir; zararlar sonraki dönemlere devreder, küçük şirketler yarı oranla öder. Ar-Ge, yatırım, istihdam ve ihracat teşviklerine başvurabilirsin. Dijital hizmet vergisi, veri yerelleştirme ve gümrük gibi düzenlemeler zaman zaman yürürlüğe girer. Bir pazarda %45'ten fazla pay tutarsan Rekabet Kurumu soruşturma açabilir.</p>`)},
 {id:'cyber',c:'arge',t:(LANG_EN?"Cybersecurity":'Siber güvenlik'),go:'infra:guvenlik',b:(LANG_EN?`<p>As your user count, team and servers grow, so does your attack surface. Security specialists, research, penetration testing and a bug bounty program raise your security level. Ransomware, data breaches and DDoS attacks can happen; backups and cyber insurance reduce the damage.</p>`:`<p>Kullanıcı sayın, ekibin ve sunucuların büyüdükçe saldırı yüzeyin artar. Güvenlik uzmanları, araştırmalar, sızma testi ve hata ödül programı güvenlik seviyeni yükseltir. Fidye yazılımı, veri sızıntısı ve DDoS saldırıları olabilir; yedekleme ve siber sigorta zararı azaltır.</p>`)},

 {id:'esg',c:'finans',t:(LANG_EN?"Sustainability score":'Sürdürülebilirlik puanı'),go:'fin:surdur',b:(LANG_EN?`<p>Your office, servers, data centers, factories, component plants, the devices you make and parts shipping all emit carbon. These emissions relative to revenue set your <b>environmental</b> score (60). The <b>social</b> score (25) comes from morale, strikes and survey promises; the <b>governance</b> score (15) from antitrust investigations, cyberattacks, board relations and greenwashing news.</p><p>You can cut emissions with green building certification, device recycling and green energy at factories and data centers, or offset them with carbon credits. Only 60% of credits count, and buying lots of credits without real cuts can trigger greenwashing news.</p><p>From 2020, a carbon tax applies to your emissions in proportion to your share of revenue from Europe. After 2018, customers in Europe and North America prefer high-scoring companies (±6%). The score affects funding rounds by ±10%; above 70 brings better candidates.</p>`:`<p>Ofisin, sunucuların, veri merkezlerin, fabrikaların, bileşen tesislerin, ürettiğin cihazlar ve parça nakliyesi karbon salar. Bu emisyonun gelirine oranı <b>çevre</b> puanını (60) belirler. <b>Sosyal</b> puan (25) moral, grev ve anket sözlerinden; <b>yönetişim</b> puanı (15) tekel soruşturması, siber saldırı, kurulla ilişki ve yeşil aklama haberlerinden gelir.</p><p>Emisyonu yeşil bina sertifikası, cihaz geri dönüşümü, fabrika ve veri merkezlerinde yeşil enerjiyle azaltabilir ya da karbon kredisiyle dengeleyebilirsin. Kredilerin yalnızca %60'ı sayılır ve gerçek azaltım yapmadan çok kredi alırsan yeşil aklama haberi çıkabilir.</p><p>2020'den itibaren Avrupa gelirinin payı kadar emisyonuna karbon vergisi uygulanır. 2018'den sonra Avrupa ve Kuzey Amerika'daki müşteriler yüksek puanlı şirketleri tercih eder (±%6). Puan yatırım turlarını ±%10 etkiler; 70'in üstü daha iyi adaylar getirir.</p>`)},
 {id:'awards',c:'pazar',t:(LANG_EN?"Tech awards":'Teknoloji ödülleri'),go:'stats:odul',b:(LANG_EN?`<p>Each year nominees are announced on November 15 and awards are given on December 10. Awards: <b>Product of the Year</b> (products released or updated in the past year), <b>Best of the Year</b> for every category with at least three competing products, <b>Startup of the Year</b> for companies under five years old, <b>Employer of the Year</b> (at least 20 employees; morale, perks and strikes), <b>Green Tech</b> (sustainability score) and <b>Innovation of the Year</b> (research and patents completed that year).</p><p>The strongest nominee usually wins, but the jury can surprise. Running an awards campaign during the nomination period boosts your chances. Awards you win grow your brand, make the product more appealing for a few months and lift your team's morale.</p>`:`<p>Her yıl 15 Kasım'da adaylar açıklanır, 10 Aralık'ta ödüller verilir. Ödüller: <b>Yılın Ürünü</b> (son bir yılda çıkan ya da güncellenen ürünler), en az üç ürünün yarıştığı her kategori için <b>Yılın En İyisi</b>, beş yaşından genç şirketler için <b>Yılın Girişimi</b>, <b>Yılın İşvereni</b> (en az 20 çalışan; moral, yan haklar ve grevler), <b>Yeşil Teknoloji</b> (sürdürülebilirlik puanı) ve <b>Yılın İnovasyonu</b> (o yıl tamamlanan araştırmalar ve patentler).</p><p>En güçlü aday çoğu zaman kazanır ama jüri sürpriz yapabilir. Adaylık döneminde ödül kampanyası yürütürsen kazanma şansın artar. Kazandığın ödüller markanı büyütür, ürünü birkaç ay daha çekici yapar, ekibin moralini yükseltir.</p>`)},
 {id:'pr',c:'pazar',t:(LANG_EN?"PR crises and press conferences":'PR krizleri ve basın toplantıları'),go:'market:hi',b:(LANG_EN?`<p>As your brand grows, crises happen: battery fires, data scandals, employee exposés, labor rights issues at suppliers, unfortunate CEO remarks, AI blunders, planned obsolescence. A crisis grows for the first two weeks, then fades. The longer it lasts, the more your brand erodes; the product involved sells much less, your other products a bit less.</p><p>Your responses: an <b>internal investigation</b> (7 days, shows whether the claims are true), an <b>apology</b> or <b>denial</b> statement, a <b>press conference</b> (three questions), <b>compensation</b> (expensive but most effective), or <b>dismissing</b> an executive. If you deny while at fault, the truth can surface months later and start a new crisis. Promises you make at a press conference (compensation, product date, emissions, layoffs) are tracked.</p><p>Even without a crisis, you can hold a press conference once every 60 days. A PR agency makes crises rarer and milder. Your marketing team boosts the impact of your answers.</p>`:`<p>Markan büyüdükçe krizler çıkar: batarya yangını, veri skandalı, çalışan ifşası, tedarikçide işçi hakları, CEO'nun talihsiz sözleri, yapay zekâ hataları, planlı eskitme. Kriz ilk iki hafta büyür, sonra söner. Sürdükçe markan erir; ilgili ürün çok, diğer ürünlerin biraz daha az satar.</p><p>Yanıtların: <b>iç soruşturma</b> (7 gün, iddiaların doğru olup olmadığını gösterir), <b>özür</b> ya da <b>yalanlama</b> açıklaması, <b>basın toplantısı</b> (üç soru), <b>telafi</b> (pahalı ama en etkili), bir yöneticiyi <b>görevden alma</b>. Hatalıyken yalanlarsan gerçek aylar sonra ortaya çıkıp yeni bir kriz başlatabilir. Basın toplantısında verdiğin sözler (telafi, ürün tarihi, emisyon, işten çıkarma) takip edilir.</p><p>Kriz yokken de 60 günde bir basın toplantısı düzenleyebilirsin. Halkla ilişkiler ajansı krizleri seyrekleştirir ve yumuşatır. Pazarlama ekibin cevaplarının etkisini artırır.</p>`)},
 {id:'scned',c:'diger',t:(LANG_EN?"Scenario editor":'Senaryo editörü'),go:'',b:(LANG_EN?`<p>In the <b>My scenarios</b> section of the new game screen you can design your own scenario: company name, cash, debt, share ownership, brand, office and servers; team size and skill per role, morale; completed research (prerequisites are added automatically); up to five ready-made software products; entered regions; part prices, demand, event frequency and rival strength; duration and up to six goals.</p><p>You must reach all goals at the same time before time runs out; finish within half the time for three stars, within three quarters for two. Send your scenario to friends with a <b>share code</b>, and open theirs with <b>Import by code</b>. Scenarios are stored in this browser.</p>`:`<p>Yeni oyun ekranındaki <b>Senaryolarım</b> bölümünden kendi senaryonu tasarlayabilirsin: şirket adı, nakit, borç, hisse payı, marka, ofis ve sunucular; rol başına ekip sayısı ve becerisi, moral; tamamlanmış araştırmalar (ön koşullar otomatik eklenir); en fazla beş hazır yazılım ürünü; girilmiş bölgeler; parça fiyatı, talep, olay sıklığı ve rakiplerin gücü; süre ve en fazla altı hedef.</p><p>Hedeflerin hepsine süre bitmeden aynı anda ulaşmalısın; sürenin yarısında bitirirsen üç, dörtte üçünde iki yıldız alırsın. <b>Paylaşım kodu</b> ile senaryonu arkadaşlarına gönderebilir, onların kodunu <b>Kodla içe aktar</b> ile açabilirsin. Senaryolar bu tarayıcıda saklanır.</p>`)},
 {id:'macro',c:'finans',t:(LANG_EN?"Economic cycles":'Ekonomik döngüler'),go:'fin:ekonomi',b:(LANG_EN?`<p>The economy cycles through phases: <b>growth</b>, sometimes <b>overheating</b> (a bubble), <b>recession</b> and <b>recovery</b>. Once between 2019 and 2021 a <b>global shock</b> hits: hardware demand and supply collapse, software demand explodes; it is followed by a <b>stimulus wave</b> with near-zero interest rates.</p><p>The central bank rate sets the loan rate (policy rate + 12%, annual). In a recession demand falls (a lot for devices, a little for apps), valuations and rival company prices drop, banks cut credit limits, and candidates are cheaper and more skilled. During overheating valuations inflate: the best time for a funding round or IPO, but when the bubble bursts the stock market crashes.</p><p>Analysts' recession forecasts are a useful guide but aren't always right.</p>`:`<p>Ekonomi dönemler arasında döner: <b>büyüme</b>, bazen <b>aşırı ısınma</b> (balon), <b>resesyon</b> ve <b>toparlanma</b>. 2019–2021 arasında bir kez <b>küresel şok</b> yaşanır: donanım talebi ve tedarik çöker, yazılım talebi patlar; ardından faizlerin sıfırlandığı bir <b>teşvik dalgası</b> gelir.</p><p>Merkez bankası faizi kredi faizini belirler (politika faizi + %12, yıllık). Resesyonda talep düşer (cihazlarda çok, uygulamalarda az), değerlemeler ve rakip şirketlerin fiyatları ucuzlar, bankalar kredi limitini kısar, adaylar daha ucuz ve yeteneklidir. Aşırı ısınmada değerlemeler şişer: yatırım turu ve halka arz için en iyi zamandır, ama balon patlayınca borsa çöker.</p><p>Analistlerin resesyon tahmini yol gösterir ama her zaman tutmaz.</p>`)},
 {id:'shareholders',c:'finans',t:(LANG_EN?"Shareholder management":'Hissedar yönetimi'),go:'fin:hissedar',b:(LANG_EN?`<p>As a public company, you manage your shareholders. <b>Dividend policy</b>: part of the profit is paid out every profitable quarter, and your share is added to your personal wealth; steady dividends build confidence, cutting them hurts badly. <b>Share buybacks</b> grow your stake; they're better received when the stock is cheap. A <b>secondary offering</b> raises cash but dilutes your stake. A <b>stock split</b> doesn't change value but pleases small investors. <b>Analyst guidance</b> sets quarterly expectations.</p><p>Every May the <b>annual meeting</b> votes on CEO pay; a rejection shakes the board's confidence. If the stock does poorly for long, an <b>activist investor</b> buys up shares and makes demands (downsizing, cash payouts, product shutdowns). You can accept, give them a board seat or launch a <b>proxy fight</b>; your odds depend on your stake, investor confidence, the last quarter, your brand and your sustainability score.</p>`:`<p>Halka açık şirketin hissedarlarını yönetirsin. <b>Temettü politikası</b>: her kârlı çeyrekte kârın bir kısmı dağıtılır, payına düşen kişisel servetine eklenir; düzenli temettü güveni artırır, kesmek sert düşürür. <b>Hisse geri alımı</b> payını büyütür; hisse ucuzken daha çok sevilir. <b>İkincil halka arz</b> nakit toplar ama payını sulandırır. <b>Hisse bölünmesi</b> değeri değiştirmez, küçük yatırımcıyı sevindirir. <b>Analist yönlendirmesi</b> çeyrek beklentisini belirler.</p><p>Her mayıs <b>genel kurul</b> CEO maaşını oylar; ret kurulun güvenini sarsar. Hisse uzun süre kötü giderse bir <b>aktivist yatırımcı</b> hisse toplayıp talepte bulunur (kadro küçültme, nakit dağıtma, ürün kapatma). Kabul edebilir, kurulda koltuk verebilir ya da <b>vekalet savaşına</b> girebilirsin; kazanma şansın hisse payına, yatırımcı güvenine, son çeyreğe, markana ve sürdürülebilirlik puanına bağlıdır.</p>`)},
 {id:'fx',c:'finans',t:(LANG_EN?"Currency risk":'Döviz kuru riski'),go:'fin:kur',b:(LANG_EN?`<p>Your company reports in dollars, but revenue from regions is earned in local currencies: Turkish lira, euro, and Asian and Latin American currencies. If a currency falls, your dollar revenue shrinks (about 70% passes through); in Latin America demand drops too. Costs move with exchange rates as well: salaries in Turkey are paid in lira, supplier and factory costs in the local currency of their region. When the lira weakens, your salary burden in dollars gets lighter; this is a <b>natural hedge</b>.</p><p>Currencies crash from time to time (most often the Turkish lira and Latin America); in recessions investors flee to the dollar. A <b>currency hedge</b> locks 50% or all of your revenue in one currency at today's rate for 6–12 months; its cost depends on volatility (the lira is the most expensive). If the rate rises, you miss that gain on the hedged part.</p>`:`<p>Şirketin dolarla raporlar ama bölgelerden gelen gelir yerel parayla kazanılır: Türk lirası, euro, Asya ve Latin Amerika para birimleri. Kur düşerse dolar gelirin azalır (yaklaşık %70'i yansır); Latin Amerika'da talep de düşer. Giderler de kurla oynar: Türkiye'deki maaşlar Türk lirasıyla, tedarikçi ve fabrika giderleri bulundukları bölgenin parasıyla ödenir. Lira değer kaybettiğinde dolar bazında maaş yükün hafifler; bu bir <b>doğal korumadır</b>.</p><p>Kurlar zaman zaman çöker (en sık Türk lirası ve Latin Amerika'da); resesyonlarda yatırımcılar dolara kaçar. <b>Kur koruması</b> bir para birimindeki gelirinin %50'sini ya da tamamını 6–12 ay boyunca bugünkü kurdan kilitler; bedeli oynaklığa bağlıdır (lira en pahalısı). Kur yükselirse korumalı kısımda o kazancı kaçırırsın.</p>`)},
 {id:'talent',c:'ekip',t:(LANG_EN?"Talent wars":'Yetenek savaşları'),go:'team:yetenek',b:(LANG_EN?`<p>Rivals make job offers to your best employees; the employee decides within 1–2 weeks. You can keep them with a counteroffer (match, or offer 10% more), stock options or a non-compete. If you do nothing, the chance they leave depends on their <b>flight risk</b> and how attractive the offer is. Flight risk depends on morale, pay versus market, skill, seniority, unvested options, non-competes and how hot the talent market is (economic phase).</p><p><b>Stock options</b> vest over 4 years (nothing in the first year); they come out of your stake, but the unvested part is a strong tie. Someone without a non-compete strengthens the rival's technology when they leave and may take low-morale teammates along. In the <b>Star hunting</b> section you can poach talent from rivals; those under non-competes carry a lawsuit risk.</p>`:`<p>Rakipler en iyi çalışanlarına iş teklif eder; çalışan 1–2 hafta içinde karar verir. Karşı teklif (eşleştir ya da %10 fazlasını ver), hisse opsiyonu ya da rekabet yasağıyla elde tutabilirsin. Hiçbir şey yapmazsan gitme ihtimali <b>kaçma riskine</b> ve teklifin cazibesine bağlıdır. Kaçma riski moral, piyasaya göre maaş, yetenek, kıdem, hak edilmemiş opsiyonlar, rekabet yasağı ve yetenek piyasasının sıcaklığına (ekonomik dönem) bağlıdır.</p><p><b>Hisse opsiyonları</b> 4 yılda hak edilir (ilk yıl hiç); senin payından çıkar ama hak edilmemiş kısım güçlü bir bağdır. Rekabet yasağı olmayan biri giderken rakibin teknolojisini güçlendirir ve morali düşük takım arkadaşlarını da götürebilir. <b>Yıldız avı</b> bölümünden rakiplerdeki yetenekleri transfer edebilirsin; rekabet yasağı olanlar dava riski taşır.</p>`)},
 {id:'ceo',c:'pazar',t:(LANG_EN?"Rival CEOs":'Rakip CEO\'lar'),go:'market:ceo',b:(LANG_EN?`<p>Every rival has a CEO with a personality: <b>visionary</b>, <b>combative</b>, <b>conservative</b>, <b>diplomat</b>, <b>opportunist</b> or <b>enigmatic</b>. Personality determines their tendency to attack you in the press, propose partnerships, hold grudges and poach your employees. The relationship ranges from −100 to +100 and drifts back to neutral over time.</p><p><b>Press feud</b>: you can reply sharply or with wit, ignore it, or offer a private meeting. A <b>dinner invitation</b> warms the relationship; <b>jabbing them in the press</b> can help your brand but damages the relationship. With friendly CEOs you can set up <b>joint R&D</b> (research +15%), <b>joint marketing</b> or a <b>non-aggression pact</b>. Hostile CEOs start price wars and target your team with offers more often; peace offers rarely stick with grudge-holding personalities. CEOs change from time to time; a new CEO largely forgets old grudges.</p>`:`<p>Her rakibin kişiliği olan bir CEO'su vardır: <b>vizyoner</b>, <b>kavgacı</b>, <b>muhafazakâr</b>, <b>diplomat</b>, <b>fırsatçı</b> ya da <b>gizemli</b>. Kişilik; basında sana saldırma, ortaklık önerme, kin tutma ve çalışanlarını ayartma eğilimini belirler. İlişki −100 ile +100 arasındadır ve zamanla nötre döner.</p><p><b>Basında atışma</b>: sert, esprili cevap verebilir, görmezden gelebilir ya da özel görüşme teklif edebilirsin. <b>Yemek daveti</b> ilişkiyi ısıtır; <b>basında iğnelemek</b> markana iyi gelebilir ama ilişkiyi bozar. Dostane CEO'larla <b>ortak Ar-Ge</b> (araştırma +%15), <b>ortak pazarlama</b> ya da <b>saldırmazlık paktı</b> yapabilirsin. Düşman CEO'lar daha sık fiyat savaşı açar ve ekibine teklif yapar; barış teklifi kinci kişiliklerde zor tutar. CEO'lar zaman zaman değişir; yeni CEO eski kini büyük ölçüde unutur.</p>`)},
 {id:'cof',c:'ekip',t:(LANG_EN?"Co-founder":'Kurucu ortak'),go:'fin:kurucu',b:(LANG_EN?`<p>In free play, the Garage to the Top and Crisis Years scenarios (and your own scenarios), you can pick a co-founder at the start of the game; you can also find one in Finance → Founder during the first year. A <b>technical</b> co-founder boosts project scores and research, a <b>business development</b> co-founder boosts funding rounds and brand, and a <b>product & design</b> co-founder boosts project scores and press score. In return they take 10–35% of the company; their shares vest over 4 years (nothing in the first year) and are diluted alongside yours in rounds.</p><p>Your co-founder's personality (perfectionist, ambitious, cautious, dreamer) sets their priorities; their satisfaction depends on company profit and whether your decisions match those priorities. Disagreements come up now and then: you can accept, find a middle ground, try to persuade them or refuse. An unhappy co-founder asks for more shares and eventually wants to leave. You can buy back their shares or let them go with their shares; in the latter case they may start a rival company. A happy co-founder stands by you on the board with their shares.</p>`:`<p>Serbest oyunda, Garajdan Zirveye ve Kriz Yılları senaryolarında (ve kendi senaryolarında) oyunun başında bir kurucu ortak seçebilirsin; ilk yıl içinde Finans → Kurucu bölümünden de bulabilirsin. <b>Teknik</b> ortak proje puanlarını ve araştırmayı, <b>iş geliştirme</b> ortağı yatırım turlarını ve markayı, <b>ürün ve tasarım</b> ortağı proje puanlarını ve basın puanını artırır. Karşılığında şirketin %10–35'ini alır; hisseleri 4 yılda hak edilir (ilk yıl hiç) ve turlarda seninle birlikte sulanır.</p><p>Ortağının kişiliği (mükemmeliyetçi, hırslı, temkinli, hayalperest) önceliklerini belirler; memnuniyeti şirketin kârına ve kararlarının bunlara uymasına göre değişir. Zaman zaman anlaşmazlık çıkar: kabul edebilir, orta yolu bulabilir, ikna etmeye çalışabilir ya da reddedebilirsin. Mutsuz ortak daha fazla hisse ister, sonunda ayrılmak ister. Hisselerini geri alabilir ya da hisseleriyle gitmesine izin verebilirsin; ikincisinde rakip bir şirket kurabilir. Memnun bir ortak hisseleriyle yönetim kurulunda yanında durur.</p>`)},
 {id:'debt',c:'urun',t:(LANG_EN?"Tech debt":'Teknik borç'),go:'prod',b:(LANG_EN?`<p>Every product has <b>tech debt</b> from 0 to 100. When starting a project you choose a development approach: <b>fast</b> (25% less work, high debt, more bugs), <b>balanced</b> or <b>solid</b> (20% more work, zero debt, fewer bugs). In software products debt grows on its own every month; overtime and patchy minor updates speed it up, major updates reduce it a bit.</p><p>As debt grows, bugs multiply, updates take longer and engineers' morale drops; above 70 the product can crash and you lose users. A <b>debt cleanup</b> cuts debt by 60%; a <b>rewrite</b> resets it and brings the software up to today's technology, but takes a long time. In Product → Products you can permanently dedicate 10% or 20% of your engineers' time to paying down debt; new projects slow down by that amount.</p>`:`<p>Her ürünün 0–100 arası bir <b>teknik borcu</b> vardır. Proje başlatırken geliştirme yaklaşımını seçersin: <b>hızlı</b> (iş yükü %25 az, borç yüksek, daha çok hata), <b>dengeli</b> ya da <b>sağlam</b> (iş yükü %20 fazla, borç sıfır, daha az hata). Yazılım ürünlerinde borç her ay kendiliğinden büyür; fazla mesai ve yamalı küçük güncellemeler hızlandırır, büyük güncelleme biraz azaltır.</p><p>Borç arttıkça hatalar çoğalır, güncellemeler uzar ve mühendislerin morali düşer; 70'in üstünde ürün çökebilir ve kullanıcı kaybedersin. <b>Borç temizliği</b> borcu %60 azaltır; <b>yeniden yazım</b> sıfırlar ve yazılımı bugünkü teknolojiye taşır ama uzun sürer. Ürün → Ürünler bölümünden mühendislerin zamanının %10'unu ya da %20'sini sürekli borç ödemeye ayırabilirsin; yeni projeler o oranda yavaşlar.</p>`)},
 {id:'hack',c:'ekip',t:(LANG_EN?"Side projects and hackathons":'Yan projeler ve hackathon'),go:'team:fikir',b:(LANG_EN?`<p>When you hold a <b>hackathon</b>, engineers and researchers drop their projects for 3 days to work on their own ideas; morale rises and 2–5 ideas come out. An <b>open hackathon</b> costs more but grows your brand and brings two talented candidates. A hackathon can be held once every 4 months. <b>Side project time</b> (10%) slows projects but boosts morale and occasionally sparks ideas; creative employees come up with more ideas.</p><p>Ideas come in three types: a <b>new product</b> (30% less work since the prototype is ready; quality depends on the idea's potential), an <b>internal tool</b> (permanent improvements such as a test pipeline, developer tools, research automation, a code analysis bot, a hiring platform or support automation) and a <b>feature</b> for an existing product (raises the score by 3–14%). The team's star rating is a guide but may be off; rarely, an ordinary-looking idea turns out to be a hidden gem.</p>`:`<p><b>Hackathon</b> düzenlediğinde mühendisler ve araştırmacılar 3 gün projelerini bırakıp kendi fikirleri üzerinde çalışır; moral artar ve 2–5 fikir çıkar. <b>Açık hackathon</b> daha pahalıdır ama markanı büyütür ve iki yetenekli aday getirir. Hackathon 4 ayda bir yapılabilir. <b>Yan proje zamanı</b> (%10) projeleri yavaşlatır ama moral verir ve ara sıra fikir doğurur; yaratıcı çalışanlar daha çok fikir üretir.</p><p>Fikirler üç türdür: <b>yeni ürün</b> (prototip hazır olduğu için iş yükü %30 az, kalitesi fikrin potansiyeline bağlı), <b>iç araç</b> (test hattı, geliştirici araçları, araştırma otomasyonu, kod analiz botu, işe alım platformu, destek otomasyonu gibi kalıcı iyileştirmeler) ve mevcut bir ürüne <b>özellik</b> (puanı %3–14 artırır). Ekibin yıldız tahmini yol gösterir ama tutmayabilir; nadiren sıradan görünen bir fikir gizli cevher çıkar.</p>`)},
 {id:'remote',c:'ekip',t:(LANG_EN?"Remote and hybrid work":'Uzaktan ve hibrit çalışma'),go:'team:ortam',b:(LANG_EN?`<p>There are three work models. <b>In office</b>: strong team cohesion, hardware and operations teams at full efficiency; capacity limited by office size. <b>Hybrid</b>: with shared desks the office holds 1.6 times as many people, rent drops a bit, and most employees prefer it; a home office stipend is paid per person. <b>Fully remote</b>: the office holds 4 times as many people, rent drops 40%, and more talented, slightly cheaper candidates come from around the world; but team cohesion weakens, hardware (20%) and operations teams slow down, and cyberattack risk rises.</p><p>Every employee has a preference (more want remote after 2020). Employees whose preference is met gain morale every month; those who want the opposite lose it. Team cohesion affects productivity by ±5%, and when it's weak rivals' offers look more tempting. The model can be changed once every 90 days; forcing a return to office from remote can lead some employees to resign. Insisting on the office during a pandemic cuts productivity by 25%.</p>`:`<p>Üç çalışma modeli vardır. <b>Ofiste</b>: takım bağı güçlü, donanım ve operasyon ekipleri tam verimli; kapasite ofis büyüklüğüyle sınırlı. <b>Hibrit</b>: paylaşımlı masalarla ofis 1,6 kat kişi alır, kira biraz düşer, çoğu çalışanın tercihidir; kişi başı ev ofis desteği ödenir. <b>Tamamen uzaktan</b>: ofis 4 kat kişi alır, kira %40 düşer, dünya çapında daha yetenekli ve biraz daha ucuz adaylar gelir; ama takım bağı zayıflar, donanım (%20) ve operasyon ekipleri yavaşlar, siber saldırı riski artar.</p><p>Her çalışanın bir tercihi vardır (2020 sonrası uzaktan çalışmak isteyen artar). Tercihine uyan çalışanın morali her ay artar, tersini isteyenin düşer. Takım bağı üretkenliği ±%5 etkiler ve zayıfsa rakiplerin teklifleri daha cazip gelir. Model 90 günde bir değiştirilebilir; uzaktan çalışmadan ofise zorla dönüş bazı çalışanların istifasına yol açabilir. Salgında ofiste ısrar etmek üretkenliği %25 düşürür.</p>`)},
 {id:'tender',c:'pazar',t:(LANG_EN?"Corporate tenders":'Kurumsal ihaleler'),go:'market:ihale',b:(LANG_EN?`<p>Ministries, municipalities, banks and conglomerates put out tenders for products or services in a specific category. When bidding you choose your product, your price (85–110%) and whether to do thorough preparation. Bids are scored on quality (45%), price (35%), your brand and your <b>tender reputation</b>; domestic companies have an edge in public tenders. Some tenders require certifications (data protection, cybersecurity).</p><p>If you win, you get fixed monthly income for 6–24 months. For hardware you must deliver a set number of devices each month (automatically added to the production plan based on demand); for software you must maintain the product's service level (bug count and freshness). Short deliveries and service breaches bring penalties; after three breaches the contract is terminated, you pay damages, and if it's a public contract you're barred from public tenders for two years. Successfully completed contracts raise your reputation.</p>`:`<p>Bakanlıklar, belediyeler, bankalar ve holdingler belirli bir kategoride ürün ya da hizmet için ihaleye çıkar. Teklif verirken ürününü, fiyatını (%85–110) ve kapsamlı hazırlık yapıp yapmayacağını seçersin. Teklifler kaliteye (%45), fiyata (%35), markana ve <b>ihale itibarına</b> göre puanlanır; kamu ihalelerinde yerli şirket avantajlıdır. Bazı ihaleler sertifika (veri koruma, siber güvenlik) şartı koyar.</p><p>Kazanırsan 6–24 ay boyunca aylık sabit gelir alırsın. Donanımda her ay belirli sayıda cihaz teslim etmelisin (talebe göre üretim planına otomatik eklenir); yazılımda ürünün hizmet seviyesini (hata sayısı ve güncellik) korumalısın. Eksik teslimat ve hizmet ihlalleri ceza getirir; üç ihlalde sözleşme feshedilir, tazminat ödersin ve kamu sözleşmesiyse iki yıl kamu ihalelerinden men edilirsin. Başarıyla tamamlanan sözleşmeler itibarını yükseltir.</p>`)},
 {id:'ailab',c:'arge',t:(LANG_EN?"AI race":'Yapay zekâ yarışı'),go:'res:yz',b:(LANG_EN?`<p>With Machine Learning research you set up your own <b>AI lab</b>. You buy or rent compute nodes (cheaper and more powerful if you have your own AI accelerator chip). You choose the scale of each training run; model capability depends on the logarithm of the compute used, your <b>data score</b> (your users and installed base, licensed datasets), your researchers, and large language model research.</p><p>Rival labs keep releasing new models too; the <b>frontier level</b> rises every year. Your model raises or lowers the appeal of your AI products relative to the frontier; if you sell it via API, you win market share based on its capability versus rivals. Becoming world number one grows your brand. Opening the weights grows your developer community but cuts your API share. If you don't allocate compute to safety research on frontier models, accident risk rises; after 2023 the AI act requires at least a 10% safety share.</p>`:`<p>Makine Öğrenmesi araştırmasıyla kendi <b>yapay zekâ laboratuvarını</b> kurarsın. Hesaplama düğümleri satın alır ya da kiralarsın (kendi yapay zekâ hızlandırıcı çipin varsa daha ucuz ve güçlü). Eğitim turunun ölçeğini seçersin; model yeteneği kullanılan işlem gücünün logaritmasına, <b>veri puanına</b> (kullanıcıların ve kurulu tabanın, lisanslı veri setleri), araştırmacılarına ve büyük dil modelleri araştırmasına bağlıdır.</p><p>Rakip laboratuvarlar da sürekli yeni model çıkarır; <b>öncü seviye</b> her yıl yükselir. Modelin yapay zekâ ürünlerinin çekiciliğini öncüye göre artırır ya da azaltır; API ile satarsan rakiplere göre yeteneğine göre pazar payı alırsın. Dünya birincisi olursan markan büyür. Ağırlıkları açarsan geliştirici topluluğun büyür ama API payın düşer. Öncü modellerde güvenlik araştırmasına işlem gücü ayırmazsan kaza riski artar; 2023'ten sonra yapay zekâ yasası en az %10 güvenlik payı ister.</p>`)},
 {id:'ipl',c:'arge',t:(LANG_EN?"Chip design licensing":'Çip tasarımı lisanslama'),go:'res:lisans',b:(LANG_EN?`<p>With the <b>Licensable Architecture</b> research and a processor of your own on the market, you can license your design to other companies. A company with a <b>core license</b> uses your processor as-is in its devices; you earn royalties on its device revenue. A company with an <b>architecture license</b> designs its own processors on your instruction set; the upfront fee is high, and royalties are a smaller share of its processor revenue.</p><p>You set the royalty rate at 1%, 3% or 5%; a higher rate brings more income but less interest. Acceptance depends on how fresh your design is, your relationship and your rate policy; companies also send requests on their own. Licensees' devices and technology get stronger, so you are feeding your own competition. If 30% of devices run on your architecture, it becomes the <b>industry standard</b>: your devices that use your own processor become 5% more appealing. Occasional audits can uncover underreported royalties.</p>`:`<p><b>Lisanslanabilir Mimari</b> araştırmasıyla ve piyasada kendi işlemcin varken tasarımını başka şirketlere lisanslayabilirsin. <b>Çekirdek lisansı</b> alan şirket işlemcini olduğu gibi cihazlarında kullanır; cihaz gelirlerinden telif alırsın. <b>Mimari lisansı</b> alan şirket senin komut setinle kendi işlemcilerini tasarlar; ilk ücret yüksek, telif işlemci gelirlerinin daha küçük bir kısmıdır.</p><p>Telif oranını %1, %3 ya da %5 seçersin; yüksek oran gelir getirir ama ilgiyi azaltır. Kabul ihtimali tasarımının güncelliğine, ilişkine ve oran politikana bağlıdır; şirketler de kendiliğinden talep gönderir. Lisans alanların cihazları ve teknolojileri güçlenir, yani rekabeti kendin beslersin. Cihazların %30'u senin mimarinle çalışırsa mimarin <b>endüstri standardı</b> olur: kendi işlemcini kullanan cihazların %5 daha çekici olur. Ara sıra yapılan denetimler eksik bildirilen telifleri ortaya çıkarabilir.</p>`)},
 {id:'a11y',c:'bas',t:(LANG_EN?"Display and accessibility":'Görüntü ve erişilebilirlik'),go:'fin:kayit',b:(LANG_EN?`<p>Under Finance → Save & settings (or Ctrl+K → "accessibility") you can adjust the theme (system, light, dark), text and interface size (90%–130%; up to 115% on narrow screens), motion and animation level, high contrast, colorblind-friendly colors (blue–orange instead of green–red), a legible font (Atkinson Hyperlegible) and how long notifications stay on screen. Settings are stored in this browser and apply to all your companies.</p>`:`<p>Finans → Kayıt ve ayarlar bölümünden (ya da Ctrl+K → "erişilebilirlik") temayı (sistem, açık, koyu), yazı ve arayüz boyutunu (%90–%130; dar ekranlarda en fazla %115), hareket ve animasyon düzeyini, yüksek kontrastı, renk körlüğü dostu renkleri (yeşil–kırmızı yerine mavi–turuncu), okunaklı yazı tipini (Atkinson Hyperlegible) ve bildirimlerin ekranda kalma süresini ayarlayabilirsin. Ayarlar bu tarayıcıda saklanır ve bütün şirketlerinde geçerlidir.</p>`)},
 {id:'photo',c:'bas',t:(LANG_EN?"Photo mode":'Fotoğraf modu'),go:'office',b:(LANG_EN?`<p>The <b>Photo mode</b> button in the Office view (or Ctrl+K → "photo") creates a shareable card from the current view of your office. You can choose from four frames (Polaroid, magazine cover, plain, postcard), five filters (natural, warm, night, black-and-white, retro) and three sizes (portrait, square, landscape), write your own caption, and add your valuation, team and brand info. The card downloads as a PNG. For a night shot or a busier office, let the game run a bit and press "Retake".</p>`:`<p>Ofis görünümündeki <b>Fotoğraf modu</b> düğmesi (ya da Ctrl+K → "fotoğraf") ofisinin o anki görüntüsünden paylaşılabilir bir kart hazırlar. Dört çerçeve (Polaroid, dergi kapağı, sade, kartpostal), beş filtre (doğal, sıcak, gece, siyah-beyaz, retro) ve üç boyut (dikey, kare, yatay) arasından seçebilir, kendi alt yazını yazabilir, değerleme, ekip ve marka bilgilerini ekleyebilirsin. Kart PNG olarak indirilir. Gece görüntüsü ya da kalabalık bir ofis için oyunu biraz oynatıp "Yeniden çek"e bas.</p>`)},
 {id:'gallery',c:'bas',t:(LANG_EN?"Scenario gallery":'Senaryo galerisi'),go:'dash',b:(LANG_EN?`<p>You can share scenarios you built in the scenario editor in the <b>community gallery</b> (up to 3). The gallery is at the bottom of the New game → Choose scenario window. You can play and like other players' scenarios, and sort them by most liked or newest, or search them. A gallery scenario you start playing is also copied to your My scenarios list. You can remove your own scenario from the gallery at any time.</p>`:`<p>Senaryo editöründe hazırladığın senaryoları <b>topluluk galerisinde</b> paylaşabilirsin (en fazla 3). Galeri, Yeni oyun → Senaryo seç penceresinin en altındadır. Diğer oyuncuların senaryolarını oynayabilir, beğenebilir, en beğenilene ya da en yeniye göre sıralayıp arayabilirsin. Oynamaya başladığın galeri senaryosu Senaryolarım listesine de kopyalanır. Kendi senaryonu istediğin zaman galeriden kaldırabilirsin.</p>`)},
 {id:'sgrid',c:'pazar',t:(LANG_EN?"Store grid and pricing policy":'Mağaza ızgarası ve fiyat politikası'),go:'market:magaza',b:(LANG_EN?`<p>Click a store's name in the store chain to open its grid: a mall kiosk is 2×1, a store 3×2 and a flagship 3×3 cells. At first every cell is a sales counter.</p><ul><li><b>Purchasing:</b> The sales counters next to it sell 35% more. It takes a counter's place; in a flagship the center works best.</li><li><b>Display and advertising:</b> +5 awareness in the store's city (Market → Cities).</li><li><b>Training and service:</b> Customer satisfaction for hardware products rises a little each month.</li><li>A unit costs 12% of the store's price; switching back to a sales counter refunds 40%.</li></ul><p><b>Pricing policy:</b> A discount store sells 25% more but the retail margin drops to 10%; Premium sells 15% less but the margin is 30%; Normal is 20%.</p><p>You can choose a new store's city from the list on the region card; the cities' income profiles are shown there too. Stores permanently raise awareness in their city.</p>`:`<p>Mağaza zincirindeki bir mağazanın adına tıklayınca ızgarası açılır: AVM standı 2×1, mağaza 3×2, amiral mağaza 3×3 hücredir. Başlangıçta bütün hücreler satış tezgâhıdır.</p><ul><li><b>Satın alma:</b> Yanındaki satış tezgâhları %35 daha çok satar. Bir tezgâhın yerini alır; amiral mağazada ortaya koymak en verimlisidir.</li><li><b>Vitrin ve reklam:</b> Mağazanın bulunduğu şehirde bilinirlik +5 (Pazar → Şehirler).</li><li><b>Eğitim ve servis:</b> Donanım ürünlerinin müşteri memnuniyeti her ay biraz artar.</li><li>Birim kurmak mağaza bedelinin %12'si kadardır; satış tezgâhına geri dönersen %40'ı iade edilir.</li></ul><p><b>Fiyat politikası:</b> İndirimli mağaza %25 daha çok satar ama perakende payı %10'a düşer; Premium %15 daha az satar ama pay %30 olur; Normal %20'dir.</p><p>Yeni mağazanın şehrini bölge kartındaki listeden seçebilirsin; şehirlerin gelir profili de orada yazar. Mağazalar bulundukları şehrin bilinirliğini kalıcı olarak artırır.</p>`)},
 {id:'cmap',c:'pazar',t:(LANG_EN?"City map and real estate":'Şehir haritası ve gayrimenkul'),go:'market:sehir',b:(LANG_EN?`<p>On Market → Cities, click a city to open its 5×4 plot map. There are four zones from the center outward: <b>Downtown</b> (lots of traffic, very expensive land), <b>Business district</b>, <b>Residential area</b> and <b>Outskirts</b> (quiet and cheap).</p><ul><li><b>Store:</b> Click a plot to open a store right there. The store's sales power grows with the plot's traffic (by its square root), and its rent rises with the land price. A flagship downtown is expensive but strong.</li><li><b>Real estate:</b> You can build an office building, housing or a mall on an empty plot. Once finished it earns rent every month; the return is higher when the building suits the zone (offices in the business district or downtown, housing in residential areas, malls downtown or in the business district). Occupancy drops in a recession.</li><li><b>Rival stores:</b> Strong rivals that sell hardware also open stores in cities, preferably downtown and in the business district; they show on the map in gray with their initial, and those plots are taken. A rival's store network in a region makes its hardware products up to 6% more appealing there.</li><li>Buildings gain about 3% in value each year and can be sold for 97% of their value. Real estate value appears on the balance sheet.</li></ul>`:`<p>Pazar → Şehirler sayfasında bir şehre tıklayınca 5×4 arsalık haritası açılır. Merkezden dışa doğru dört bölge vardır: <b>Merkez</b> (trafik çok, arsa çok pahalı), <b>İş bölgesi</b>, <b>Konut bölgesi</b> ve <b>Çevre</b> (sakin ve ucuz).</p><ul><li><b>Mağaza:</b> Bir arsaya tıklayıp doğrudan mağaza açabilirsin. Mağazanın satış gücü arsanın trafiğiyle (karekökü kadar) artar, kirası arsa fiyatıyla yükselir. Merkezde amiral mağaza pahalı ama güçlüdür.</li><li><b>Gayrimenkul:</b> Boş arsaya ofis binası, konut ya da AVM yapabilirsin. Bitince her ay kira getirir; getiri yapı bölgesine uygunsa (ofis iş bölgesinde ya da merkezde, konut konut bölgesinde, AVM merkezde ya da iş bölgesinde) daha yüksektir. Durgunlukta doluluk düşer.</li><li><b>Rakip mağazaları:</b> Donanım satan güçlü rakipler de şehirlere, tercihen merkez ve iş bölgesine mağaza açar; haritada gri ve baş harfleriyle görünür, o arsalar doludur. Bir rakibin bölgedeki mağaza ağı onun donanım ürünlerini o bölgede en çok %6 daha çekici yapar.</li><li>Yapılar her yıl yaklaşık %3 değer kazanır ve değerinin %97'sine satılabilir. Gayrimenkulün değeri bilançoda görünür.</li></ul>`)},
 {id:'pboard',c:'urun',t:(LANG_EN?"Production board":'Üretim panosu'),go:'dev',b:(LANG_EN?`<p>On the production board of the Development page you manage your team and component depot by hand. Drag a card and drop it on a target; on a phone, tap the card first, then the target.</p><ul><li><b>Drop on a project:</b> The developer moves to that project's work for their role.</li><li><b>Drop on a component station:</b> While idle, the developer produces only that component for the depot (even if depot production is off). The station's progress shows on its bar. When assigned to a project they work on it; when the project ends they return to their station.</li><li><b>Drop on the Auto area:</b> When idle, the developer produces the component the depot needs most.</li><li><b>Drop a component on a project:</b> The depot component is given as far as the project needs it, and the project speeds up by that much.</li><li><b>Auto distribution:</b> When on, projects take missing components from the depot automatically. If you turn it off, components wait in the depot and you decide which project gets a scarce component.</li></ul>`:`<p>Geliştirme sayfasındaki üretim panosunda ekibini ve bileşen deposunu elle yönetirsin. Bir kartı sürükleyip bir hedefe bırak; telefonda önce karta, sonra hedefe dokun.</p><ul><li><b>Projeye bırak:</b> Geliştirici o projenin kendi rolündeki işine geçer.</li><li><b>Bileşen istasyonuna bırak:</b> Geliştirici boşta kaldığı sürece depoya yalnızca o bileşeni üretir (depo üretimi kapalı olsa bile). İstasyonun ilerlemesi çubukta görünür. Bir projeye atanınca projede çalışır; proje bitince istasyonuna döner.</li><li><b>Otomatik alana bırak:</b> Geliştirici boşta kaldığında depoya en çok gereken bileşeni üretir.</li><li><b>Bileşeni projeye bırak:</b> Depodaki bileşen, o projenin ihtiyacı kadar verilir ve proje o kadar hızlanır.</li><li><b>Otomatik dağıtım:</b> Açıkken projeler eksik bileşenleri depodan kendiliğinden alır. Kapatırsan bileşenler depoda bekler; kıt bileşenin hangi projeye gideceğine sen karar verirsin.</li></ul>`)},
 {id:'b2b',c:'pazar',t:(LANG_EN?"Wholesale trade":'Toptan ticaret'),go:'market:toptan',b:(LANG_EN?`<p>You trade with rivals business to business. Offers arrive every month; orders you don't take are picked up by another rival and cash changes hands between rivals (shown in the market log).</p><ul><li><b>Component market:</b> You sell components that idle developers produced into the depot to rivals for about 75% of their build cost. If you sell a lot of the same component, demand and price fall; they recover every month. You can also buy component lots that rivals sell, at a premium; they go into the depot and projects use missing components from there automatically.</li><li><b>Contract manufacturing:</b> Rivals rent idle capacity in your assembly factory for months; they pay a net fee per unit. Your own products take priority. If a month's delivery falls below 80% of the target, you pay a penalty of half the fee for the shortfall and the relationship suffers. To accept, an assembly factory that can make the product must have free capacity of at least 80% of the order.</li><li><b>Raw material contracts:</b> A rival buys your mine's output for 12 months at a fixed premium over the market. The contract is filled from the mine's surplus; if that is not enough, the shortfall is bought on the market at 5% more and delivered. To accept, you need a mine for that raw material, and the total of contracts for one raw material cannot exceed the mine's production capacity.</li><li><b>Contract line from a rival (buying):</b> When your capacity falls short, rivals lease you a line of their assembly capacity. The offer is sized to one of your products; when you accept, that product moves to the line automatically, and the line also appears in the production site list on the Manufacturing page. The unit fee is fixed at signing (60–85% of Delta Contract Assembly, unaffected by energy shocks) and the defect rate is lower; it is still more expensive than your own factory. Take-or-pay: after the first 30 days, if a month's use falls below 50% of the reserved capacity, you pay the difference. When the contract ends, products return to the default site.</li><li><b>Raw materials from a rival (buying):</b> As you use raw materials, rivals offer 12-month fixed-price supply. A fixed amount arrives every month at the signing price; that part of your use is covered at this price instead of the market and flows into part prices. Whatever you don't use is sold at the market price at month end. Unlike a futures deal there is no fee and you actually receive the goods, but the amount is fixed.</li><li>You can end contracts early: the cancellation fee is one month's amount and the relationship suffers. Every month you deliver improves the relationship a little.</li></ul>`:`<p>Rakiplerle firmalar arası ticaret yaparsın. Teklifler her ay gelir; senin almadığın siparişleri başka bir rakip üstlenir ve nakit rakipler arasında el değiştirir (piyasa günlüğünde görünür).</p><ul><li><b>Bileşen pazarı:</b> Boştaki geliştiricilerin depoya ürettiği bileşenleri rakiplere yapım maliyetinin yaklaşık %75'ine satarsın. Aynı bileşeni çok satarsan talep ve fiyat düşer, her ay toparlanır. Rakiplerin sattığı bileşen lotlarını da primle alabilirsin; depoya girer ve projeler eksik bileşenleri oradan otomatik kullanır.</li><li><b>Fason üretim:</b> Rakipler montaj fabrikandaki boş kapasiteyi aylarca kiralar; birim başına net ücret ödenir. Kendi ürünlerin önceliklidir. Bir ayın teslimatı hedefin %80'inin altında kalırsa eksiğin yarı ücreti kadar ceza ödersin ve ilişki bozulur. Kabul etmek için o ürünü yapabilen montaj fabrikanda siparişin en az %80'i kadar boş kapasite olmalı.</li><li><b>Ham madde sözleşmeleri:</b> Bir rakip, madeninin üretimini 12 ay boyunca piyasanın üstünde sabit bir primle alır. Sözleşme madenin artan üretiminden karşılanır; yetmezse eksik piyasadan %5 pahalıya alınıp teslim edilir. Kabul etmek için o ham maddenin madeni olmalı ve bir ham madde için sözleşmelerin toplamı madenin üretim kapasitesini aşamaz.</li><li><b>Rakipten fason hattı (alış):</b> Kapasiten yetmediğinde rakipler montaj kapasitelerinden sana bir hat kiralar. Teklif senin bir ürününe göre boyutlanır; kabul edince o ürün kendiliğinden bu hatta taşınır ve hat Üretim sayfasındaki üretim yeri listesine de girer. Birim ücret imzada sabitlenir (Delta fasonun %60–85'i, enerji şoklarından etkilenmez) ve hata oranı daha düşüktür; kendi fabrikandan yine de pahalıdır. Al ya da öde: ilk 30 günden sonra bir ayın kullanımı ayrılan kapasitenin %50'sinin altında kalırsa farkı ödersin. Sözleşme bitince ürünler varsayılan tesise döner.</li><li><b>Rakipten ham madde (alış):</b> Ham madde kullandıkça rakipler 12 aylık sabit fiyatlı tedarik önerir. Her ay sabit miktar, imzadaki fiyatla gelir; kullanımının o kısmı piyasa yerine bu fiyattan karşılanır ve parça fiyatlarına yansır. Kullanmadığın kısım ay sonunda piyasa fiyatından satılır. Vadeli anlaşmadan farkı: ücret yoktur ve malı gerçekten alırsın, ama miktar sabittir.</li><li>Sözleşmeleri erken bitirebilirsin: cayma bedeli bir aylık tutardır ve ilişki bozulur. Teslim ettiğin her ay ilişki biraz iyileşir.</li></ul>`)},
 {id:'media',c:'pazar',t:(LANG_EN?"Media company":'Medya şirketi'),go:'market:medya',b:(LANG_EN?`<p>You can found your own tech publication (news site, reviews, videos). Founding it is a one-time investment; after that you spend your chosen content budget every month.</p><ul><li><b>Audience:</b> The content budget, credibility and your brand grow the audience. Ad revenue comes per viewer, but there is also a distribution and server cost per viewer. A small publication loses money and a mature one makes a small profit; the real benefit is the ad discount and appeal below.</li><li><b>Ad discount:</b> As the audience grows, your own products' ad campaigns get cheaper (30% at 3 million viewers).</li><li><b>Promotion policy:</b> An independent publication gains credibility every month. Balanced and aggressive policies add appeal to your own products but erode credibility; when credibility drops, the audience shrinks.</li><li>You can sell the publication for 0.8 times its annual ad revenue. Its value appears on the balance sheet.</li></ul>`:`<p>Kendi teknoloji yayınını kurabilirsin (haber sitesi, incelemeler, videolar). Kuruluşu tek seferlik bir yatırımdır; sonra her ay seçtiğin içerik bütçesini harcarsın.</p><ul><li><b>İzleyici:</b> İçerik bütçesi, güvenilirlik ve markan izleyiciyi büyütür. İzleyici başına reklam geliri gelir; buna karşılık izleyici başına dağıtım ve sunucu gideri de vardır. Küçük yayın zarar eder, olgun bir yayın küçük bir kâr getirir; asıl faydası aşağıdaki reklam indirimi ve çekiciliktir.</li><li><b>Reklam indirimi:</b> İzleyici büyüdükçe kendi ürünlerinin reklam kampanyaları ucuzlar (3 milyon izleyicide %30).</li><li><b>Tanıtım politikası:</b> Bağımsız yayın her ay güvenilirlik kazanır. Dengeli ve agresif politikalar kendi ürünlerine çekicilik katar ama güvenilirliği aşındırır; güvenilirlik düşünce izleyici azalır.</li><li>Yayını yıllık reklam gelirinin 0,8 katına satabilirsin. Değeri bilançoda görünür.</li></ul>`)},
 {id:'city',c:'pazar',t:(LANG_EN?"Cities":'Şehirler'),go:'market:sehir',b:(LANG_EN?`<p>Each region splits into 4–6 cities: Istanbul, Berlin, London, New York, San Francisco, Tokyo, Shanghai, São Paulo and more. Every city has its own population share, income profile (price-focused, balanced, affluent) and tastes: Paris and Tokyo love design, Berlin loves privacy, San Francisco loves performance and AI, Bursa and Bangkok love low cost. Each city also has favorite features.</p><ul><li>A region's total demand doesn't change. Your product's appeal in a region is multiplied by the population-weighted average of awareness and taste fit across its cities; affluent cities weigh more for discerning buyers, price-focused cities for price-focused buyers.</li><li><b>Awareness</b> starts at 50. A local campaign adds 25 points, and the effect fades a little each month. Your stores in that city add a permanent boost (a flagship store +20).</li><li><b>Taste fit</b> comes from the design focus and features: a product that emphasizes what a city loves and has its favorite features sells more there.</li><li>On the city page you can see each product's city multiplier, the features loved there and the local competition. Estimated revenue splits last month's regional revenue across the cities.</li></ul>`:`<p>Her bölge 4–6 şehre ayrılır: İstanbul, Berlin, Londra, New York, San Francisco, Tokyo, Şanghay, São Paulo gibi. Her şehrin nüfus payı, gelir profili (fiyat odaklı, dengeli, varlıklı) ve zevki vardır: Paris ve Tokyo tasarımı, Berlin gizliliği, San Francisco performansı ve yapay zekâyı, Bursa ve Bangkok düşük maliyeti sever. Her şehrin sevdiği özellikler de vardır.</p><ul><li>Bölgenin toplam talebi değişmez. Ürünün bölgedeki çekiciliği, şehirlerdeki bilinirlik ve zevk uyumunun nüfusla ağırlıklı ortalamasıyla çarpılır; varlıklı şehirler seçici kitlede, fiyat odaklı şehirler fiyat odaklı kitlede daha çok ağırlık taşır.</li><li><b>Bilinirlik</b> varsayılan olarak 50'dir. Yerel kampanya onu 25 puan artırır, etkisi her ay biraz söner. O şehirdeki mağazaların kalıcı katkı verir (amiral mağaza +20).</li><li><b>Zevk uyumu</b> tasarım odağından ve özelliklerden gelir: şehrin sevdiği niteliği öne çıkaran ve sevdiği özelliklere sahip ürün orada daha çok satar.</li><li>Şehir sayfasında ürünlerinin şehir çarpanını, orada sevilen özellikleri ve yerel rekabeti görebilirsin. Tahmini gelir, geçen ayın bölge gelirinin şehirlere paylaştırılmasıdır.</li></ul>`)},
 {id:'fairs',c:'pazar',t:(LANG_EN?"Trade shows & sponsorship":'Fuarlar ve sponsorluk'),go:'market:fuar',b:(LANG_EN?`<p>There are six major trade shows a year: CES (January, Las Vegas), MWC (February, Barcelona), Computex (June, Taipei), Gamescom (August, Cologne), Teknofest (September, Istanbul), Web Summit (November, Lisbon). Each has different focus categories. At least 14 days ahead you book a <b>booth</b>, a <b>large pavilion</b> or a <b>keynote</b> (brand 30+) and put a product on display.</p><p>On show day the featured product becomes more appealing for 45 days (product quality amplifies the effect), your other products in the focus categories benefit too, and brand and regional awareness rise. Above-standard products can win <b>Best of Show</b>.</p><p><b>Sponsorships</b> give an ongoing effect for a monthly fee: an esports team, a soccer jersey, a music festival, university hackathons (developer community and candidate quality), Formula 1 (brand 40+). They boost appeal with specific audiences and categories, plus brand and regional awareness every month. Contracts run at least one year; ending early costs 3 months' fees.</p>`:`<p>Yılda altı büyük fuar var: CES (Ocak, Las Vegas), MWC (Şubat, Barselona), Computex (Haziran, Taipei), Gamescom (Ağustos, Köln), Teknofest (Eylül, İstanbul), Web Summit (Kasım, Lizbon). Her birinin odak kategorileri farklıdır. En geç 14 gün önce <b>stand</b>, <b>büyük pavyon</b> ya da <b>ana sahne konuşması</b> (marka 30+) ayırır ve vitrine bir ürün koyarsın.</p><p>Fuar gününde vitrindeki ürün 45 gün daha çekici olur (ürünün kalitesi etkiyi büyütür), odak kategorilerdeki diğer ürünlerin de faydalanır; marka ve bölge bilinirliği artar. Standardın üstündeki ürünler <b>Fuarın en iyisi</b> ödülünü kazanabilir.</p><p><b>Sponsorluklar</b> aylık ücretle sürekli etki verir: e-spor takımı, futbol forması, müzik festivali, üniversite hackathonları (geliştirici topluluğu ve aday kalitesi), Formula 1 (marka 40+). Belirli kitle ve kategorilerde çekicilik, her ay marka ve bölge bilinirliği sağlar. Sözleşmeler en az bir yıllıktır; erken bitirmenin cezası 3 aylık bedeldir.</p>`)},
 {id:'inbox',c:'bas',t:(LANG_EN?"News and decision inbox":'Haberler ve karar kutusu'),go:'dash',b:(LANG_EN?`<p>News appears in the one-line ticker in the top bar; consecutive news of the same type is merged. Clicking the ticker or the <b>News</b> button opens the last 30 stories. Floating notifications only report the results of your own actions.</p><p>Decisions pile up in the <b>decision inbox</b> and the game keeps running: board meetings, CEO spats, lawsuits, unions, price wars, quality issues and more. Each decision has a deadline; if it expires, the default option shown on the card is applied. Emergencies such as ransomware attacks, hostile takeovers and boardroom coups still pause the game. If you prefer the old behavior, turn off the decision inbox under Finance → Save & settings. The <b>Month end</b> button fast-forwards to the end of the month and pauses.</p>`:`<p>Haberler üst çubuktaki tek satırlık akışta görünür; aynı türden haberler art arda gelirse birleşir. Akışa ya da <b>Haberler</b> düğmesine tıklayınca son 30 haber açılır. Yüzen bildirim yalnızca senin yaptığın işlerin sonucunu söyler.</p><p>Kararlar <b>karar kutusunda</b> birikir ve oyun durmaz: kurul toplantısı, CEO atışması, dava, sendika, fiyat savaşı, kalite sorunu gibi. Her kararın bir süresi vardır; süre dolarsa kartta yazılı varsayılan seçenek uygulanır. Fidye saldırısı, düşmanca devralma ve kurul darbesi gibi acil olaylar oyunu yine durdurur. Eski davranışı istersen Finans → Kayıt ve ayarlar bölümünden karar kutusunu kapat. <b>Ay sonu</b> düğmesi oyunu ay bitene kadar hızlı oynatıp duraklatır.</p>`)},
 {id:'pitch',c:'finans',t:(LANG_EN?"Investor pitch":'Yatırımcı sunumu'),go:'fin',b:(LANG_EN?`<p>You can take a funding round in one click or <b>pitch</b> for it. First you pick one of three funds: a <b>growth fund</b> looks at growth and market, a <b>cautious fund</b> at profitability, cash and risk, a <b>tech fund</b> at product, team and culture. The fund asks four questions, and each shows your real numbers. <b>Lead with numbers</b> works best on your strong points. <b>Paint a big vision</b> works on strong points, but on weak ones your exaggeration may be caught. <b>Pivot to your strengths</b> steers the topic to your best area, but tough funds dislike it.</p><p>At the end, investor interest sets the valuation between ×0.8 and ×1.25. If interest is high, you may also be offered a <b>board seat</b> (+6%, board confidence −6) or a <b>milestone</b> deal (+15%; 40% of the money arrives if you grow monthly revenue 30% within 12 months). If interest is above 70, you can try <b>creating competition</b> to raise the offer; the fund may also walk away. If you reject the offer, funds won't talk to you for 60 days for that round.</p>`:`<p>Bir yatırım turunu tek tıkla alabilir ya da <b>sunum yapabilirsin</b>. Önce üç fondan birini seçersin: <b>büyüme fonu</b> büyümeye ve pazara, <b>temkinli fon</b> kârlılık, nakit ve riske, <b>teknoloji fonu</b> ürün, ekip ve kültüre bakar. Fon dört soru sorar; her soruda gerçek rakamın gösterilir. <b>Rakamlarla anlatmak</b> güçlü olduğun konuda en etkilisidir. <b>Vizyonu büyük çizmek</b> güçlü konularda işe yarar, zayıf konularda abartın yakalanabilir. <b>Güçlü yanına çekmek</b> konuyu en iyi alanına taşır, ama sert fonlar bunu sevmez.</p><p>Sunum sonunda yatırımcının ilgisi değerlemeyi ×0,8 ile ×1,25 arasında belirler. İlgi yüksekse <b>kurul koltuğu</b> (+%6, kurul güveni −6) ya da <b>kilometre taşlı</b> yatırım (+%15; paranın %40'ı, 12 ayda aylık gelirini %30 artırırsan gelir) da teklif edilir. İlgi 70'in üstündeyse <b>rekabet yaratıp</b> teklifi yükseltmeyi deneyebilirsin; fon masadan da kalkabilir. Teklifi reddedersen fonlar o tur için 60 gün görüşmez.</p>`)},
 {id:'culture',c:'ekip',t:(LANG_EN?"Company culture":'Şirket kültürü'),go:'team:kultur',b:(LANG_EN?`<p>You choose up to three company values: speed, quality, transparency, customer obsession, work-life balance, experimentation or drive to win. Some conflict with each other. Each value has an effect that scales with <b>culture strength</b>. Strength grows over time and with decisions that fit your values. Contradicting decisions weaken it: choosing balance and then going to crunch, laying people off while valuing transparency, halting research while valuing experimentation. Rapid growth and low engagement while working remotely also lower strength.</p><p>A strong culture raises morale and candidate quality, and investors ask about it in pitches. Dilemmas that test your values come up from time to time. Changing values costs 60% of your strength and lowers morale; you can do it once every 180 days.</p>`:`<p>En fazla üç şirket değeri seçersin: hız, kalite, şeffaflık, müşteri takıntısı, iş-yaşam dengesi, deneycilik ya da kazanma hırsı. Bazıları birbiriyle çatışır. Her değerin bir etkisi vardır ve bu etki <b>kültür gücüyle</b> ölçeklenir. Güç zamanla ve değerlere uygun kararlarla artar. Çelişen kararlar zayıflatır: dengeyi seçip yoğun tempoya geçmek, şeffaflık varken işten çıkarmak, deneycilikte araştırmayı durdurmak gibi. Hızlı büyüme ve uzaktan çalışmada düşük bağlılık da gücü düşürür.</p><p>Güçlü kültür morali ve aday kalitesini yükseltir; yatırımcı sunumlarında da sorulur. Zaman zaman değerlerini sınayan ikilemler çıkar. Değerleri değiştirmek gücün %60'ını götürür ve morali düşürür; 180 günde bir yapılabilir.</p>`)},
 {id:'era',c:'finans',t:(LANG_EN?"Era events":'Dönem olayları'),go:'fin:ekonomi',b:(LANG_EN?`<p>From 2015 to 2030, developments inspired by the real world happen on a schedule: Brexit, a ransomware outbreak, crypto mania, the EU data regulation, the lira crisis, 5G, the chip shortage, generative AI, a wave of layoffs, tariffs and more. Major events surface about 45 days in advance; under Finance → Economy you can see what has happened and what is on the horizon. You can turn events off in any game.</p>`:`<p>2015–2030 arasında gerçek dünyadan esinlenen gelişmeler takvime bağlı olarak yaşanır: Brexit, fidye yazılımı salgını, kripto çılgınlığı, AB veri tüzüğü, lira krizi, 5G, çip kıtlığı, üretken yapay zekâ, işten çıkarma dalgası, gümrük tarifeleri ve sonrası. Büyük olaylar yaklaşık 45 gün önce gündeme düşer; Finans → Ekonomi bölümünde yaşananları ve ufuktakini görürsün. Olayları her oyunda kapatabilirsin.</p>`)},
 {id:'recall',c:'urun',t:(LANG_EN?"Quality and recalls":'Kalite ve geri çağırma'),go:'mfg',b:(LANG_EN?`<p>Hardware products carry a risk of failure in the field. Fast development, crunch, an inexperienced hardware team and a factory with a high defect rate increase the risk; a robust approach, beta testing and <b>quality control</b> reduce it. When a failure surfaces there are four options: a <b>voluntary recall</b> (expensive, but trust is preserved), <b>free repairs</b> (half the cost, may turn into a mandatory recall), a <b>silent fix</b> or <b>denial</b> (cheap, but if exposed it means a big scandal, fines and a mandatory recall). Every recall lowers the risk for later products in that category.</p>`:`<p>Donanım ürünlerinin sahada arıza riski vardır. Hızlı geliştirme, yoğun tempo, deneyimsiz donanım ekibi ve hata oranı yüksek üretim tesisi riski artırır; sağlam yaklaşım, beta testi ve <b>kalite denetimi</b> azaltır. Arıza çıkınca dört yol var: <b>gönüllü geri çağırma</b> (pahalı ama güven korunur), <b>ücretsiz onarım</b> (yarı maliyet, zorunlu geri çağırmaya dönüşebilir), <b>sessiz düzeltme</b> ya da <b>reddetmek</b> (ucuz ama ortaya çıkarsa büyük skandal, ceza ve zorunlu geri çağırma). Her geri çağırma o kategorideki sonraki ürünlerin riskini düşürür.</p>`)},
 {id:'refurb',c:'urun',t:(LANG_EN?"Refurbished and secondhand products":'Yenilenmiş ürünler ve ikinci el'),go:'refurb',b:(LANG_EN?`<p>Your devices that are over a year old or discontinued enter the secondhand market; some bargain hunters buy them instead of a new product (up to 10% in the budget segment). Devices leave the market after about five years. A <b>refurbishment program</b> collects these devices and resells them with a warranty: the lost sales disappear, and you gain extra revenue and sustainability points. <b>Trade-in</b> gives a discount to buyers of a new device; it boosts appeal in the mainstream and enthusiast segments, but you pay for the discount.</p>`:`<p>Bir yıldan eski ya da satıştan kalkmış cihazların ikinci el pazarına düşer; ucuz cihaz arayanların bir kısmı yeni ürünün yerine onları alır (fiyat odaklı kesimde en fazla %10). Cihazlar yaklaşık beş yılda piyasadan çekilir. <b>Yenileme programı</b> bu cihazları toplayıp garantili olarak satar: kayıp ortadan kalkar, ek gelir ve sürdürülebilirlik puanı gelir. <b>Takas</b> yeni cihaz alana indirim verir; ana akım ve meraklı kesimde çekiciliği artırır ama indirimi sen ödersin.</p>`)},
 {id:'merger',c:'pazar',t:(LANG_EN?"Rival mergers":'Rakip birleşmeleri'),go:'market:pay',b:(LANG_EN?`<p>Profitable rivals merge from time to time: the new company's cash, brand and technology grow stronger, and laid-off staff join the candidate pool. If a merger affects your markets, you get notified: you can <b>object to the Competition Authority</b> (more effective if their combined share is high), make a <b>counteroffer</b> for the smaller company and buy it yourself, or just watch. The authority usually blocks mergers that would hold over 50% share on its own.</p>`:`<p>Kârlı rakipler zaman zaman birleşir: yeni şirketin nakdi, markası ve teknolojisi güçlenir, kadrodan çıkarılanlar aday havuzuna düşer. Birleşme senin pazarlarını etkiliyorsa haber alırsın: <b>Rekabet Kurumu'na itiraz</b> edebilir (ortak pay yüksekse daha etkili), küçük şirkete <b>karşı teklif</b> verip onu kendin alabilir ya da izleyebilirsin. Birlikte %50'nin üzerinde pay tutacak birleşmeleri kurum çoğu zaman kendisi durdurur.</p>`)},
 {id:'bundle',c:'urun',t:(LANG_EN?"Subscription bundle":'Abonelik paketi'),go:'bundle',b:(LANG_EN?`<p>If you have at least two subscription-based software products (paid or freemium apps, enterprise software, AI services), you can create a bundle offering all of them for one price. Bundled products' <b>churn drops by up to 40%</b>, the products become more appealing (+3% per extra product, plus the discount) and subscribers try your other products too.</p><p>The cost: subscribers who switch to the bundle pay a discounted price, so revenue per user drops. Bigger discounts drive more adoption (up to 60%). A <b>family plan</b> raises the price 1.5x; it increases adoption and loyalty, but since several paying users merge into one account, revenue per user drops. Bundles with three or more products grow your brand a little every month. Removing products from the bundle or cutting the discount angers subscribers; shutting the bundle down lowers satisfaction.</p>`:`<p>Aboneliğe dayalı en az iki yazılım ürünün varsa (ücretli ya da freemium uygulama, kurumsal yazılım, yapay zekâ hizmeti) hepsini tek fiyatla sunan bir paket kurabilirsin. Paketteki ürünlerin <b>kayıp oranı %40'a kadar düşer</b>, ürünler daha çekici olur (her ek ürün +%3, indirim ayrıca) ve aboneler diğer ürünlerini de dener.</p><p>Bedeli: pakete geçen aboneler indirimli öder, kullanıcı başı gelir düşer. İndirim büyüdükçe benimseme artar (en fazla %60). <b>Aile planı</b> fiyatı 1,5 katına çıkarır; benimsemeyi ve sadakati artırır ama birden çok ödeyen kullanıcı tek hesapta toplandığı için kullanıcı başı gelir düşer. Üç ve daha fazla ürünlü paket markayı her ay biraz büyütür. Paketten ürün çıkarmak ya da indirimi azaltmak aboneleri kızdırır; paketi kapatmak memnuniyeti düşürür.</p>`)},
 {id:'shops',c:'pazar',t:(LANG_EN?"Store chain":'Mağaza zinciri'),go:'market:magaza',b:(LANG_EN?`<p>If you sell hardware, you can open your own retail locations in regions you've entered: a <b>mall kiosk</b> (cheap, small effect), a <b>store</b> and a <b>flagship store</b> (expensive, its opening makes headlines and it grows your brand every month). Setup and monthly costs depend on the region's price level. Each region allows up to 4 kiosks, 8 stores and 2 flagship stores; larger formats are expensive but add more network strength relative to their rent.</p><p>As your network strength in a region grows: your hardware products there become <b>up to 25% more appealing</b>, <b>up to 40%</b> of sales go through your own stores and you keep the <b>20% cut</b> that would go to retailers, regional awareness rises, and service desks increase customer satisfaction. If you close a store, 20% of the setup cost is refunded.</p><p><b>Shelf and prices:</b> Each store sells only the products on its shelf and fully boosts their appeal; your hardware products that are not on its shelf get 30% of that effect through the brand halo seen by shoppers. A kiosk holds 4 products, a store 8 and a flagship 16; each purchasing unit adds 2. By default products launched in the last 90 days and the region's best sellers are picked automatically; click a store to edit its shelf by hand. You can set a store price for each product on the shelf: a discount sells more of that product in the store but lowers the retail margin, a markup does the opposite.</p><p>Each region card shows the <b>break-even revenue</b> for each store type: if your monthly hardware revenue in that region is above it, a new location covers its rent and staff costs; it also shows how many months it takes to recoup the setup cost. Each new location adds less as the network grows; a few locations are enough in small markets.</p>`:`<p>Donanım satıyorsan girdiğin bölgelerde kendi satış noktalarını açabilirsin: <b>AVM standı</b> (ucuz, küçük etki), <b>mağaza</b> ve <b>amiral mağaza</b> (pahalı, açılışı ses getirir, markayı her ay büyütür). Kurulum ve aylık gider bölgenin fiyat seviyesine göre değişir. Bölge başına en fazla 4 stant, 8 mağaza ve 2 amiral mağaza açılabilir; büyük formatlar pahalıdır ama ağ gücüne katkıları kiralarına göre daha yüksektir.</p><p>Bir bölgedeki ağ gücün arttıkça: donanım ürünlerin orada <b>%25'e kadar daha çekici</b> olur, satışların <b>%40'a kadarı</b> kendi mağazandan geçer ve perakendeciye giden <b>%20 pay</b> sende kalır, bölge bilinirliği yükselir, servis masaları müşteri memnuniyetini artırır. Mağazayı kapatırsan kurulum bedelinin %20'si geri döner.</p><p><b>Raf ve fiyat:</b> Her mağaza yalnızca rafındaki ürünleri satar ve onların çekiciliğini tam artırır; rafında olmayan donanım ürünlerin mağazayı gezen müşterilerin gözünde marka hâlesiyle bu etkinin %30'unu alır. Raf stantta 4, mağazada 8, amiral mağazada 16 üründür; her satın alma birimi 2 ürün ekler. Varsayılan olarak son 90 günde çıkan ürünler ve bölgede en çok satanlar otomatik seçilir; mağazaya tıklayıp rafı elle de düzenleyebilirsin. Raftaki her ürün için mağaza fiyatı seçebilirsin: indirim o ürünü mağazada daha çok sattırır ama perakende payını azaltır, zam tersini yapar.</p><p>Her bölge kartında her mağaza türü için <b>başabaş geliri</b> gösterilir: o bölgedeki aylık donanım gelirin bunun üstündeyse yeni nokta kira ve personel giderini çıkarır, ayrıca kurulum bedelinin kaç ayda geri döneceği yazar. Ağ büyüdükçe her yeni noktanın katkısı azalır; küçük pazarlarda birkaç nokta yeterlidir.</p>`)},
 {id:'datapol',c:'urun',t:(LANG_EN?"Data policy":'Veri politikası'),go:'dpol',b:(LANG_EN?`<p>You decide how your software products collect user data. A <b>privacy-first</b> policy cuts ad revenue by 18% and lowers your AI data score, but builds trust every month and nearly eliminates scandal risk. <b>Aggressive data collection</b> raises ad revenue by 15% and provides more data for model training; in exchange, trust falls, scandal risk rises 2.5x and you may face fines in Europe.</p><p><b>User trust</b> affects your software products' appeal by −8% to +7% (55 is neutral); a scandal makes software products 15% less appealing for 60 days. Explicit consent screens, end-to-end encryption and a yearly transparency report build trust. Selling a dataset to a broker brings quick cash, but users being re-identified can turn into a major scandal. Data breaches lower trust; encryption reduces the number of affected users.</p>`:`<p>Yazılım ürünlerinin kullanıcı verisini nasıl topladığını sen belirlersin. <b>Gizlilik öncelikli</b> politika reklam gelirini %18 düşürür, yapay zekâ veri puanını azaltır ama güveni her ay artırır ve skandal riskini neredeyse sıfırlar. <b>Agresif veri toplama</b> reklam gelirini %15 artırır, model eğitimi için daha çok veri sağlar; buna karşılık güven düşer, skandal riski 2,5 katına çıkar ve Avrupa'da ceza gelebilir.</p><p><b>Kullanıcı güveni</b> yazılım ürünlerinin çekiciliğini −%8 ile +%7 arasında etkiler (55 nötr); bir skandal yazılım ürünlerini 60 gün %15 daha az çekici yapar. Açık rıza ekranları, uçtan uca şifreleme ve yıllık şeffaflık raporu güveni artırır. Veri setini bir simsara satmak hızlı nakit getirir ama kullanıcıların yeniden tanımlanması büyük bir skandala dönüşebilir. Veri sızıntıları güveni düşürür; şifreleme etkilenen kullanıcı sayısını azaltır.</p>`)},
 {id:'aiw',c:'ekip',t:(LANG_EN?"AI agents":'Yapay zekâ ajanları'),go:'team:yz',b:(LANG_EN?`<p>After the Machine Learning research you can add <b>AI agents</b> to your team: coding and research agents right away, design and marketing agents with Large Language Models. Agents draw no salary but run up a compute bill; the bill gets cheaper every year.</p><p>Each human employee can supervise up to <b>2 agents</b>; unsupervised agents cost money but produce nothing. Coding and design agents boost the productivity of the team in the same role (agent skill × 0.5 / team skill); research agents produce research points and marketing agents produce brand strength. Agent skill improves over the years, with LLM research and with your own lab's model.</p><p>Risks: agents' work is <b>buggier</b> and occasional <b>incidents</b> happen (made-up posts, security holes, fake sources). An <b>oversight layer</b> raises the fee by 25% and reduces incidents and bugs. If agents outnumber humans, the team fears for their jobs; a <b>reskilling program</b> prevents this and builds experience.</p>`:`<p>Makine Öğrenmesi araştırmasından sonra ekibine <b>yapay zekâ ajanları</b> ekleyebilirsin: kod ve araştırma ajanları hemen, tasarım ve pazarlama ajanları Büyük Dil Modelleri ile açılır. Ajan maaş almaz, işlem gücü faturası çıkarır; fatura her yıl ucuzlar.</p><p>Her insan çalışan en fazla <b>2 ajanı</b> yönetebilir; gözetmensiz ajan para yer ama iş üretmez. Kod ve tasarım ajanları aynı roldeki ekibin verimini artırır (ajan yeteneği × 0,5 / ekip yeteneği), araştırma ajanı araştırma puanı, pazarlama ajanı marka gücü üretir. Ajan yeteneği yıllar geçtikçe, LLM araştırmasıyla ve kendi laboratuvarının modeliyle artar.</p><p>Riskler: ajanların ürettiği iş daha <b>hatalıdır</b> ve ara sıra <b>kaza</b> çıkar (uydurma paylaşım, güvenlik açığı, sahte kaynak). <b>Denetim katmanı</b> ücreti %25 artırır, kazaları ve hataları azaltır. Ajan sayısı insan sayısını geçerse ekip işini kaybetmekten korkar; <b>yeniden beceri programı</b> bunu önler ve deneyim kazandırır.</p>`)},
 {id:'hostile',c:'finans',t:(LANG_EN?"Hostile takeover":'Düşmanca devralma'),go:'fin:dusmanca',b:(LANG_EN?`<p><b>Attack:</b> To buy a rival without its management's approval, you first buy up shares on the market in 5% blocks (each block a bit pricier, up to 25%). Past 10% you must disclose, and the rival finds out. Then you make a <b>tender offer</b> to the remaining shareholders at a 10%, 25% or 40% premium; you pay only if you succeed.</p><p>The rival can defend with a <b>poison pill</b> (lowers your chance of success) or a <b>white knight</b> (a higher counteroffer). You can raise your bid against the knight; if you don't, you sell your shares to them at their higher price for a profit. If your bid fails, your shares are sold at a 10% discount and brand −1. After a campaign ends, you must wait 6 months before starting another.</p><p><b>Competition Authority:</b> If you and your target would together hold over 50% market share in a shared category, neither a hostile nor a friendly acquisition is allowed.</p><p><b>Defense:</b> If you are public and own less than 50%, a cash-rich rival can buy up your shares and make a tender offer. Within 45 days, defend with a poison pill, a white knight, a share buyback or a letter to shareholders. If they succeed, you lose the company; your stake is added to your wealth at the offer price.</p>`:`<p><b>Saldırı:</b> Bir rakibi yönetiminin onayı olmadan almak için önce borsadan %5'lik dilimlerle hisse toplarsın (her dilim biraz daha pahalı, en fazla %25). %10'u geçince bildirim zorunluluğu doğar ve rakip haberdar olur. Sonra kalan hissedarlara %10, %25 ya da %40 primle <b>ihale teklifi</b> yaparsın; ödeme yalnızca başarırsan yapılır.</p><p>Rakip <b>zehir hapı</b> (başarı şansı düşer) ya da <b>beyaz şövalye</b> (daha yüksek karşı teklif) ile savunabilir. Şövalyeye karşı teklifini artırabilirsin; artırmazsan hisselerini onun yüksek fiyatından kârla satarsın. Başarısız teklifte hisselerin %10 iskontoyla satılır ve marka −1. Bir kampanya bittikten sonra yenisi için 6 ay beklenir.</p><p><b>Rekabet Kurumu:</b> Ortak bir kategoride seninle hedefin toplam pazar payı %50'yi geçecekse ne düşmanca ne de dostça satın almaya izin verilir.</p><p><b>Savunma:</b> Halka açıksan ve hissen %50'nin altındaysa nakdi bol bir rakip senin hisselerini toplayıp ihale teklifi yapabilir. 45 gün içinde zehir hapı, beyaz şövalye, hisse geri alımı ya da hissedarlara mektupla savun. Başarırlarsa şirketi kaybedersin; payın teklif fiyatından servetine eklenir.</p>`)},
 {id:'board',c:'finans',t:(LANG_EN?"Board meetings":'Yönetim kurulu toplantıları'),go:'fin:kurul',b:(LANG_EN?`<p>Once you take on investors (your stake drops below 100%), a <b>board</b> is formed: 4 members at a private company, 6 at a public one. Your co-founder and any activist who joins the board also take a seat. The board meets <b>every quarter</b> and the game pauses.</p><p>The agenda has 2–3 items: R&D budget (research +15%, 180 days), marketing push (brand +2, appeal +5%, 120 days), downsizing, entering a new market, special dividend, cutting the CEO's salary, paying off debt, team bonus. For each item you <b>support, abstain or oppose</b>.</p><p>Members' priorities decide their votes: <b>growth-minded</b>, <b>cash-minded</b> and <b>cautious</b> members favor different items. If your board confidence is high and your relationship with a member is good, they listen to you. Before the meeting you can hold a <b>private talk</b> with a member. If you own over 50%, you get a vote too; otherwise you can only persuade. Ties mean the item is rejected. A vote you win changes confidence by +1.5, one you lose by −2; skipping the meeting costs −6.</p>`:`<p>Yatırımcı aldığında (hissen %100'ün altına indiğinde) bir <b>yönetim kurulu</b> kurulur: özel şirkette 4, halka açık şirkette 6 üye. Kurucu ortağın ve kurula giren bir aktivist de masaya oturur. Kurul <b>her çeyrek</b> toplanır ve oyun duraklar.</p><p>Gündemde 2–3 madde olur: Ar-Ge bütçesi (araştırma +%15, 180 gün), pazarlama atağı (marka +2, cazibe +%5, 120 gün), kadroyu küçültme, yeni pazara açılma, özel temettü, CEO maaşını düşürme, borç kapatma, ekibe prim. Her madde için <b>destekle, çekimser kal ya da karşı çık</b>.</p><p>Üyelerin önceliği oyu belirler: <b>büyümeci</b>, <b>nakitçi</b> ve <b>temkinli</b> üyeler farklı maddeleri sever. Kurul güvenin yüksekse ve üyeyle ilişkin iyiyse seni dinlerler. Toplantı öncesi bir üyeyle <b>özel görüşme</b> yapabilirsin. Hissen %50'nin üstündeyse senin de bir oyun olur; altındaysa yalnızca ikna edebilirsin. Eşitlikte madde reddedilir. Kazandığın oylama güveni +1,5, kaybettiğin −2 etkiler; toplantıya katılmamak −6.</p>`)},
 {id:'beta',c:'urun',t:(LANG_EN?"Beta testing and focus groups":'Beta testi ve odak grupları'),go:'dev',b:(LANG_EN?`<p>You can run a <b>focus group</b> for a product in development (small fee): you learn its estimated press score range, how its price is perceived and its most interested audience; the team also gets a small quality boost from the feedback.</p><p>If you schedule a <b>beta test</b>, the product goes through a 30-day beta after development and then launches. A <b>closed beta</b> costs money: bugs are halved, press score +0.3, and there's a 10% leak risk. An <b>open beta</b> is free: bugs drop 30% and it builds hype for launch (appeal ×1.12 for 45 days), but you lose the surprise (the launch event counts as leaked) and if the product is weak, first impressions lower the press score by 0.3. The team is free during the beta; a scheduled launch event takes place when the beta ends.</p>`:`<p>Geliştirmedeki bir ürün için <b>odak grubu</b> düzenleyebilirsin (küçük bir ücret): tahmini basın puanı aralığını, fiyatın nasıl algılandığını ve en ilgili kitleyi öğrenirsin; ekip de geri bildirimlerden küçük bir kalite artışı kazanır.</p><p>Ürüne <b>beta testi</b> planlarsan geliştirme bitince 30 gün beta yapılır, sonra ürün piyasaya çıkar. <b>Kapalı beta</b> ücretlidir: hatalar yarıya iner, basın puanı +0,3 olur, %10 sızıntı riski vardır. <b>Açık beta</b> ücretsizdir: hatalar %30 azalır ve lansmanda heyecan yaratır (45 gün çekicilik ×1,12), ama sürpriz etkisi kaybolur (lansman etkinliği sızıntı sayılır) ve ürün zayıfsa ilk izlenim basın puanını 0,3 düşürür. Beta sırasında ekip serbest kalır; planlı bir lansman etkinliği beta bitince yapılır.</p>`)},
 {id:'quests',c:'bas',t:(LANG_EN?"Quests":'Görevler'),go:'quest',b:(LANG_EN?`<p>From time to time your investor, the Ministry of Industry, large enterprise customers, the board, the tech press, your employees or the user community offer you a timed quest: grow your user count, increase revenue, ship a homegrown processor, enter a new category, gain market share, lift team morale, reduce bugs, improve social sentiment or sustainability, post consecutive profits, finish research, pull off a great launch and so on.</p><p>You can accept or decline an offer within 30 days; you can take on at most two quests at a time. Reach the goal within the time limit and you get the reward (cash, brand, board confidence, morale, social sentiment, CEO experience). Some quests, especially investor and board quests, carry a penalty for failure. Rewards scale with your company's size.</p>`:`<p>Zaman zaman yatırımcın, Sanayi Bakanlığı, büyük kurumsal müşteriler, yönetim kurulu, teknoloji basını, çalışanların ya da kullanıcı topluluğu sana süreli bir görev önerir: kullanıcı sayını büyütmek, geliri artırmak, yerli bir işlemci çıkarmak, yeni bir kategoriye girmek, pazar payını artırmak, ekip moralini yükseltmek, hataları azaltmak, sosyal nabzı ya da sürdürülebilirliği iyileştirmek, art arda kâr etmek, araştırma bitirmek, iyi bir lansman yapmak gibi.</p><p>Teklifi 30 gün içinde kabul ya da reddedebilirsin; aynı anda en fazla iki görev üstlenebilirsin. Görev süresi içinde hedefe ulaşırsan ödülü (nakit, marka, kurul güveni, moral, sosyal nabız, CEO deneyimi) alırsın. Bazı görevlerin, özellikle yatırımcı ve kurul görevlerinin, başarısızlık cezası vardır. Ödüller şirketinin büyüklüğüyle ölçeklenir.</p>`)},
 {id:'lgoals',c:'bas',t:(LANG_EN?"Grand goals":'Büyük hedefler'),go:'quest',b:(LANG_EN?`<p>When your company enters its 10th year, or its value passes $5 billion at today's prices, four grand goals unlock. Each has a bronze, silver and gold tier. Tiers you reach are permanent; each tier gives brand and CEO experience. The sum of your tiers is your <b>legacy score</b> (up to 12) and appears on the company report card. Progress is tracked at month end.</p><ul><li><b>Monopoly:</b> Hold 60% or more of a category's market for 12 months in a row. Bronze 1, silver 3, gold 5 categories. The Competition Authority investigates shares above 45%.</li><li><b>Industry leader:</b> Be ahead of every rival in monthly product revenue and company value at the same time. Bronze 12, silver 36, gold 60 months in a row.</li><li><b>Holding company:</b> The number of business lines you are active in at the same time: software, hardware, manufacturing, retail, media, real estate, mining, stakes (20% of a rival), acquired companies, data centers and space. Bronze 5, silver 7, gold 9.</li><li><b>Global giant:</b> Company value of 10, 50 and 250 billion dollars at today's prices. Targets rise with inflation.</li></ul>`:`<p>Şirketin 10. yılına girdiğinde ya da şirket değeri bugünün fiyatlarıyla 5 milyar doları geçtiğinde dört büyük hedef açılır. Her birinin bronz, gümüş ve altın kademesi vardır. Ulaştığın kademe kalıcıdır; her kademe marka ve CEO deneyimi verir. Kademelerin toplamı <b>miras puanıdır</b> (en fazla 12) ve şirket karnesinde görünür. Takip ay sonunda yapılır.</p><ul><li><b>Tekel:</b> Bir kategoride pazarın %60'ını ya da fazlasını 12 ay üst üste elinde tut. Bronz 1, gümüş 3, altın 5 kategori. Rekabet Kurumu %45'i aşan payları soruşturur.</li><li><b>Sektör lideri:</b> Aylık ürün cirosunda ve şirket değerinde aynı anda bütün rakiplerinin önünde ol. Bronz 12, gümüş 36, altın 60 ay üst üste.</li><li><b>Holding:</b> Aynı anda faal olduğun iş kolu sayısı: yazılım, donanım, üretim, perakende, medya, gayrimenkul, madencilik, iştirakler (bir rakipte %20 hisse), satın alınan şirketler, veri merkezi ve uzay. Bronz 5, gümüş 7, altın 9.</li><li><b>Dünya devi:</b> Şirket değeri bugünün fiyatlarıyla 10, 50 ve 250 milyar dolar. Hedefler enflasyonla birlikte artar.</li></ul>`)},
 {id:'odak',c:'bas',t:(LANG_EN?"Focus mode":'Odak modu'),go:'fin:kayit',b:(LANG_EN?`<p>As the game grows, dozens of sections open in the menu. <b>Focus mode</b> (Settings) hides the sections you haven't opened in the last year and aren't using right now.</p><ul><li>The systems behind hidden sections keep running in the background.</li><li>Systems you use aren't hidden: for example, if you have stores the store chain stays visible, and if you have factories manufacturing does.</li><li>A section with a red alert, a newly unlocked section or one you pinned is never hidden.</li><li>You can open a hidden section from search or with the “Show” button under “More”; a section you open stays in the menu for a year.</li><li>In the list in Settings you can show or hide each section by hand.</li></ul><p>How it differs from Simple mode: Simple mode hides a fixed list of advanced sections and makes their decisions automatically; focus mode looks at your usage and never decides anything for you.</p>`:`<p>Oyun büyüdükçe menüde onlarca bölüm açılır. <b>Odak modu</b> (Ayarlar), son bir yılda açmadığın ve şu an kullanmadığın bölümleri menüden gizler.</p><ul><li>Gizli bölümlerin sistemleri arka planda çalışmaya devam eder.</li><li>Kullandığın sistemler gizlenmez: örneğin mağazan varsa mağaza zinciri, fabrikan varsa üretim görünür kalır.</li><li>Kırmızı uyarısı olan, yeni açılan ya da sabitlediğin bölüm hiç gizlenmez.</li><li>Gizli bir bölümü aramadan ya da “Daha fazla” altındaki “Göster” düğmesinden açabilirsin; açtığın bölüm bir yıl menüde kalır.</li><li>Ayarlardaki listeden her bölümü elle gösterip gizleyebilirsin.</li></ul><p>Basit moddan farkı: Basit mod sabit bir ileri seviye bölüm listesini gizler ve onların kararlarını otomatik verir; odak modu senin kullanımına bakar ve hiçbir kararı senin yerine vermez.</p>`)},
 {id:'neolur',c:'bas',t:(LANG_EN?"What-if preview":'Ne olur? önizlemesi'),go:'prod',b:(LANG_EN?`<p>You can see the outcome of a decision before you make it. The <b>What if?</b> button takes a copy of your company, applies the decision to the copy and plays the game's own simulation for 30, 60 or 90 days. Every option is played with the same random future, so the difference comes from the decision itself.</p><ul><li><b>Products:</b> cutting or raising the price by 10% or 20%, or a 30-day ad campaign. Sales, product revenue, market share, cash and company value difference.</li><li><b>Manufacturing:</b> which site makes a hardware product (your own factories, Delta Contract Assembly, rival lines you lease).</li><li><b>Wholesale trade:</b> accepting versus declining offers.</li><li><b>Decisions:</b> in board, regulator or crisis events, each option's outcome appears inside the window.</li></ul><p>Pick the option you like right away with <b>Apply</b>. The preview never changes the real game. It's an estimate: it shows one possible future, and other events may happen in reality.</p>`:`<p>Bir karar vermeden önce sonucunu görebilirsin. <b>Ne olur?</b> düğmesi şirketinin bir kopyasını alır, kararı kopyada uygular ve oyunun kendi simülasyonunu 30, 60 ya da 90 gün oynatır. Her seçenek aynı rastgele gelecekle oynatıldığı için fark kararın kendisinden gelir.</p><ul><li><b>Ürünler:</b> fiyatı %20 ve %10 indirmek ya da artırmak, 30 günlük reklam. Satış, ürün geliri, pazar payı, nakit ve şirket değeri farkı.</li><li><b>Üretim:</b> bir donanım ürününü hangi tesiste üreteceğin (kendi fabrikaların, Delta fason, kiraladığın rakip hatları).</li><li><b>Toptan ticaret:</b> teklifleri kabul etmek ile reddetmek.</li><li><b>Kararlar:</b> yönetim kurulu, regülatör ya da kriz gibi olaylarda her seçeneğin sonucu pencerenin içinde görünür.</li></ul><p>Beğendiğin seçeneği <b>Uygula</b> ile hemen seçebilirsin. Önizleme gerçek oyunu hiç değiştirmez. Bir tahmindir: tek bir olası geleceği gösterir ve gerçekte başka olaylar yaşanabilir.</p>`)},
 {id:'apause',c:'bas',t:(LANG_EN?"Auto-pause":'Otomatik duraklatma'),go:'fin:kayit',b:(LANG_EN?`<p>So you don't miss anything important while the game runs fast, it pauses itself when one of the situations you chose happens. The reason appears in the news strip: <b>Go</b> takes you to the related section, <b>Resume</b> continues at the previous speed. The rules are in Settings and apply to all your companies.</p><ul><li><b>On by default:</b> important bad news, cash falling below 3 months of fixed costs, a capacity or parts shortage in manufacturing, a new product launching.</li><li><b>You can also turn on:</b> important good news, idle team members, new offers, month end.</li><li>It pauses once when a problem starts; if it clears up and starts again, it pauses again. News of the same kind (for example a string of poaching offers) pauses at most once every 30 days.</li></ul><p>The <b>⏩ Until next event</b> button plays at top speed and stops when one of your active rules or any important news fires; if nothing happens within 180 days it stops anyway. <b>⏭ Month end</b> plays until the month closes. Pressing any speed button ends these modes. Events that need a decision always pause the game.</p>`:`<p>Oyun hızlı akarken önemli bir şeyi kaçırmamak için seçtiğin durumlardan biri olunca oyun kendiliğinden durur. Nedeni haber şeridinde görünür: <b>Git</b> ilgili bölüme götürür, <b>Devam</b> oyunu önceki hızında sürdürür. Kurallar Ayarlar'dadır ve bütün şirketlerinde geçerlidir.</p><ul><li><b>Varsayılan olarak açık:</b> kötü önemli haber, nakdin 3 aylık sabit giderin altına inmesi, üretimde kapasite ya da parça sıkıntısı, yeni ürünün piyasaya çıkması.</li><li><b>İstersen açabileceklerin:</b> iyi önemli haber, boşta kalan ekip, yeni teklif, ay sonu.</li><li>Bir sorun başladığında bir kez durur; düzelip yeniden başlarsa yine durur. Aynı türden haberler (örneğin art arda gelen transfer teklifleri) en fazla 30 günde bir durdurur.</li></ul><p><b>⏩ Olaya kadar</b> düğmesi oyunu en yüksek hızda oynatır ve açık kurallardan biri ya da herhangi bir önemli haber gelince durur; 180 gün içinde bir şey olmazsa yine durur. <b>⏭ Ay sonu</b> ay kapanışına kadar oynatır. Hız düğmelerinden birine basmak bu modları bitirir. Karar gerektiren olaylar her zaman oyunu durdurur.</p>`)},
 {id:'td',c:'arge',t:(LANG_EN?"Rival product teardown":'Rakip ürün sökümü'),go:'res:sokum',b:(LANG_EN?`<p>In R&D → Teardown you buy one of a rival's products on the market and take it apart in the lab. The cost is buying the product (10 devices for hardware, a 12-month subscription for software) plus engineering. You need an engineer who works in that category; at most 2 teardowns run at once and each product can be torn down once.</p><ul><li><b>Report:</b> the product's real freshness (compared with yours), unit cost, price and margin, design focus, strongest and weakest side, and which customer group it appeals to most. A product focused on its weak side wins the customers it misses.</li><li><b>Score bonus:</b> for 18 months, new products and major updates in that category score higher. The further the rival is ahead of you, the bigger the bonus: between 4% and 10%. Your products already on the market also improve right away by the same amount (each product once).</li><li><b>Research discount:</b> up to three related research items you haven't done yet need fewer research points.</li><li><b>Clean room:</b> 45 days, 1.5× cost, 75% of the gain, 15% research discount; no legal risk and the rival barely minds.</li><li><b>Direct copy:</b> 25 days, full gain, 25% research discount. Relations with the rival sour, and within two years it may sue for patent infringement over products you launch or update in that category after the teardown. The claim is 3–5× your monthly revenue in that category, but at most 30% of your cash (at least $300K).</li></ul>`:`<p>Ar-Ge → Ürün sökümü bölümünde rakibin piyasadaki bir ürününü satın alıp laboratuvarda sökersin. Maliyet ürünün alımı (donanımda 10 cihaz, yazılımda 12 aylık abonelik) ile mühendislikten oluşur. O kategoride çalışacak bir mühendisin olmalı; aynı anda en fazla 2 söküm yürütülür ve bir ürün bir kez sökülür.</p><ul><li><b>Rapor:</b> ürünün gerçek güncelliği (seninkiyle karşılaştırmalı), birim maliyeti, fiyatı ve marjı, tasarım odağı, en güçlü ve en zayıf yönü, en çok hangi kitleye hitap ettiği. Zayıf yönüne odaklanan bir ürün, onun kaçırdığı müşterileri çeker.</li><li><b>Puan bonusu:</b> o kategoride 18 ay boyunca yeni ürünlerin ve büyük güncellemelerin puanı artar. Rakip senden ne kadar öndeyse bonus o kadar büyüktür: %4 ile %10 arası. Piyasadaki ürünlerin de hemen aynı oranda iyileşir (her ürün bir kez).</li><li><b>Araştırma indirimi:</b> kategoriyle ilgili, henüz yapmadığın en fazla üç araştırmanın araştırma puanı düşer.</li><li><b>Temiz oda:</b> 45 gün, 1,5 kat maliyet, kazanımın %75'i, araştırmada %15 indirim; yasal risk yok, rakip pek alınmaz.</li><li><b>Doğrudan kopya:</b> 25 gün, tam kazanım, araştırmada %25 indirim. Rakiple ilişki bozulur ve iki yıl içinde o kategoride sökümden sonra çıkardığın ya da güncellediğin ürünler için patent davası açabilir. Talep o kategorideki aylık cironun 3–5 katıdır, ama nakdinin en çok %30'u (en az 300K).</li></ul>`)},
 {id:'spn',c:'ekip',t:(LANG_EN?"Alumni and their startups":'Mezunlar ve girişimleri'),go:'team:mezun',b:(LANG_EN?`<p>Talented employees who leave (skill 7 or higher, senior or manager) may found their own startup. The chance depends on skill, how they left and personality: people laid off in cutbacks and those who quit found startups more often, those poached by rivals rarely; ambitious, leader and creative employees more often, loyal ones less often. At most 4 alumni startups exist at once, with at least 150 days between foundings. Someone who quits with very low morale may take a colleague along.</p><ul><li><b>Rounds:</b> a startup goes through seed, Series A and Series B; its value grows each round, and it may fail. After Series B it enters the market in its category as a <b>rival</b>, with its founder as CEO.</li><li><b>How they see you:</b> people you fired are resentful or hostile, those who quit are resentful, those poached by rivals are distant. A resentful founder won't take your investment; a hostile one won't sell you the company. When the startup enters the market it becomes a rival with that attitude.</li><li><b>Investing:</b> 15% of its value buys you about 13% (at most 45%); each new round dilutes your stake. When it enters the market your stake moves to your share portfolio.</li><li><b>Acquiring:</b> the founder and their team (2–4 people) come back, and products in that category score +4% for 12 months.</li><li><b>If it fails:</b> the founder looks for a job and appears among your candidates; you can bring them back.</li><li><b>Alumni network:</b> every alumni startup that passes Series A, enters the market or gets acquired raises your candidate quality (up to +0.4).</li></ul>`:`<p>Ayrılan yetenekli çalışanlar (yetenek 7 ve üstü, kıdemli ya da yönetici) kendi girişimini kurabilir. Olasılık yeteneğe, ayrılış biçimine ve kişiliğe bağlıdır: küçülmede çıkarılanlar ve istifa edenler daha sık kurar, rakibe geçenler seyrek; hırslı, lider ve yaratıcı çalışanlar daha sık, sadık olanlar daha seyrek kurar. Aynı anda en fazla 4 mezun girişimi olur ve iki kuruluş arasında en az 150 gün geçer. Morali çok düşükken istifa eden biri bir arkadaşını da yanına alabilir.</p><ul><li><b>Turlar:</b> girişim tohum, Seri A ve Seri B aşamalarından geçer; her turda değeri artar, batabilir. Seri B'den sonra kendi kategorisinde pazara <b>rakip</b> olarak girer ve kurucusu CEO'su olur.</li><li><b>Sana bakışı:</b> işten çıkarılanlar kırgın ya da düşmancadır, istifa edenler kırgın, rakibe geçenler mesafelidir. Kırgın kurucu yatırımını kabul etmez; düşmanca olan şirketini satmaz. Pazara girdiğinde bu bakışla rakip olur.</li><li><b>Yatırım:</b> değerinin %15'iyle yaklaşık %13 pay alırsın (en çok %45); her yeni turda payın sulanır. Pazara girdiğinde payın hisse portföyüne geçer.</li><li><b>Satın alma:</b> kurucu ve ekibi (2–4 kişi) geri döner ve o kategoride 12 ay ürün puanı +%4 olur.</li><li><b>Batarsa:</b> kurucu iş arar ve adaylar listesine düşer; geri çağırabilirsin.</li><li><b>Mezun ağı:</b> Seri A'yı geçen, pazara giren ya da satın alınan her mezun girişimi aday kaliteni artırır (en çok +0,4).</li></ul>`)},
 {id:'voice',c:'urun',t:(LANG_EN?"Customer voice":'Müşteri sesi'),go:'prod',b:(LANG_EN?`<p>The <b>Customer voice</b> panel on the Products page and the product window show users' concrete complaints: each complaint's share, which customer group voices it most, and how to fix it.</p><ul><li><b>Bugs:</b> “Keeps crashing” or “Freezes often”; assign a maintenance team or ship an update.</li><li><b>Support:</b> “Support never answers”; hire support specialists.</li><li><b>Price:</b> when the product is clearly pricier than similar ones; preview price options with “What if?”.</li><li><b>Aging:</b> when freshness drops below 90%; ship a major update.</li><li><b>Weak design focus:</b> if you gave an attribute 0 or 1 points, e.g. “Battery dies fast”; raise that focus in an update.</li><li><b>Missing feature:</b> when a feature that's now standard is missing.</li><li><b>Stock:</b> “Out of stock” when capacity or parts fall short.</li></ul><p><b>Listening to customers:</b> if a product's biggest complaint (at least 25% share) drops clearly by month end, users notice: satisfaction +6, brand +0.5. This reward is given once every 180 days per product.</p>`:`<p>Ürünler sayfasındaki <b>Müşteri sesi</b> paneli ve ürün penceresi, kullanıcıların somut şikâyetlerini gösterir: her şikâyetin payı, en çok hangi kitleden geldiği ve çözüm yolu.</p><ul><li><b>Hatalar:</b> “Sürekli çöküyor” ya da “Sık donuyor”; bakım ekibi ata ya da güncelleme yap.</li><li><b>Destek:</b> “Destekten yanıt gelmiyor”; destek uzmanı işe al.</li><li><b>Fiyat:</b> ürün benzerlerinden belirgin biçimde pahalıysa; “Ne olur?” ile fiyat seçeneklerini önizle.</li><li><b>Eskime:</b> güncellik %90'ın altına inince; büyük güncelleme yap.</li><li><b>Zayıf tasarım odağı:</b> bir niteliğe 0 ya da 1 puan verdiysen, örneğin “Pil çabuk bitiyor”; güncellemede o odağı artır.</li><li><b>Eksik özellik:</b> artık standart sayılan bir özellik yoksa.</li><li><b>Stok:</b> kapasite ya da parça yetmiyorsa “Stokta bulunamıyor”.</li></ul><p><b>Müşteriyi dinlemek:</b> bir ürünün en büyük şikâyeti (payı en az %25) ay sonunda belirgin biçimde azalırsa kullanıcılar fark eder: memnuniyet +6, marka +0,5. Bu ödül her ürün için 180 günde bir verilir.</p>`)},
 {id:'cdesk',c:'finans',t:(LANG_EN?"Crisis desk":'Kriz masası'),go:'dash',b:(LANG_EN?`<p>Major operational crises are handled at the crisis desk in three rounds: <b>First 24 hours</b>, <b>Investigation</b> and <b>Closing</b>. There are four kinds: a major data breach (software with many users), a product safety crisis (best-selling hardware; more likely with a high defect rate), a general strike at your factories (more likely with a union or low morale) and a global service outage (several data centers lower the risk). They occur after day 540, at least two years apart, and only to companies of some size (valuation of at least $20 million) that were profitable over the last three months and are not short of cash.</p><ul><li><b>Stakeholders:</b> trust of customers, press, regulator, investors and employees is tracked from 0 to 100. Each option shows with arrows which stakeholder it pushes in which direction.</li><li><b>Time:</b> 5 days pass between rounds. If you don't decide on a round within 10 days, you're considered to have stayed silent and the passive option applies.</li><li><b>Lying:</b> options that deny reassure investors but may come out in the next round: press and regulator react harshly.</li><li><b>Outcome:</b> the press sets your brand, customers the 90-day sales of affected products, the regulator a fine (if its trust is below 35), investors the share mood or board confidence, employees morale. You get an A–F grade based on average trust.</li></ul>`:`<p>Büyük operasyonel krizler kriz masasında üç turda yönetilir: <b>İlk 24 saat</b>, <b>Soruşturma</b> ve <b>Kapanış</b>. Dört kriz türü vardır: büyük veri sızıntısı (çok kullanıcılı yazılım), ürün güvenliği (çok satan donanım; hata oranı yüksekse daha olası), fabrikalarda genel grev (sendika ya da düşük moral varsa daha olası) ve küresel hizmet kesintisi (birden çok veri merkezi riski azaltır). 540. günden sonra, iki kriz arasında en az iki yıl olacak şekilde ortaya çıkar; yalnızca belli bir ölçeğe (şirket değeri en az 20 milyon dolar) ulaşmış, son üç ayı kârlı ve nakit sıkıntısı çekmeyen şirketlerde.</p><ul><li><b>Paydaşlar:</b> müşteriler, basın, regülatör, yatırımcılar ve çalışanların güveni 0–100 izlenir. Seçeneklerde hangi paydaşı hangi yöne ittiği oklarla görünür.</li><li><b>Zaman:</b> turlar arasında 5 gün geçer. Bir tura 10 gün içinde karar vermezsen sessiz kalmış sayılırsın ve pasif seçenek uygulanır.</li><li><b>Yalan:</b> inkâr eden seçenekler yatırımcıları rahatlatır ama sonraki turda ortaya çıkabilir: basın ve regülatör sert tepki verir.</li><li><b>Sonuç:</b> basın markayı, müşteriler etkilenen ürünlerin 90 günlük satışını, regülatör cezayı (güveni 35'in altındaysa), yatırımcılar hisse havasını ya da kurul güvenini, çalışanlar morali belirler. Ortalama güvene göre A–F notu alırsın.</li></ul>`)},
 {id:'rvn',c:'pazar',t:(LANG_EN?"Rival moves":'Rakiplerin hamleleri'),go:'market:ceo',b:(LANG_EN?`<p>Rivals also use the teardown, crisis, lobbying and alumni startup systems (Market → Rival CEOs → Rival moves). Ongoing moves, rivals with teardown gains and recent moves are shown there.</p><ul><li><b>Teardown:</b> a rival buys and tears down your best product in a category where you lead. When it's done, its new products in that category are 3–8% stronger for 18 months and its best product improves right away by half that. Each of your products can be torn down at most once a year.</li><li><b>Copying lawsuit:</b> aggressive rivals choose a direct copy. Evidence of copying adds +25 points to your chance of winning a lawsuit; if you win, you get damages and the rival loses its gain. You can also demand a license fee.</li><li><b>Crisis:</b> large rivals go through data breaches, product safety crises, strikes or outages; their affected products are less appealing for 90 days. A rival that denies everything is usually found out. If it's your market, you decide: comparative campaign, switching discount or staying quiet.</li><li><b>CEO personality:</b> Combative and Opportunist CEOs tear down more often, copy directly and deny everything in a crisis; Diplomat and Visionary CEOs choose a clean room and handle crises openly. A non-aggression pact also stops teardowns.</li><li><b>Counter-lobbying:</b> when you lobby on a bill, rivals with the opposite interest respond; their total response is at most 35% of your new spending.</li><li><b>Bids for alumni startups:</b> a rival may want to buy an alumni startup at Series A or B. Within 45 days you can buy it yourself or block the bid by holding a 25% stake; if the rival buys it, your stake is paid out with a 30% premium.</li><li><b>Suggestions and auto-pause:</b> the Status list suggests blocking bids, rival products worth tearing down and close votes. The "Rival move" auto-pause rule stops the game on these moves.</li></ul>`:`<p>Rakipler de söküm, kriz, lobi ve mezun girişimleri sistemlerini kullanır (Pazar → Rakip CEO'lar → Rakiplerin hamleleri). Süren hamleler, söküm kazanımı olan rakipler ve son hamleler orada görünür.</p><ul><li><b>Söküm:</b> senin önde olduğun bir kategorideki en iyi ürününü satın alıp söker. Bitince o kategoride 18 ay yeni ürünleri %3–8 güçlenir, en iyi ürünü hemen bunun yarısı kadar iyileşir. Bir ürünün yılda en çok bir kez sökülür.</li><li><b>Kopya davası:</b> saldırgan rakipler doğrudan kopyayı seçer. Kopya kanıtı dava kazanma ihtimaline +25 puan ekler; kazanırsan tazminat alırsın ve rakibin kazanımı silinir. Lisans ücreti de isteyebilirsin.</li><li><b>Kriz:</b> büyük rakipler veri sızıntısı, ürün güvenliği, grev ya da kesinti yaşar; etkilenen ürünleri 90 gün daha az çekici olur. İnkâr eden rakibin yalanı çoğu zaman ortaya çıkar. Senin pazarındaysa karşılaştırmalı kampanya, geçiş indirimi ya da sessiz kalma kararı gelir.</li><li><b>CEO kişiliği:</b> Kavgacı ve Fırsatçı CEO'lar daha sık söker, doğrudan kopyalar ve krizde inkâr eder; Diplomat ve Vizyoner CEO'lar temiz oda seçer ve krizi açık yönetir. Saldırmazlık paktı sökümü de durdurur.</li><li><b>Karşı lobi:</b> bir teklifte lobi yaptığında ters çıkarlı rakipler karşılık verir; toplam karşılık yeni harcamanın en çok %35'idir.</li><li><b>Mezun girişimine teklif:</b> rakip, Seri A ya da B'deki bir mezun girişimini almak isteyebilir. 45 gün içinde satın alabilir ya da %25 pay sahibi olarak engelleyebilirsin; rakip alırsa payın %30 primle ödenir.</li><li><b>Öneriler ve duraklatma:</b> Durum listesi teklif engellemeyi, sökmeye değer rakip ürünlerini ve başa baş oylamaları önerir. "Rakip hamlesi" otomatik duraklatma kuralı bu hamlelerde oyunu durdurur.</li></ul>`)},
 {id:'lobby',c:'finans',t:(LANG_EN?"Lobbying and bills":'Lobi ve yasa teklifleri'),go:'fin:devlet',b:(LANG_EN?`<p>After day 400, a bill reaches parliament every 8–12 months and is voted on 120 days later (Finance → Government and regulation). You can see whether the bill is good or bad for you, how the public feels and which side your rivals lobby for.</p><ul><li><b>Bills:</b> a tech tax cut or a surtax (permanent), an EU digital services tax, a US hardware tariff, an R&D tax credit (research −20%), a domestic production incentive (labor −15% at factories in Türkiye), a strict data privacy law (software appeal −4%, +3% for companies with data policy trust 70+) and an AI regulation (AI appeal −5% plus a monthly compliance cost). Timed ones last 3 years.</li><li><b>Odds:</b> each bill has a base chance of passing that shifts with the balance of lobbying for and against. Rivals lobby every month according to their interests, in proportion to their cash.</li><li><b>Your lobbying:</b> small or large lobbying for or against; the amount scales with your company's size. You can't back both sides of the same bill.</li><li><b>Public campaign:</b> 2.5× as effective on the side the public supports and raises your brand by 1; against the public it has little effect and your brand drops by 1.</li><li><b>Scandal:</b> heavy lobbying may leak to the press at the vote (up to a 30% chance): brand −2. The risk is higher if your sustainability score is low.</li></ul>`:`<p>400. günden sonra 8–12 ayda bir meclise bir yasa teklifi gelir ve 120 gün sonra oylanır (Finans → Devlet ve regülasyon). Teklifin senin için olumlu mu olumsuz mu olduğu, halkın tavrı ve rakiplerin hangi tarafta lobi yaptığı görünür.</p><ul><li><b>Teklifler:</b> teknoloji vergi indirimi ya da ek vergi (kalıcı), Avrupa dijital hizmet vergisi, ABD donanım gümrüğü, Ar-Ge vergi kredisi (araştırma −%20), yerli üretim teşviki (Türkiye fabrikalarında işçilik −%15), veri gizliliği yasası (yazılım çekiciliği −%4, veri politikası güveni 70+ olanlarda +%3) ve yapay zekâ düzenlemesi (yapay zekâ çekiciliği −%5 ve aylık uyum maliyeti). Süreli olanlar 3 yıl geçerlidir.</li><li><b>Olasılık:</b> her teklifin bir taban geçme olasılığı vardır; destek ve karşı lobi arasındaki dengeye göre değişir. Rakipler çıkarlarına göre her ay nakitleriyle orantılı lobi yapar.</li><li><b>Senin lobin:</b> küçük ya da büyük destek veya karşı lobi; tutar şirketinin büyüklüğüyle ölçeklenir. Aynı teklifte iki tarafı birden destekleyemezsin.</li><li><b>Kamuoyu kampanyası:</b> halkın desteklediği tarafta 2,5 kat etkilidir ve markayı +1 artırır; halka karşı yapılırsa etkisi azdır ve marka −1 düşer.</li><li><b>Skandal:</b> çok lobi harcaması oylamada basına sızabilir (en çok %30 olasılık): marka −2. Sürdürülebilirlik puanın düşükse risk artar.</li></ul>`)},
 {id:'advisor',c:'bas',t:(LANG_EN?"Advisor":'Danışman'),go:'dash',b:(LANG_EN?`<p>The advisor looks at your company as a whole and ranks the most important tasks in the <b>Next move</b> panel on the CEO desk: runway, idle employees, aging or buggy products, low morale, full offices and servers, new markets and categories, dependence on a single category, idle cash, prices, social media, rival dominance and more. The panel merges warnings and suggestions into one list and shows the top three tasks; many can be done from the panel in one click.</p><p>You can choose from three advisors: <b>Ayla</b> is a balanced strategy advisor who values research; <b>Kemal</b> is a retired banker who thinks cash and efficiency first; <b>Deniz</b> is a growth strategist who pushes new products, markets and brand. You can snooze a suggestion for 60 days or turn the advisor off entirely; when off, the panel shows only warnings.</p>`:`<p>Danışman şirketine bütün olarak bakar ve CEO masasındaki <b>Sıradaki hamle</b> panelinde en önemli işleri sıralar: nakit ömrü, boştaki çalışanlar, eskiyen ya da hatalı ürünler, düşük moral, dolan ofis ve sunucular, yeni pazarlar ve kategoriler, tek kategoriye bağımlılık, boşta duran nakit, fiyatlar, sosyal medya, rakip hâkimiyeti ve daha fazlası. Panel uyarıları ve önerileri tek listede birleştirir, en önemli üç işi gösterir; birçoğu panelden tek tıkla yapılabilir.</p><p>Üç danışman arasından seçebilirsin: <b>Ayla</b> dengeli bir strateji danışmanıdır ve araştırmaya önem verir; <b>Kemal</b> emekli bir bankacıdır, önce nakdi ve verimliliği düşünür; <b>Deniz</b> büyüme stratejistidir, yeni ürünleri, pazarları ve markayı öne çıkarır. Bir öneriyi 60 gün erteleyebilir ya da danışmanı tamamen kapatabilirsin; kapalıyken panel yalnızca uyarıları gösterir.</p>`)},
 {id:'space',c:'arge',t:(LANG_EN?"Space program":'Uzay programı'),go:'space',b:(LANG_EN?`<p>The <b>Satellite Technology</b> research unlocks Product → Space program. You build satellites in batches (60 days), then launch them: at first you rent space from a launch company; with the <b>Reusable Rocket</b> research and a development program, your own rocket cuts launch costs to a quarter. Every launch has a small risk of failure; a failed launch loses the satellites in that batch.</p><p>The number of satellites in orbit sets your <b>coverage</b> (about 63% at 200 satellites). You need a <b>spectrum license</b> to sell service. Subscribers come based on coverage, price, your brand and service quality; capacity per satellite is limited (+60% with <b>Laser Satellite Link</b>). If you exceed capacity, quality and subscribers drop.</p><p>Satellites last 5 years; debris collisions and solar storms destroy satellites. After a while a rival constellation (Orbit Network) competes with you for subscribers. Once coverage passes 50%, your phones gain satellite messaging and your vehicle software gets connectivity everywhere. With the <b>Crewed Flight</b> research and a crewed capsule you can start space tourism.</p>`:`<p><b>Uydu Teknolojisi</b> araştırmasıyla Ürün → Uzay programı açılır. Uyduları gruplar hâlinde üretirsin (60 gün), sonra fırlatırsın: başta bir fırlatma şirketinden yer kiralarsın, <b>Yeniden Kullanılabilir Roket</b> araştırması ve geliştirme programıyla kendi roketin fırlatma maliyetini dörtte birine indirir. Her fırlatmanın küçük bir başarısızlık riski vardır; başarısız fırlatmada o gruptaki uydular kaybolur.</p><p>Yörüngedeki uydu sayısı <b>kapsamayı</b> belirler (200 uyduda yaklaşık %63). Hizmet satmak için <b>frekans lisansı</b> gerekir. Aboneler kapsamaya, fiyata, markana ve hizmet kalitesine göre gelir; uydu başına kapasite sınırlıdır (<b>Lazer Uydu Bağlantısı</b> ile +%60). Kapasiteyi aşarsan kalite ve abone düşer.</p><p>Uyduların ömrü 5 yıldır; enkaz çarpışmaları ve güneş fırtınaları uydu kaybettirir. Bir süre sonra rakip bir takımyıldız (Yörünge Ağı) aboneler için seninle yarışır. Kapsama %50'yi geçince telefonların uydudan mesajlaşma, araç yazılımların her yerde bağlantı kazanır. <b>İnsanlı Uçuş</b> araştırması ve insanlı kapsülle uzay turizmine başlayabilirsin.</p>`)},
 {id:'ceoskill',c:'finans',t:(LANG_EN?"CEO skills":'CEO yetenekleri'),go:'skill',b:(LANG_EN?`<p>As founder you gain experience: from every new product (more with a high press score), every launch event (more with an excited crowd on stage), every research project, every profitable month, every achievement, tech awards, valuation milestones and the IPO. Each level grants a skill point; you start the game with one point.</p><p>There are five branches: <b>Visionary</b> (product and research), <b>Leader</b> (team and culture), <b>Marketer</b> (brand and sales), <b>Financier</b> (money and investors), <b>Operator</b> (manufacturing and quality). Each branch has four skills unlocked in order; the final tier costs two points. You can't complete every branch, so choose what kind of CEO you'll be. You can reset your skills with an executive coach for a fee.</p>`:`<p>Kurucu olarak deneyim kazanırsın: her yeni ürün (basın puanı yüksekse daha çok), her lansman etkinliği (sahnede salon coşkusuyla artar), her araştırma, her kârlı ay, her başarım, teknoloji ödülleri, değerleme eşikleri ve halka arz. Her seviye bir yetenek puanı verir; oyuna bir puanla başlarsın.</p><p>Beş dal vardır: <b>Vizyoner</b> (ürün ve araştırma), <b>Lider</b> (ekip ve kültür), <b>Pazarlamacı</b> (marka ve satış), <b>Finansçı</b> (para ve yatırımcılar), <b>Operasyoncu</b> (üretim ve kalite). Her dalda dört yetenek sırayla açılır; son kademe iki puan ister. Bütün dalları bitiremezsin, hangi tür CEO olacağını seç. Yetenekleri bir yönetim koçuyla ücret karşılığı sıfırlayabilirsin.</p>`)},
 {id:'subbrand',c:'pazar',t:(LANG_EN?"Sub-brands":'Alt markalar'),go:'market:altmarka',b:(LANG_EN?`<p>You can create up to three sub-brands. Each sub-brand has its own name, logo, <b>positioning</b> and <b>brand strength</b>. Positioning shifts demand by segment: <b>Affordable</b> appeals to budget buyers, <b>Premium</b> to enthusiasts, <b>Youth</b> to the mainstream for consumer products, and <b>Enterprise</b> to business products. The positioning effect reaches full strength over the first year. This way two of your products in the same category can target different customers without cannibalizing each other.</p><p>An <b>endorsed brand</b> ("X, backed by the parent brand") starts at 70% of the parent brand's strength and gradually approaches it; for its products the effective strength is 60% sub-brand, 40% parent brand. Launch and press successes or flops affect both brands.</p><p>An <b>independent brand</b> starts weak (it grows a little each month in the first year with promotional support) and sells purely on its own strength. The parent brand's personality, social media sentiment and crises don't touch it, and its mistakes don't reflect on your parent brand. It's useful when entering a risky category or when you don't want cheap products to hurt your premium image.</p><p>With the <b>Brand</b> choice in the development form you can launch a new product directly under a sub-brand, and you can move existing products from the sub-brand page. Each sub-brand has a monthly upkeep cost.</p>`:`<p>En fazla üç alt marka kurabilirsin. Her alt markanın kendi adı, logosu, <b>konumu</b> ve <b>marka gücü</b> vardır. Konum segmentlere göre talebi değiştirir: <b>Uygun fiyatlı</b> fiyat odaklıları, <b>Premium</b> meraklıları, <b>Genç</b> tüketici ürünlerinde ana akımı, <b>Kurumsal</b> iş ürünlerini sever. Konum etkisi ilk yıl boyunca tam güce ulaşır. Böylece aynı kategoride iki ürünün farklı müşterilere hitap eder ve birbirinin satışını yemez.</p><p><b>Bağlı marka</b> ("X, ana marka güvencesiyle") ana markanın %70'i güçle başlar, gücü zamanla ana markaya yaklaşır; ürünlerinde etkin güç %60 alt marka, %40 ana markadır. Lansman ve basın başarısı ya da fiyaskosu iki markayı birden etkiler.</p><p><b>Bağımsız marka</b> düşük güçle başlar (ilk yıl her ay tanıtım desteğiyle biraz büyür) ve tamamen kendi gücüyle satar. Ana markanın kişiliği, sosyal medya nabzı ve krizleri ona dokunmaz; onun hataları da ana markana yansımaz. Riskli bir kategoriye girerken ya da ucuz ürünlerin premium imajını zedelemesini istemediğinde işe yarar.</p><p>Geliştirme formundaki <b>Marka</b> seçimiyle yeni ürünü doğrudan bir alt markayla çıkarabilir, var olan ürünleri alt marka sayfasından taşıyabilirsin. Her alt markanın aylık bakım gideri vardır.</p>`)},
 {id:'social',c:'pazar',t:(LANG_EN?"Social media":'Sosyal medya'),go:'market:sosyal',b:(LANG_EN?`<p>Users, influencers, the tech press, rival CEOs and your own employees post about your company and products. The tone of product posts depends on satisfaction, bug count, freshness and value for money; employee posts depend on morale, press posts on major news. Some posts go viral and their impact multiplies.</p><p><b>Social sentiment</b> (−100 to +100) affects your brand (up to ±0.6) and your products' appeal (±5% for consumer products, half that for enterprise products) every month.</p><p>Negative posts from influencers, the press or viral ones need a response; if you don't reply within 5 days, sentiment drops. <b>Apologize and promise a fix</b> helps right away, but if the product's bugs don't drop 30% within 45 days, the promise counts as broken and the backlash grows. <b>Share the facts</b> works well against rival CEOs but can come across as defensive with users. A <b>witty reply</b> is a gamble: if it goes viral, sentiment and followers soar; if it backfires, it draws backlash. A Playful brand personality improves your odds; Trustworthy and Exclusive personalities lower them. A community manager or team handles standard replies for you.</p>`:`<p>Kullanıcılar, fenomenler, teknoloji basını, rakip CEO'lar ve kendi çalışanların şirketin ve ürünlerin hakkında paylaşım yapar. Ürün paylaşımlarının tonu memnuniyete, hata sayısına, güncelliğe ve fiyatın değerine bağlıdır; çalışan paylaşımları morale, basın paylaşımları önemli haberlere. Bazı paylaşımlar viral olur ve etkisi katlanır.</p><p><b>Sosyal nabız</b> (−100 ile +100) her ay markayı (en fazla ±0,6) ve ürünlerinin çekiciliğini (tüketici ürünlerinde ±%5, kurumsal ürünlerde yarısı) etkiler.</p><p>Fenomen, basın ya da viral olumsuz paylaşımlar yanıt bekler; 5 gün içinde yanıt vermezsen nabız düşer. <b>Özür dile, çözüm sözü ver</b> hemen iyi gelir ama 45 gün içinde ürünün hataları %30 azalmazsa söz tutulmamış sayılır ve tepki büyür. <b>Bilgi ver</b> rakip CEO'lara karşı iyi çalışır, kullanıcılara karşı savunmacı bulunabilir. <b>Esprili cevap</b> kumardır: viral olursa nabız ve takipçi fırlar, ters teperse tepki çeker; Eğlenceli marka kişiliği şansını artırır, Güvenilir ve Seçkin kişilik azaltır. Topluluk yöneticisi ya da ekibi standart yanıtları senin yerine verir.</p>`)},
 {id:'brandid',c:'pazar',t:(LANG_EN?"Logo and brand identity":'Logo ve marka kimliği'),go:'market:marka',b:(LANG_EN?`<p>Under Market → Brand identity you design your company's <b>logo</b> (shape, symbol, two colors, typeface), <b>slogan</b> and <b>brand personality</b>. The logo appears in the top bar, on the home screen, on your office wall, in your product list, in your trophy cabinet and in annual reports; the report also takes on the logo's main color.</p><p><b>Personality</b> shifts demand by segment: Innovative appeals to enthusiasts and the press, Exclusive to enthusiasts (budget buyers turn away), Playful to consumer products, Trustworthy to enterprise products and tenders, Eco-friendly (if your sustainability score is 55+) to all products, and People's brand to budget buyers. The strength of the effect depends on <b>recognition</b> and how well the logo <b>fits</b> the personality (colors, symbol, shape, typeface, slogan).</p><p>You can design it yourself, or hire a freelance designer or a famous agency; quality determines how fast recognition grows and how much it adds to your brand each month. Unreadable color pairings lower quality. A design scoring over 70 boosts your brand immediately; a big company's logo scoring under 45 becomes a laughingstock. You can change your identity at most once a year, and each change wipes out part of your recognition. Recognition grows over time, with marketers and with campaigns.</p>`:`<p>Pazar → Marka kimliği bölümünde şirketinin <b>logosunu</b> (şekil, sembol, iki renk, yazı karakteri), <b>sloganını</b> ve <b>marka kişiliğini</b> tasarlarsın. Logo üst çubukta, ana sayfada, ofisinin duvarında, ürün listende, ödül dolabında ve faaliyet raporlarında görünür; raporun rengi de logonun ana rengini alır.</p><p><b>Kişilik</b> segmentlere göre talebi değiştirir: Yenilikçi meraklıları ve basını, Seçkin meraklıları (fiyat odaklılar uzaklaşır), Eğlenceli tüketici ürünlerini, Güvenilir kurumsal ürünleri ve ihaleleri, Doğa dostu (sürdürülebilirlik puanı 55+ ise) tüm ürünleri, Halkın markası fiyat odaklıları sever. Etkinin gücü <b>tanınırlığa</b> ve logonun kişiliğe <b>uyumuna</b> (renkler, sembol, şekil, yazı, slogan) bağlıdır.</p><p>Tasarımı kendin yapabilir, serbest bir tasarımcıya ya da ünlü bir ajansa verebilirsin; kalite tanınırlığın ne hızla büyüdüğünü ve markana aylık katkısını belirler. Okunmayan renk eşleşmeleri kaliteyi düşürür. 70 üstü bir tasarım hemen marka kazandırır; büyük bir şirketin 45 altı logosu alay konusu olur. Kimliği yılda en fazla bir kez değiştirebilirsin ve her değişiklik tanınırlığın bir kısmını siler. Tanınırlık zamanla, pazarlamacılarla ve kampanyalarla artar.</p>`)},
 {id:'annrep',c:'finans',t:(LANG_EN?"Annual report":'Yıllık faaliyet raporu'),go:'fin:rapor',b:(LANG_EN?`<p>Every January, last year's annual report is prepared: revenue and profit, monthly charts, expense breakdown, valuation, cash, team, brand, market shares, product portfolio, products launched, research completed, awards and the year's key events. Reports are archived under Finance → Annual report; you can download each one as an HTML file with charts to print or share. You can also preview it while the year is still underway.</p><p>You choose the <b>tone of the CEO letter</b> that opens the report. A <b>transparent</b> letter boosts credibility; in a bad year the stock may dip a little, but the board appreciates the honesty. An <b>optimistic</b> letter supports the brand and stock in a good year, but dressing up a bad year sharply hurts credibility and can draw a press backlash. A <b>cautious</b> letter lowers expectations; if the next year goes well, you'll have beaten them.</p><p><b>Reporting credibility</b> affects funding round valuations (−12% to +8%) and the board's confidence; it drifts back toward 60 over time. <b>Design</b> sets the report's look: professional and award-winning agency designs add to your brand, and with an award-winning agency design the report can even win a design award. If you like, reports can be published automatically in the tone you choose.</p><p><b>Year in review:</b> once the report is published, the year's highlights play as story cards: revenue, best month, products, team, research and awards, the most loved social media post, company value and the year's personality. Tap or use the arrow keys to advance; at the end you can download the summary card as an SVG. You can rewatch past years' reviews from the report page or turn them off in settings.</p>`:`<p>Her ocakta geçen yılın faaliyet raporu hazırlanır: gelir ve kâr, aylık grafikler, gider dağılımı, değerleme, nakit, ekip, marka, pazar payları, ürün portföyü, çıkan ürünler, tamamlanan araştırmalar, ödüller ve yılın önemli olayları. Raporlar Finans → Faaliyet raporu bölümünde arşivlenir; her birini grafikli bir HTML dosyası olarak indirip yazdırabilir ya da paylaşabilirsin. Yıl devam ederken önizlemesini de görebilirsin.</p><p>Raporun açılışındaki <b>CEO mektubunun tonunu</b> sen seçersin. <b>Şeffaf</b> mektup güvenilirliği artırır; kötü bir yılda hisse biraz düşse de kurul dürüstlüğü takdir eder. <b>İyimser</b> mektup iyi bir yılda markayı ve hisseyi destekler, ama kötü bir yılı parlak göstermek güvenilirliği sert düşürür ve basının tepkisini çekebilir. <b>Temkinli</b> mektup beklentileri düşürür; ertesi yıl iyi geçerse beklentileri aşmış olursun.</p><p><b>Raporlama güvenilirliği</b> yatırım turlarının değerlemesini (−%12 ile +%8 arası) ve yönetim kurulunun güvenini etkiler; zamanla 60'a doğru döner. <b>Tasarım</b> raporun görünümünü belirler: profesyonel ve ödüllü ajans tasarımları markaya katkı sağlar, ödüllü ajans tasarımıyla rapor tasarım ödülü de kazanabilirsin. İstersen raporları seçtiğin tonla otomatik yayımlatabilirsin.</p><p><b>Yıl sonu özeti:</b> rapor yayımlanınca yılın özeti hikâye kartlarıyla oynatılır: gelir, en iyi ay, ürünler, ekip, araştırma ve ödüller, sosyal medyanın en sevilen paylaşımı, şirket değeri ve yılın kişiliği. Dokunarak ya da ok tuşlarıyla ilerlersin; sonunda özet kartını SVG olarak indirebilirsin. Geçmiş yılların özetini rapor sayfasından yeniden izleyebilir, ayarlardan kapatabilirsin.</p>`)},
 {id:'cash',c:'finans',t:(LANG_EN?"Cash and valuation":'Nakit ve değerleme'),go:'fin',b:(LANG_EN?`<p>Valuation is calculated from cash, recent months' operating profit, brand, inventory and factories. The stock portfolio and real estate are added at 90% of their market value and the media company at its sale value; their rent, dividends and publication income are kept out of profit because they are reflected in the asset values. If your cash stays negative for three months in a row, you go bankrupt. Warnings on Company → CEO desk show how many months your cash will last.</p>`:`<p>Değerleme nakit, son ayların faaliyet kârı, marka, stok ve fabrikalardan hesaplanır. Hisse portföyü ve gayrimenkul piyasa değerinin %90'ıyla, medya şirketi satış değeriyle eklenir; bunların kira, temettü ve yayın gelirleri ise kâra değil varlık değerine yansıdığı için kârdan ayrı tutulur. Nakit üç ay üst üste eksiye düşerse iflas edersin. Şirket → CEO masasındaki uyarılar nakdin kaç ay yeteceğini gösterir.</p>`)},
 {id:'funding',c:'finans',t:(LANG_EN?"Funding rounds and IPO":'Yatırım turları ve halka arz'),go:'fin',b:(LANG_EN?`<p>Angel, Series A, B, C and the IPO each require certain valuation thresholds; every round brings cash but dilutes your stake. At a public company the share price moves with quarterly results; miss expectations repeatedly and the board takes action.</p>`:`<p>Melek yatırımcı, Seri A, B, C ve halka arz için belirli değerleme eşikleri gerekir; her tur nakit getirir ama hisse payını sulandırır. Halka açık şirkette hisse fiyatı çeyrek sonuçlarına göre oynar; beklentiyi üst üste kaçırırsan yönetim kurulu harekete geçer.</p>`)},
 {id:'loan',c:'finans',t:(LANG_EN?"Loans":'Krediler'),go:'fin',b:(LANG_EN?`<p>You can take out a bank loan of up to 30% of your valuation; the monthly interest varies with the policy rate (about 1–1.75%). You can repay the debt at any time.</p>`:`<p>Değerlemenin %30'una kadar banka kredisi çekebilirsin; aylık faiz politika faizine göre değişir (yaklaşık %1–1,75). Borcu istediğin zaman geri ödeyebilirsin.</p>`)},
 {id:'founder',c:'finans',t:(LANG_EN?"Founder and personal life":'Kurucu ve kişisel hayat'),go:'fin:kurucu',b:(LANG_EN?`<p>As founder you set your salary and manage your personal wealth: house, car, yacht, art collection, angel investments, donations. Life balance and prestige affect your personal life. The more shares you sell, the stronger the board becomes; if you lose its confidence, you can be removed.</p>`:`<p>Kurucu olarak maaşını belirler, kişisel servetini yönetirsin: ev, araba, yat, sanat koleksiyonu, melek yatırım, bağış. Yaşam dengesi ve prestij kişisel hayatını etkiler. Hisse sattıkça yönetim kurulu güçlenir; güvenini kaybedersen görevden alınabilirsin.</p>`)},

 {id:'vc',c:'finans',t:(LANG_EN?"Corporate venture fund":'Kurumsal girişim fonu'),go:'fin:girisim',b:(LANG_EN?`<p>Once your valuation passes $10M, startups bring you investment offers every month (seed, Series A, Series B). Their true potential is hidden: the team score is an estimate that becomes clear if you pay for <b>due diligence</b>.</p><ul><li>Most startups fail or stagnate; a few return more than 10x.</li><li>When a startup raises a new round, you can make a follow-on investment within 30 days to keep your stake; otherwise you get diluted.</li><li>After 18 months startups may be sold to a rival; you receive cash for your share.</li><li>Stakes of 20%+ in your own product categories add +3% appeal to your products (up to +9%).</li><li>If you fully acquire a startup you hold 15%+ of, its team joins your company and your next product in that category is stronger.</li></ul><p>80% of the portfolio's value is added to your company valuation.</p>`:`<p>Değerlemen $10M'u geçince girişimler her ay yatırım teklifi getirir (tohum, Seri A, Seri B). Gerçek potansiyelleri gizlidir: ekip puanı bir tahmindir, <b>inceleme</b> ücreti öderseniz netleşir.</p><ul><li>Çoğu girişim batar ya da yerinde sayar; birkaçı 10 katın üstünde kazandırır.</li><li>Girişim yeni tur topladığında 30 gün içinde ek yatırım yapıp payını koruyabilirsin; yapmazsan payın sulanır.</li><li>18 aydan sonra girişimler bir rakibe satılabilir; payına düşen nakit gelir.</li><li>Kendi ürün kategorindeki %20+ paylar ürünlerine +%3 çekicilik katar (en fazla +%9).</li><li>%15+ paylı girişimin tamamını alırsan ekibi şirketine katılır ve o kategorideki sonraki ürünün daha güçlü olur.</li></ul><p>Portföy değerinin %80'i şirket değerlemene eklenir.</p>`)},
 {id:'serial',c:'finans',t:(LANG_EN?"Serial entrepreneur":'Seri girişimci'),go:'fin:kurucu',b:(LANG_EN?`<p>When your company is sold, you are removed, or it goes under, the result is recorded in your <b>career</b> (stored in this browser). After at least 2 years and a $5M valuation, you can also sell the company to a fund yourself and exit.</p><p>If you start a new game as a <b>Serial entrepreneur</b>:</p><ul><li>You invest as much of your personal wealth as you like in the new company; the rest stays as your personal wealth.</li><li>Big exits earn <b>fame</b>: brand, candidate quality and funding round amounts increase.</li><li>The three best employees from your previous company follow you as loyal staff.</li></ul>`:`<p>Şirketin satıldığında, görevden alındığında ya da battığında sonuç <b>kariyerine</b> yazılır (bu tarayıcıda saklanır). En az 2 yıl ve $5M değerlemeden sonra şirketi kendin de bir fona satıp çıkabilirsin.</p><p>Yeni oyunda <b>Seri girişimci</b> olarak başlarsan:</p><ul><li>Kişisel servetinden istediğin kadarını yeni şirkete yatırırsın; geri kalanı kişisel servetin olarak kalır.</li><li>Büyük çıkışlar <b>ün</b> kazandırır: marka, aday kalitesi ve yatırım turu tutarları artar.</li><li>Önceki şirketinin en iyi üç çalışanı sadık olarak seninle gelir.</li></ul>`)},
 {id:'scn',c:'diger',t:(LANG_EN?"Scenarios and difficulty":'Senaryolar ve zorluk'),b:(LANG_EN?`<p>In a new game you can choose free play or goal-based scenarios. Difficulty sets starting cash, rivals' technology and aggressiveness, event frequency, demand and component prices; with "Custom" you can pick each setting individually.</p>`:`<p>Yeni oyunda serbest oyun ya da hedefli senaryolar seçebilirsin. Zorluk başlangıç nakdini, rakiplerin teknolojisini ve saldırganlığını, olay sıklığını, talebi ve parça fiyatlarını belirler; "Özel" ile her ayarı tek tek seçebilirsin.</p>`)},
 {id:'ach',c:'diger',t:(LANG_EN?"Achievements":'Başarımlar'),go:'stats:basarim',b:(LANG_EN?`<p>Achievements under Company → Achievements are milestones: your first million, your own chip, unicorn, labor peace and more. Unlocked achievements are saved in this browser across all your games.</p>`:`<p>Şirket → Başarımlar bölümündeki başarımlar kilometre taşlarıdır: ilk milyon, kendi çipin, unicorn, sosyal barış gibi. Açtığın başarımlar bu tarayıcıda bütün oyunların için saklanır.</p>`)},
 {id:'lb',c:'diger',t:(LANG_EN?"Leaderboard":'Liderlik tablosu'),go:'stats:lider',b:(LANG_EN?`<p>In free play your highest valuation is submitted automatically at the end of each month; in scenarios your best result is submitted on completion. To see the leaderboard you must open the game while signed in to claude.ai; to submit scores, the person who shared the page must have given you contributor access.</p>`:`<p>Serbest oyunda en yüksek değerlemen her ay sonu, senaryolarda en iyi sonucun tamamlandığında otomatik gönderilir. Tabloyu görebilmek için oyunu claude.ai'de oturum açıkken açmalısın; skor göndermek için sayfayı paylaşan kişinin sana katkı izni vermiş olması gerekir.</p>`)},
 {id:'weekly',c:'diger',t:(LANG_EN?"Weekly challenge":'Haftanın meydan okuması'),go:'stats:lider',b:(LANG_EN?`<p>Every calendar week everyone plays from the same start: the same cash, the same pre-completed research, the same two world conditions (for example a chip shortage, aggressive rivals) and the same random seed. Rivals, candidates and the event schedule are largely the same; your decisions make the difference.</p><p>After 3 game years your valuation becomes your score and goes on the weekly leaderboard. You can try as many times as you like; your best result counts. When the challenge ends, you can keep playing the same company in free play.</p>`:`<p>Her takvim haftası herkes aynı başlangıçla oynar: aynı nakit, aynı hazır araştırma, aynı iki dünya koşulu (örneğin çip kıtlığı, saldırgan rakipler) ve aynı rastgelelik tohumu. Rakipler, adaylar ve olay takvimi büyük ölçüde aynı gelir; farkı senin kararların yaratır.</p><p>3 oyun yılı sonunda değerlemen skorun olur ve haftalık tabloya girer. İstediğin kadar deneyebilirsin; en iyi sonucun sayılır. Meydan okuma bitince aynı şirketle serbest oyunda devam edebilirsin.</p>`)},
 {id:'history',c:'diger',t:(LANG_EN?"History and news":'Tarihçe ve haberler'),go:'stats',b:(LANG_EN?`<p>The History section of Company has charts of revenue, profit, valuation and market share, comparisons with rivals and your company's timeline. In the news archive you can filter stories by topic, type and keyword.</p>`:`<p>Şirket bölümünün Tarihçe kısmında gelir, kâr, değerleme ve pazar payı grafikleri, rakiplerle karşılaştırma ve şirketinin zaman çizelgesi bulunur. Haber arşivindeki haberleri konuya, türe ve kelimeye göre süzebilirsin.</p>`)},
];
const ENCD=Object.fromEntries(ENC.map(a=>[a.id,a]));
const helpBtn=k=>(LANG_EN?`<button class="btn sm ghost helpq" data-act="help" data-k="${k}" aria-label="Open in Encyclopedia: ${esc(ENCD[k]?ENCD[k].t:'')}" title="Encyclopedia">?</button>`:`<button class="btn sm ghost helpq" data-act="help" data-k="${k}" aria-label="Ansiklopedide aç: ${esc(ENCD[k]?ENCD[k].t:'')}" title="Ansiklopedi">?</button>`);
const encText=a=>(a.t+' '+a.b.replace(/<[^>]+>/g,' ')).toLocaleLowerCase(LOC);
function encListHTML(){const q=(UI.encQ||'').trim().toLocaleLowerCase(LOC),cur=UI.encA||'goal';
  return ENC_CATS.map(([c,n])=>{const items=ENC.filter(a=>a.c===c&&(!q||encText(a).includes(q)));if(!items.length)return '';
    return `<div class="enc-cat">${n}</div>${items.map(a=>`<button class="enc-item${a.id===cur?' on':''}" data-act="help" data-k="${a.id}" aria-current="${a.id===cur}">${a.t}</button>`).join('')}`;}).join('')||(LANG_EN?"<div class=\"small muted\" style=\"padding:8px\">No results.</div>":'<div class="small muted" style="padding:8px">Sonuç yok.</div>');}
function encBody(){const a=ENCD[UI.encA]||ENC[0],cat=ENC_CATS.find(x=>x[0]===a.c)[1];
  return `<div class="eyebrow">${cat}</div><h2 style="margin:2px 0 8px">${a.t}</h2><div class="enc-art">${a.b}</div>${a.go?(LANG_EN?`<div class="row" style="margin-top:12px"><button class="btn sm primary" data-act="helpgo" data-k="${a.id}">Go to related screen</button></div>`:`<div class="row" style="margin-top:12px"><button class="btn sm primary" data-act="helpgo" data-k="${a.id}">İlgili ekrana git</button></div>`):''}`;}

